{
  "name": "Structured Credit CRM",
  "description": "A CRM system to centralize information, monitoring, and events for structured credit operations, built with React and Tailwind CSS."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useMemo } from 'react';
import type { Operation, Task } from './types';
import { Page } from './types';
import { initialOperations } from './data/mockData';
import { generateTasksForOperation } from './utils/taskEngine';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import { PlusCircleIcon } from './components/icons/Icons';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>(initialOperations);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => generateTasksForOperation(op));
  }, [operations]);

  const handleSelectOperation = (id: number) => {
    setSelectedOperationId(id);
    setCurrentPage(Page.DETAIL);
  };

  const handleReturnToOverview = () => {
    setSelectedOperationId(null);
    setCurrentPage(Page.OVERVIEW);
  };

  const handleAddOperation = (newOperation: Omit<Operation, 'id'>) => {
    setOperations(prev => [
      ...prev,
      { ...newOperation, id: Date.now() }
    ]);
  };

  const handleUpdateOperation = (updatedOperation: Operation) => {
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800">
      <header className="bg-white shadow-md">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <h1 className="text-2xl font-bold text-gray-700 cursor-pointer" onClick={handleReturnToOverview}>
              CRM de Crédito Estruturado
            </h1>
            {currentPage === Page.DETAIL && (
                <button
                onClick={handleReturnToOverview}
                className="text-sm text-blue-600 hover:text-blue-800 font-medium"
                >
                &larr; Voltar ao Resumo
                </button>
            )}
          </div>
        </div>
      </header>
      <main className="container mx-auto p-4 sm:p-6 lg:p-8">
        {currentPage === Page.OVERVIEW ? (
          <OverviewDashboard
            operations={operations}
            allTasks={allTasks}
            onSelectOperation={handleSelectOperation}
            onAddOperation={handleAddOperation}
          />
        ) : selectedOperation ? (
          <OperationDetail 
            operation={selectedOperation}
            onUpdateOperation={handleUpdateOperation}
          />
        ) : (
          <div>
            <p>Operação não encontrada. Por favor, retorne ao resumo.</p>
            <button onClick={handleReturnToOverview} className="mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
              Voltar ao Resumo
            </button>
          </div>
        )}
      </main>
      <footer className="text-center py-4 mt-8 text-gray-500 text-sm">
        <p>&copy; {new Date().getFullYear()} Structured Credit CRM. Todos os direitos reservados.</p>
      </footer>
    </div>
  );
};

export default App;

export interface Project {
  id: number;
  name: string;
}

export interface Guarantee {
  id: number;
  name: string;
}

export interface Covenants {
  ltv: number | null;
  dscr: number | null;
}

export interface DefaultMonitoring {
  news: boolean;
  fiiReport: boolean;
  operationalInfo: boolean;
  receivablesPortfolio: boolean;
  monthlyConstructionReport: boolean;
  monthlyCommercialInfo: boolean;
  speDfs: boolean;
}

export interface Event {
  id: number;
  date: string; // ISO string
  type: string;
  title: string;
  description: string;
  registeredBy: string;
  nextSteps: string;
}

export interface TaskRule {
  id: number;
  name: string;
  frequency: 'Diário' | 'Semanal' | 'Quinzenal' | 'Mensal' | 'Trimestral' | 'Semestral' | 'Anual';
  startDate: string; // ISO string
  endDate: string; // ISO string
  description: string;
}

export enum TaskStatus {
  PENDING = 'Pendente',
  OVERDUE = 'Atrasada',
  COMPLETED = 'Concluída'
}

export interface Task {
  id: string; // e.g., "op1-rule2-2024-08-15"
  operationId: number;
  ruleId: number;
  ruleName: string;
  dueDate: string; // ISO string
  status: TaskStatus;
}

export interface Operation {
  id: number;
  name: string;
  projects: Project[];
  operationType: string;
  guarantees: Guarantee[];
  maturityDate: string; // ISO string
  responsibleAnalyst: string;
  reviewFrequency: string;
  callFrequency: string;
  dfFrequency: string;
  defaultMonitoring: DefaultMonitoring;
  covenants: Covenants;
  events: Event[];
  taskRules: TaskRule[];
}

export enum Page {
  OVERVIEW = 'overview',
  DETAIL = 'detail',
}

