import type { Operation, Task, TaskRule } from '../types';
import { TaskStatus } from '../types';

const getNextDate = (currentDate: Date, frequency: TaskRule['frequency']): Date => {
  const next = new Date(currentDate);
  switch (frequency) {
    case 'Diário':
      next.setDate(next.getDate() + 1);
      break;
    case 'Semanal':
      next.setDate(next.getDate() + 7);
      break;
    case 'Quinzenal':
      next.setDate(next.getDate() + 15);
      break;
    case 'Mensal':
      next.setMonth(next.getMonth() + 1);
      break;
    case 'Trimestral':
      next.setMonth(next.getMonth() + 3);
      break;
    case 'Semestral':
      next.setMonth(next.getMonth() + 6);
      break;
    case 'Anual':
      next.setFullYear(next.getFullYear() + 1);
      break;
  }
  return next;
};

export const generateTasksForRule = (operationId: number, rule: TaskRule): Task[] => {
  const tasks: Task[] = [];
  let currentDate = new Date(rule.startDate);
  const endDate = new Date(rule.endDate);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  while (currentDate <= endDate) {
    const dueDate = new Date(currentDate);
    // Ignore tasks with due date far in the past unless they are relevant for being overdue
    // For simplicity, we generate all future tasks. UI can filter them.

    // We can decide to only generate tasks up to a certain point in the future to avoid large arrays.
    // e.g., for the next 2 years. For this CRM, generating all is fine.

    const task: Task = {
      id: `op${operationId}-rule${rule.id}-${dueDate.toISOString().split('T')[0]}`,
      operationId: operationId,
      ruleId: rule.id,
      ruleName: rule.name,
      dueDate: dueDate.toISOString(),
      status: TaskStatus.PENDING,
    };

    if (dueDate < today) {
        task.status = TaskStatus.OVERDUE;
    }

    tasks.push(task);
    currentDate = getNextDate(currentDate, rule.frequency);
  }

  return tasks;
};


export const generateTasksForOperation = (operation: Operation): Task[] => {
  return operation.taskRules.flatMap(rule => generateTasksForRule(operation.id, rule));
};

export const getOverdueTasksCount = (tasks: Task[]): number => {
    return tasks.filter(task => task.status === TaskStatus.OVERDUE).length;
}

import React, { useState, useMemo } from 'react';
import type { Operation, Task } from '../types';
import { TaskStatus } from '../types';
import OperationForm from './OperationForm';
import AnalystCalendar from './AnalystCalendar';
import { PlusCircleIcon, EyeIcon } from './icons/Icons';
import { getOverdueTasksCount } from '../utils/taskEngine';

interface OverviewDashboardProps {
  operations: Operation[];
  allTasks: Task[];
  onSelectOperation: (id: number) => void;
  onAddOperation: (newOperation: Omit<Operation, 'id'>) => void;
}

const OverviewDashboard: React.FC<OverviewDashboardProps> = ({ operations, allTasks, onSelectOperation, onAddOperation }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);

  const operationsWithTasks = useMemo(() => {
    return operations.map(op => {
      const opTasks = allTasks.filter(task => task.operationId === op.id);
      const overdueCount = getOverdueTasksCount(opTasks);
      return { ...op, overdueCount };
    });
  }, [operations, allTasks]);

  return (
    <div className="space-y-8">
      {isFormOpen && (
        <OperationForm 
            onClose={() => setIsFormOpen(false)} 
            onSave={onAddOperation} 
        />
      )}

      {/* Operations Summary */}
      <div className="bg-white p-6 rounded-lg shadow-lg">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold text-gray-700">Resumo de Operações</h2>
          <button
            onClick={() => setIsFormOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition duration-300"
          >
            <PlusCircleIcon className="w-5 h-5" />
            <span>Adicionar Operação</span>
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nome da Operação</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Projetos</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tarefas Atrasadas</th>
                <th scope="col" className="relative px-6 py-3">
                  <span className="sr-only">Detalhes</span>
                </th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {operationsWithTasks.map((op) => (
                <tr key={op.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{op.name}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{op.projects.map(p => p.name).join(', ')}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm">
                    <span className={op.overdueCount > 0 ? 'text-red-600 font-bold' : 'text-green-600'}>
                      {op.overdueCount}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <button onClick={() => onSelectOperation(op.id)} className="flex items-center gap-2 text-blue-600 hover:text-blue-900">
                      <EyeIcon className="w-5 h-5" /> Ver Detalhes
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
            {operations.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                    Nenhuma operação cadastrada.
                </div>
            )}
        </div>
      </div>

      {/* Analyst Calendar */}
      <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-xl font-bold text-gray-700 mb-4">Calendário do Analista (Mês Atual)</h2>
        <AnalystCalendar tasks={allTasks.filter(t => t.status !== TaskStatus.COMPLETED)} operations={operations} />
      </div>
    </div>
  );
};

export default OverviewDashboard;

import React, { useState, useMemo } from 'react';
import type { Operation, Event, Task, TaskRule } from '../types';
import { TaskStatus } from '../types';
import { generateTasksForOperation } from '../utils/taskEngine';
import { PlusCircleIcon, PencilIcon, CheckCircleIcon, EyeIcon } from './icons/Icons';
import EventForm from './EventForm';
import TaskRuleForm from './TaskRuleForm';

interface OperationDetailProps {
  operation: Operation;
  onUpdateOperation: (updatedOperation: Operation) => void;
}

const InfoCard: React.FC<{ title: string; children: React.ReactNode; }> = ({ title, children }) => (
    <div className="bg-gray-50 p-3 rounded-md">
        <h4 className="text-xs text-gray-500 font-semibold uppercase">{title}</h4>
        <p className="text-gray-800 font-medium">{children}</p>
    </div>
);


const OperationDetail: React.FC<OperationDetailProps> = ({ operation, onUpdateOperation }) => {
    const [isEventFormOpen, setIsEventFormOpen] = useState(false);
    const [isTaskRuleFormOpen, setIsTaskRuleFormOpen] = useState(false);
    const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
    const [expandedEventId, setExpandedEventId] = useState<number | null>(null);

    const tasks = useMemo(() => generateTasksForOperation(operation), [operation]);

    const activeTasks = useMemo(() => {
        return tasks.filter(t => t.status === TaskStatus.PENDING || t.status === TaskStatus.OVERDUE)
            .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks]);

    const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
        const updatedOperation = {
            ...operation,
            events: [...operation.events, { ...newEvent, id: Date.now() }]
        };
        onUpdateOperation(updatedOperation);

        if (taskToComplete) {
            // This is a placeholder for updating task status.
            // In a real app, you'd save this to a DB and re-fetch.
            // For this UI, we assume completion upon event creation.
            console.log(`Task ${taskToComplete.id} marked as complete.`);
            setTaskToComplete(null);
        }
    };

    const handleAddTaskRule = (newTaskRule: Omit<TaskRule, 'id'>) => {
        const updatedOperation = {
            ...operation,
            taskRules: [...operation.taskRules, {...newTaskRule, id: Date.now()}]
        };
        onUpdateOperation(updatedOperation);
    };

    const handleCompleteTaskClick = (task: Task) => {
        setTaskToComplete(task);
        setIsEventFormOpen(true);
    };

    return (
        <div className="space-y-8">
            {isEventFormOpen && (
                <EventForm 
                    onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                    onSave={handleAddEvent}
                    analystName={operation.responsibleAnalyst}
                    prefilledTitle={taskToComplete ? `Conclusão: ${taskToComplete.ruleName}` : ''}
                />
            )}
            {isTaskRuleFormOpen && (
                <TaskRuleForm
                    onClose={() => setIsTaskRuleFormOpen(false)}
                    onSave={handleAddTaskRule}
                />
            )}

            {/* Header */}
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">{operation.name}</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <InfoCard title="Projetos">{operation.projects.map(p => p.name).join(', ')}</InfoCard>
                    <InfoCard title="Garantias">{operation.guarantees.map(g => g.name).join(', ')}</InfoCard>
                    <InfoCard title="Covenant LTV">{operation.covenants.ltv ?? 'N/A'}</InfoCard>
                    <InfoCard title="Covenant DSCR">{operation.covenants.dscr ?? 'N/A'}</InfoCard>
                </div>
            </div>

            {/* Events */}
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold text-gray-700">Histórico de Eventos</h3>
                    <button onClick={() => setIsEventFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                        <PlusCircleIcon className="w-5 h-5"/>
                        Adicionar Evento
                    </button>
                </div>
                <div className="space-y-2">
                     {operation.events.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map(event => (
                        <div key={event.id} className="border border-gray-200 rounded-lg p-4">
                            <div className="grid grid-cols-4 md:grid-cols-5 gap-4 items-center">
                                <div className="text-sm font-medium text-gray-600">{new Date(event.date).toLocaleDateString('pt-BR')}</div>
                                <div className="text-sm text-gray-800"><span className="font-semibold">{event.type}</span></div>
                                <div className="col-span-2 md:col-span-2 text-sm text-gray-800">{event.title}</div>
                                <div className="text-right">
                                    <button onClick={() => setExpandedEventId(expandedEventId === event.id ? null : event.id)} className="text-blue-600 hover:text-blue-800 text-sm">
                                        {expandedEventId === event.id ? 'Ver Menos' : 'Ver Mais'}
                                    </button>
                                </div>
                            </div>
                            {expandedEventId === event.id && (
                                <div className="mt-4 pt-4 border-t border-gray-200 space-y-3 text-sm">
                                    <p><strong className="font-semibold text-gray-600">Descrição:</strong> {event.description}</p>
                                    <p><strong className="font-semibold text-gray-600">Registrado por:</strong> {event.registeredBy}</p>
                                    <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>
                                </div>
                            )}
                        </div>
                     ))}
                     {operation.events.length === 0 && <p className="text-center text-gray-500 py-4">Nenhum evento registrado.</p>}
                </div>
            </div>

            {/* Task Management */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                {/* Task Rules */}
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-gray-700">Regras de Tarefas</h3>
                         <button onClick={() => setIsTaskRuleFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm">
                            <PlusCircleIcon className="w-5 h-5"/>
                            Nova Regra
                        </button>
                    </div>
                    <div className="space-y-3">
                        {operation.taskRules.map(rule => (
                            <div key={rule.id} className="p-3 bg-gray-50 rounded-md">
                                <p className="font-semibold text-gray-800">{rule.name} <span className="text-xs font-normal text-white bg-blue-500 px-2 py-0.5 rounded-full">{rule.frequency}</span></p>
                                <p className="text-sm text-gray-600">{rule.description}</p>
                                <p className="text-xs text-gray-400 mt-1">
                                    {new Date(rule.startDate).toLocaleDateString('pt-BR')} até {new Date(rule.endDate).toLocaleDateString('pt-BR')}
                                </p>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>

                {/* Task Execution */}
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <h3 className="text-xl font-bold text-gray-700 mb-4">Execução de Tarefas</h3>
                    <div className="space-y-2 max-h-96 overflow-y-auto">
                       {activeTasks.map(task => (
                           <div key={task.id} className={`p-3 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                               <div>
                                   <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                   <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-700'}`}>
                                       Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                   </p>
                               </div>
                               <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                   <CheckCircleIcon className="w-4 h-4" />
                                   Completar
                               </button>
                           </div>
                       ))}
                        {activeTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa pendente.</p>}
                    </div>
                </div>
            </div>

        </div>
    );
};

export default OperationDetail;

import React, { useEffect } from 'react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  useEffect(() => {
    const handleEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };
    document.addEventListener('keydown', handleEscape);
    return () => {
      document.removeEventListener('keydown', handleEscape);
    };
  }, [onClose]);

  if (!isOpen) return null;

  return (
    <div
      className="fixed inset-0 bg-black bg-opacity-50 z-50 flex justify-center items-center"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-lg shadow-xl w-full max-w-2xl max-h-[90vh] overflow-y-auto p-6 relative"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex justify-between items-center pb-4 border-b">
          <h3 className="text-lg font-semibold text-gray-900">{title}</h3>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600"
            aria-label="Fechar modal"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>
        <div className="mt-4">
          {children}
        </div>
      </div>
    </div>
  );
};

export default Modal;

