    }, [tasks, operation.events]);

    const uniqueEventTypes = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.type))], [operation.events]);
    const uniqueRegisteredBy = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.registeredBy))], [operation.events]);

    const filteredEvents = useMemo(() => {
        return [...operation.events]
            .filter(event => {
                if (!dateFilter.start && !dateFilter.end) return true;
                const eventDate = new Date(event.date);
                eventDate.setHours(0,0,0,0);
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && eventDate < startDate) return false;
                if (endDate && eventDate > endDate) return false;
                return true;
            })
            .filter(event => typeFilter === 'Todos' || event.type === typeFilter)
            .filter(event => personFilter === 'Todos' || event.registeredBy === personFilter)
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.events, dateFilter, typeFilter, personFilter]);

    const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
        const eventToSave: Partial<Event> = { ...newEvent };
        if (taskToComplete) {
            eventToSave.completedTaskId = taskToComplete.id;
        }

        const updatedOperation = {
            ...operation,
            events: [...operation.events, { ...eventToSave, id: Date.now() } as Event]
        };
        onUpdateOperation(updatedOperation);

        setTaskToComplete(null);
        setIsEventFormOpen(false);
    };

    const handleAddTaskRule = (newTaskRule: Omit<TaskRule, 'id'>) => {
        const updatedOperation = {
            ...operation,
            taskRules: [...operation.taskRules, {...newTaskRule, id: Date.now()}]
        };
        onUpdateOperation(updatedOperation);
        setIsTaskRuleFormOpen(false);
    };

    const handleCompleteTaskClick = (task: Task) => {
        setTaskToComplete(task);
        setIsEventFormOpen(true);
    };

    const handleViewEventClick = (taskId: string) => {
        const completionEvent = operation.events.find(e => e.completedTaskId === taskId);
        if (completionEvent) {
            setExpandedEventId(completionEvent.id);
            const eventElement = eventRefs.current[completionEvent.id];
            if (eventElement) {
                eventElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }

    return (
        <div className="space-y-8">
            {isEventFormOpen && (
                <EventForm 
                    onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                    onSave={handleAddEvent}
                    analystName={operation.responsibleAnalyst}
                    prefilledTitle={taskToComplete ? `Conclusão: ${taskToComplete.ruleName}` : ''}
                />
            )}
            {isTaskRuleFormOpen && (
                <TaskRuleForm
                    onClose={() => setIsTaskRuleFormOpen(false)}
                    onSave={handleAddTaskRule}
                />
            )}

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">{operation.name}</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <InfoCard title="Projetos">{operation.projects.map(p => p.name).join(', ')}</InfoCard>
                    <InfoCard title="Garantias">{operation.guarantees.map(g => g.name).join(', ')}</InfoCard>
                    <InfoCard title="Covenant LTV">{operation.covenants.ltv ?? 'N/A'}</InfoCard>
                    <InfoCard title="Covenant DSCR">{operation.covenants.dscr ?? 'N/A'}</InfoCard>
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold text-gray-700">Histórico de Eventos</h3>
                    <button onClick={() => setIsEventFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                        <PlusCircleIcon className="w-5 h-5"/> Adicionar Evento
                    </button>
                </div>

                <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4">
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div>
                            <label htmlFor="start-date" className="text-sm font-medium text-gray-700">De:</label>
                            <input type="date" id="start-date" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="end-date" className="text-sm font-medium text-gray-700">Até:</label>
                            <input type="date" id="end-date" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="type-filter" className="text-sm font-medium text-gray-700">Tipo:</label>
                            <select id="type-filter" value={typeFilter} onChange={e => setTypeFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueEventTypes.map(type => <option key={type} value={type}>{type}</option>)}
                            </select>
                        </div>
                        <div>
                            <label htmlFor="person-filter" className="text-sm font-medium text-gray-700">Responsável:</label>
                            <select id="person-filter" value={personFilter} onChange={e => setPersonFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueRegisteredBy.map(name => <option key={name} value={name}>{name}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="space-y-2">
                     {filteredEvents.map(event => (
                        <div key={event.id} ref={el => { if(el) eventRefs.current[event.id] = el; }} className={`border border-gray-200 rounded-lg p-4 transition-all duration-300 ${expandedEventId === event.id ? 'bg-blue-50 ring-2 ring-blue-300' : ''}`}>
                            <div className="grid grid-cols-4 md:grid-cols-5 gap-4 items-center">
                                <div className="text-sm font-medium text-gray-600">{new Date(event.date).toLocaleDateString('pt-BR')}</div>
                                <div className="text-sm text-gray-800"><span className="font-semibold">{event.type}</span></div>
                                <div className="col-span-2 md:col-span-2 text-sm text-gray-800">{event.title}</div>
                                <div className="text-right">
                                    <button onClick={() => setExpandedEventId(expandedEventId === event.id ? null : event.id)} className="text-blue-600 hover:text-blue-800 text-sm">
                                        {expandedEventId === event.id ? 'Ver Menos' : 'Ver Mais'}
                                    </button>
                                </div>
                            </div>
                            {expandedEventId === event.id && (
                                <div className="mt-4 pt-4 border-t border-gray-200 space-y-3 text-sm text-gray-700">
                                    <p><strong className="font-semibold text-gray-600">Descrição:</strong> {event.description}</p>
                                    <p><strong className="font-semibold text-gray-600">Registrado por:</strong> {event.registeredBy}</p>
                                    <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>
                                    {event.completedTaskId && <p className="text-xs text-gray-500 italic pt-2">Este evento concluiu a tarefa ID: {event.completedTaskId}</p>}
                                </div>
                            )}
                        </div>
                     ))}
                     {filteredEvents.length === 0 && <p className="text-center text-gray-500 py-4">Nenhum evento encontrado para os filtros selecionados.</p>}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <h3 className="text-xl font-bold text-gray-700 mb-4">Execução de Tarefas</h3>
                    <div className="space-y-2 max-h-96 overflow-y-auto">
                       {activeTasks.map(task => (
                           <div key={task.id} className={`p-3 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                               <div>
                                   <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                   <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-700'}`}>
                                       Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                   </p>
                               </div>
                               <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                   <CheckCircleIcon className="w-4 h-4" /> Completar
                               </button>
                           </div>
                       ))}
                        {activeTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa pendente.</p>}
                    </div>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-lg">
                     <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-gray-700">Regras de Tarefas</h3>
                         <button onClick={() => setIsTaskRuleFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm">
                            <PlusCircleIcon className="w-5 h-5"/> Nova Regra
                        </button>
                    </div>
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {operation.taskRules.map(rule => (
                            <div key={rule.id} className="p-3 bg-gray-50 rounded-md">
                                <p className="font-semibold text-gray-800">{rule.name} <span className="text-xs font-normal text-white bg-blue-500 px-2 py-0.5 rounded-full">{rule.frequency}</span></p>
                                <p className="text-sm text-gray-600">{rule.description}</p>
                                <p className="text-xs text-gray-400 mt-1">
                                    {new Date(rule.startDate).toLocaleDateString('pt-BR')} até {new Date(rule.endDate).toLocaleDateString('pt-BR')}
                                </p>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>
            </div>
             <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Tarefas Concluídas</h3>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {completedTasks.map(task => {
                        const completionEvent = operation.events.find(e => e.completedTaskId === task.id);
                        return (
                            <div key={task.id} className="p-3 bg-green-50 rounded-md flex justify-between items-center border-l-4 border-green-500">
                                <div>
                                    <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                    <p className="text-sm text-gray-600">
                                        Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                {completionEvent && (
                                    <button onClick={() => handleViewEventClick(task.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm">
                                        <EyeIcon className="w-4 h-4" /> Ver Evento
                                    </button>
                                )}
                            </div>
                        )
                    })}
                    {completedTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa foi concluída ainda.</p>}
                </div>
            </div>
        </div>
    );
};

export default OperationDetail;

import React, { useState, useMemo } from 'react';
import type { Operation, Task, Event } from '../types';
import { TaskStatus } from '../types';
import EventForm from './EventForm';
import { CheckCircleIcon } from './icons/Icons';

interface TasksPageProps {
  operations: Operation[];
  allTasks: Task[];
  onUpdateOperation: (updatedOperation: Operation) => void;
}

const TasksPage: React.FC<TasksPageProps> = ({ operations, allTasks, onUpdateOperation }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedAnalyst, setSelectedAnalyst] = useState('Todos');
  const [selectedRuleName, setSelectedRuleName] = useState('Todos');
  const [activeTab, setActiveTab] = useState('pending'); // 'pending' or 'completed'

  const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
  const [isEventFormOpen, setIsEventFormOpen] = useState(false);

  const analysts = useMemo(() => ['Todos', ...new Set(operations.map(op => op.responsibleAnalyst))], [operations]);
  const ruleNames = useMemo(() => ['Todos', ...new Set(allTasks.map(task => task.ruleName))], [allTasks]);
  const operationsById = useMemo(() => new Map(operations.map(op => [op.id, op])), [operations]);

  const pendingTasksInMonth = useMemo(() => {
    return allTasks
      .filter(task => task.status !== TaskStatus.COMPLETED)
      .filter(task => {
        const op = operationsById.get(task.operationId);
        return selectedAnalyst === 'Todos' || op?.responsibleAnalyst === selectedAnalyst;
      })
      .filter(task => {
        const dueDate = new Date(task.dueDate);
        return dueDate.getFullYear() === currentMonth.getFullYear() && dueDate.getMonth() === currentMonth.getMonth();
      })
      .filter(task => selectedRuleName === 'Todos' || task.ruleName === selectedRuleName)
      .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
  }, [allTasks, selectedAnalyst, currentMonth, selectedRuleName, operationsById]);

  const completedTasksInMonth = useMemo(() => {
     return allTasks
      .filter(task => task.status === TaskStatus.COMPLETED)
      .filter(task => {
        const op = operationsById.get(task.operationId);
        return selectedAnalyst === 'Todos' || op?.responsibleAnalyst === selectedAnalyst;
      })
      .filter(task => {
        const op = operationsById.get(task.operationId);
        const completionEvent = op?.events.find(e => e.completedTaskId === task.id);
        if (!completionEvent) return false;
        const completionDate = new Date(completionEvent.date);
        return completionDate.getFullYear() === currentMonth.getFullYear() && completionDate.getMonth() === currentMonth.getMonth();
      })
      .filter(task => selectedRuleName === 'Todos' || task.ruleName === selectedRuleName)
      .sort((a, b) => {
          const eventA = operationsById.get(a.operationId)?.events.find(e => e.completedTaskId === a.id);
          const eventB = operationsById.get(b.operationId)?.events.find(e => e.completedTaskId === b.id);
          return (eventB ? new Date(eventB.date).getTime() : 0) - (eventA ? new Date(eventA.date).getTime() : 0);
      });
  }, [allTasks, selectedAnalyst, currentMonth, selectedRuleName, operationsById]);

  const changeMonth = (offset: number) => {
    setCurrentMonth(prev => {
      const newDate = new Date(prev);
      newDate.setMonth(prev.getMonth() + offset);
      return newDate;
    });
  };

  const handleCompleteTaskClick = (task: Task) => {
    setTaskToComplete(task);
    setIsEventFormOpen(true);
  };

  const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
      if (!taskToComplete) return;

      const operationToUpdate = operationsById.get(taskToComplete.operationId);
      if (operationToUpdate) {
        const eventToSave: Partial<Event> = {
            ...newEvent,
            completedTaskId: taskToComplete.id,
        };
        const updatedOperation = {
            ...operationToUpdate,
            events: [...operationToUpdate.events, { ...eventToSave, id: Date.now() } as Event]
        };
        onUpdateOperation(updatedOperation);
      }

      setTaskToComplete(null);
      setIsEventFormOpen(false);
  };


  return (
    <div className="space-y-6">
       {isEventFormOpen && taskToComplete && (
            <EventForm 
                onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                onSave={handleAddEvent}
                analystName={operationsById.get(taskToComplete.operationId)?.responsibleAnalyst || ''}
                prefilledTitle={`Conclusão: ${taskToComplete.ruleName}`}
            />
        )}
      <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Gerenciador de Tarefas</h2>

        {/* Filters */}
        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
            <div>
              <label htmlFor="analyst-filter" className="block text-sm font-medium text-gray-700">Analista</label>
              <select id="analyst-filter" value={selectedAnalyst} onChange={e => setSelectedAnalyst(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                {analysts.map(name => <option key={name} value={name}>{name}</option>)}
              </select>
            </div>
             <div>
                <label htmlFor="task-type-filter" className="block text-sm font-medium text-gray-700">Tipo de Tarefa</label>
                <select id="task-type-filter" value={selectedRuleName} onChange={e => setSelectedRuleName(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                    {ruleNames.map(name => <option key={name} value={name}>{name}</option>)}
                </select>
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700 text-center">Mês</label>
                <div className="flex justify-between items-center mt-1">
                    <button onClick={() => changeMonth(-1)} className="px-3 py-2 bg-gray-200 rounded-md hover:bg-gray-300">&larr;</button>
                    <h3 className="font-semibold text-gray-700">
                        {currentMonth.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })}
                    </h3>
                    <button onClick={() => changeMonth(1)} className="px-3 py-2 bg-gray-200 rounded-md hover:bg-gray-300">&rarr;</button>
                </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 mb-4">
            <nav className="-mb-px flex space-x-6" aria-label="Tabs">
                <button
                    onClick={() => setActiveTab('pending')}
                    className={`${
                        activeTab === 'pending'
                            ? 'border-blue-500 text-blue-600'
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    } whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}
                >
                    Tarefas Pendentes ({pendingTasksInMonth.length})
                </button>
                <button
                    onClick={() => setActiveTab('completed')}
                    className={`${
                        activeTab === 'completed'
                            ? 'border-blue-500 text-blue-600'
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    } whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}
                >
                    Tarefas Concluídas ({completedTasksInMonth.length})
                </button>
            </nav>
        </div>

        {/* Task List */}
        <div className="space-y-3">
          {activeTab === 'pending' && (
            <>
              {pendingTasksInMonth.map(task => {
                  const operationName = operationsById.get(task.operationId)?.name || 'N/A';
                  return (
                     <div key={task.id} className={`p-4 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                        <div className="flex-1">
                            <p className="font-semibold text-gray-800">{task.ruleName}</p>
                            <p className="text-sm text-gray-600">
                                <span className="font-medium">Operação:</span> {operationName}
                            </p>
                            <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-800'}`}>
                                Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                            </p>
                        </div>
                        <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                            <CheckCircleIcon className="w-4 h-4" /> Completar
                        </button>
                    </div>
                  );
              })}
              {pendingTasksInMonth.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                  <p>Nenhuma tarefa pendente encontrada para os filtros selecionados.</p>
                </div>
              )}
            </>
          )}

          {activeTab === 'completed' && (
            <>
                {completedTasksInMonth.map(task => {
                    const op = operationsById.get(task.operationId);
                    const operationName = op?.name || 'N/A';
                    const completionEvent = op?.events.find(e => e.completedTaskId === task.id);
                    return (
                        <div key={task.id} className="p-4 rounded-md flex justify-between items-center bg-green-50 border-l-4 border-green-500">
                            <div className="flex-1">
                                <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                <p className="text-sm text-gray-600">
                                    <span className="font-medium">Operação:</span> {operationName}
                                </p>
                                <p className="text-sm text-green-700">
                                    Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : 'N/A'}
                                </p>
                            </div>
                        </div>
                    );
                })}
                {completedTasksInMonth.length === 0 && (
                    <div className="text-center py-8 text-gray-500">
                      <p>Nenhuma tarefa concluída encontrada para os filtros selecionados.</p>
                    </div>
                )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default TasksPage;

import React, { useState, useMemo } from 'react';
import type { Operation, TaskRule } from './types';
import { Page } from './types';
import { initialOperations } from './data/mockData';
import { generateTasksForOperation } from './utils/taskEngine';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>(initialOperations);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => generateTasksForOperation(op));
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = (newOperation: Omit<Operation, 'id'>) => {
    const autoGeneratedRules: Omit<TaskRule, 'id'>[] = [];
    const today = new Date();
    const startDate = today.toISOString();
    const endDate = newOperation.maturityDate;

    // Frequency-based rules
    autoGeneratedRules.push({
        name: 'Revisão Periódica',
        frequency: newOperation.reviewFrequency as TaskRule['frequency'],
        startDate,
        endDate,
        description: 'Revisão periódica da operação, conforme frequência definida.'
    });
    autoGeneratedRules.push({
        name: 'Call de Acompanhamento',
        frequency: newOperation.callFrequency as TaskRule['frequency'],
        startDate,
        endDate,
        description: 'Call de acompanhamento com o cliente/gestor.'
    });
    autoGeneratedRules.push({
        name: 'Análise de DFs & Dívida',
        frequency: newOperation.dfFrequency as TaskRule['frequency'],
        startDate,
        endDate,
        description: 'Análise dos demonstrativos financeiros e endividamento.'
    });

    // Checkbox-based rules (Default Monitoring)
    const { defaultMonitoring } = newOperation;
    if (defaultMonitoring.news) {
        const nextFriday = new Date(today);
        nextFriday.setHours(0,0,0,0);
        const dayOfWeek = today.getDay(); // Sunday = 0, Friday = 5
        const daysUntilFriday = (5 - dayOfWeek + 7) % 7;
        nextFriday.setDate(today.getDate() + (daysUntilFriday === 0 ? 7 : daysUntilFriday));

        autoGeneratedRules.push({
            name: 'Monitorar Notícias',
            frequency: 'Semanal',
            startDate: nextFriday.toISOString(),
            endDate,
            description: 'Acompanhar notícias relacionadas à operação e ao mercado.'
        });
    }
    if (defaultMonitoring.fiiReport) {
        autoGeneratedRules.push({ name: 'Verificar Relatório FII', frequency: 'Mensal', startDate, endDate, description: 'Analisar o relatório mensal do FII, se aplicável.' });
    }
    if (defaultMonitoring.operationalInfo) {
        autoGeneratedRules.push({ name: 'Coletar Info Operacional', frequency: 'Mensal', startDate, endDate, description: 'Coletar e analisar informações operacionais da SPE/Projeto.' });
    }
    if (defaultMonitoring.receivablesPortfolio) {
        autoGeneratedRules.push({ name: 'Analisar Carteira de Recebíveis', frequency: 'Mensal', startDate, endDate, description: 'Análise da performance da carteira de recebíveis (FIDC/CRI).' });
    }
    if (defaultMonitoring.monthlyConstructionReport) {
        autoGeneratedRules.push({ name: 'Analisar Relatório Mensal de Obra', frequency: 'Mensal', startDate, endDate, description: 'Verificar o andamento físico e financeiro da obra.' });
    }
    if (defaultMonitoring.monthlyCommercialInfo) {
        autoGeneratedRules.push({ name: 'Analisar Info Comercial Mensal', frequency: 'Mensal', startDate, endDate, description: 'Analisar performance de vendas/locação do projeto.' });
    }
    if (defaultMonitoring.speDfs) {
        autoGeneratedRules.push({ name: 'Analisar DFs da SPE', frequency: 'Mensal', startDate, endDate, description: 'Analisar os demonstrativos financeiros da Sociedade de Propósito Específico.' });
    }

    const newOpWithId = { 
      ...newOperation, 
      id: Date.now(),
      taskRules: autoGeneratedRules.map((rule, index) => ({
        ...rule,
        id: Date.now() + index
      }))
    };
    setOperations(prev => [ ...prev, newOpWithId ]);
    // Navigate to the new operation's detail page after adding it
    handleNavigate(Page.DETAIL, newOpWithId.id);
  };

  const handleUpdateOperation = (updatedOperation: Operation) => {
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const renderContent = () => {
    switch (currentPage) {
        case Page.OVERVIEW:
            return <OverviewDashboard
                operations={operations}
                allTasks={allTasks}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
            />;
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                allTasks={allTasks}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

