import type { Operation, Task, TaskRule } from '../types';
import { TaskStatus } from '../types';

const getNextDate = (currentDate: Date, frequency: TaskRule['frequency']): Date => {
  const next = new Date(currentDate);
  switch (frequency) {
    case 'Diário':
      next.setDate(next.getDate() + 1);
      break;
    case 'Semanal':
      next.setDate(next.getDate() + 7);
      break;
    case 'Quinzenal':
      next.setDate(next.getDate() + 15);
      break;
    case 'Mensal':
      next.setMonth(next.getMonth() + 1);
      break;
    case 'Trimestral':
      next.setMonth(next.getMonth() + 3);
      break;
    case 'Semestral':
      next.setMonth(next.getMonth() + 6);
      break;
    case 'Anual':
      next.setFullYear(next.getFullYear() + 1);
      break;
  }
  return next;
};

export const generateTasksForRule = (operation: Operation, rule: TaskRule): Task[] => {
  const tasks: Task[] = [];
  const completedTaskIds = new Set(operation.events.map(e => e.completedTaskId).filter(Boolean));

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // Handle one-off 'Pontual' tasks
  if (rule.frequency === 'Pontual') {
    const dueDate = new Date(rule.startDate);
    const taskId = `op${operation.id}-rule${rule.id}-${dueDate.toISOString().split('T')[0]}`;

    let status: TaskStatus;
    if (completedTaskIds.has(taskId)) {
      status = TaskStatus.COMPLETED;
    } else if (dueDate < today) {
      status = TaskStatus.OVERDUE;
    } else {
      status = TaskStatus.PENDING;
    }

    tasks.push({
      id: taskId,
      operationId: operation.id,
      ruleId: rule.id,
      ruleName: rule.name,
      dueDate: dueDate.toISOString(),
      status: status,
    });
    return tasks;
  }

  // Handle recurring tasks
  let currentDate = new Date(rule.startDate);
  const endDate = new Date(rule.endDate);

  while (currentDate <= endDate) {
    const dueDate = new Date(currentDate);
    const taskId = `op${operation.id}-rule${rule.id}-${dueDate.toISOString().split('T')[0]}`;

    let status: TaskStatus;
    if (completedTaskIds.has(taskId)) {
      status = TaskStatus.COMPLETED;
    } else if (dueDate < today) {
      status = TaskStatus.OVERDUE;
    } else {
      status = TaskStatus.PENDING;
    }

    const task: Task = {
      id: taskId,
      operationId: operation.id,
      ruleId: rule.id,
      ruleName: rule.name,
      dueDate: dueDate.toISOString(),
      status: status,
    };

    tasks.push(task);
    currentDate = getNextDate(currentDate, rule.frequency);
  }

  return tasks;
};


export const generateTasksForOperation = (operation: Operation): Task[] => {
  return operation.taskRules.flatMap(rule => generateTasksForRule(operation, rule));
};

export const getOverdueTasksCount = (tasks: Task[]): number => {
    return tasks.filter(task => task.status === TaskStatus.OVERDUE).length;
}

import React, { useState, useMemo, useRef } from 'react';
import type { Operation, Event, Task, RatingHistoryEntry, Rating, WatchlistStatus, Sentiment } from '../types';
import { TaskStatus, ratingOptions } from '../types';
import { generateTasksForOperation } from '../utils/taskEngine';
import { PlusCircleIcon, CheckCircleIcon, EyeIcon, ArrowUpIcon, ArrowRightIcon, ArrowDownIcon, BellIcon } from './icons/Icons';
import EventForm from './EventForm';
import WatchlistChangeForm from './WatchlistChangeForm';
import ReviewCompletionForm from './ReviewCompletionForm';

interface OperationDetailProps {
  operation: Operation;
  onUpdateOperation: (updatedOperation: Operation) => void;
  onOpenNewTaskModal: (operationId: number) => void;
}

const InfoCard: React.FC<{ title: string; children: React.ReactNode; }> = ({ title, children }) => (
    <div className="bg-gray-50 p-3 rounded-md">
        <h4 className="text-xs text-gray-500 font-semibold uppercase">{title}</h4>
        <p className="text-gray-800 font-medium">{children}</p>
    </div>
);

const getRatingChange = (currentRating: Rating, previousRating: Rating | undefined): 'up' | 'down' | 'neutral' => {
    if (!previousRating || currentRating === previousRating) {
        return 'neutral';
    }
    const currentIndex = ratingOptions.indexOf(currentRating);
    const previousIndex = ratingOptions.indexOf(previousRating);

    if (currentIndex < 0 || previousIndex < 0) return 'neutral';

    if (currentIndex < previousIndex) return 'up'; // Better rating, e.g., index 1 (Baa1) is better than index 2 (Baa3)
    if (currentIndex > previousIndex) return 'down'; // Worse rating
    return 'neutral';
};

const RatingChangeIndicator: React.FC<{ change: 'up' | 'down' | 'neutral' }> = ({ change }) => {
    if (change === 'up') {
        return <ArrowUpIcon className="w-4 h-4 text-green-600" title="Upgrade" />;
    }
    if (change === 'down') {
        return <ArrowDownIcon className="w-4 h-4 text-red-600" title="Downgrade" />;
    }
    return <ArrowRightIcon className="w-4 h-4 text-gray-400" title="Sem alteração" />;
};


const OperationDetail: React.FC<OperationDetailProps> = ({ operation, onUpdateOperation, onOpenNewTaskModal }) => {
    const [isEventFormOpen, setIsEventFormOpen] = useState(false);
    const [isWatchlistFormOpen, setIsWatchlistFormOpen] = useState(false);
    const [isReviewFormOpen, setIsReviewFormOpen] = useState(false);

    const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
    const [reviewTaskToComplete, setReviewTaskToComplete] = useState<Task | null>(null);

    const [expandedEventId, setExpandedEventId] = useState<number | null>(null);
    const eventRefs = useRef<Record<number, HTMLDivElement | null>>({});

    // State for filtering events
    const [dateFilter, setDateFilter] = useState({ start: '', end: '' });
    const [typeFilter, setTypeFilter] = useState('Todos');
    const [personFilter, setPersonFilter] = useState('Todos');

    const tasks = useMemo(() => generateTasksForOperation(operation), [operation]);

    const activeTasks = useMemo(() => {
        return tasks.filter(t => t.status === TaskStatus.PENDING || t.status === TaskStatus.OVERDUE)
            .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks]);

    const completedTasks = useMemo(() => {
        return tasks.filter(t => t.status === TaskStatus.COMPLETED)
            .sort((a, b) => {
                const eventA = operation.events.find(e => e.completedTaskId === a.id);
                const eventB = operation.events.find(e => e.completedTaskId === b.id);
                return (eventB ? new Date(eventB.date).getTime() : 0) - (eventA ? new Date(eventA.date).getTime() : 0);
            });
    }, [tasks, operation.events]);

    const uniqueEventTypes = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.type))], [operation.events]);
    const uniqueRegisteredBy = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.registeredBy))], [operation.events]);

    const filteredEvents = useMemo(() => {
        return [...operation.events]
            .filter(event => {
                if (!dateFilter.start && !dateFilter.end) return true;
                const eventDate = new Date(event.date);
                eventDate.setHours(0,0,0,0);
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && eventDate < startDate) return false;
                if (endDate && eventDate > endDate) return false;
                return true;
            })
            .filter(event => typeFilter === 'Todos' || event.type === typeFilter)
            .filter(event => personFilter === 'Todos' || event.registeredBy === personFilter)
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.events, dateFilter, typeFilter, personFilter]);

    const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
        const eventToSave: Partial<Event> = { ...newEvent };
        if (taskToComplete) {
            eventToSave.completedTaskId = taskToComplete.id;
        }

        const updatedOperation = {
            ...operation,
            events: [...operation.events, { ...eventToSave, id: Date.now() } as Event]
        };
        onUpdateOperation(updatedOperation);

        setTaskToComplete(null);
        setIsEventFormOpen(false);
    };

    const handleCompleteTaskClick = (task: Task) => {
        if (task.ruleName === 'Revisão Periódica') {
            setReviewTaskToComplete(task);
            setIsReviewFormOpen(true);
        } else {
            setTaskToComplete(task);
            setIsEventFormOpen(true);
        }
    };

    const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
        const newEventId = Date.now();
        const eventToSave: Event = {
            ...data.event,
            id: newEventId,
            completedTaskId: reviewTaskToComplete?.id
        };

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            sentiment: data.sentiment,
            eventId: newEventId,
        };

        const updatedOperation: Operation = {
            ...operation,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
            ratingHistory: [...operation.ratingHistory, newHistoryEntry]
        };

        onUpdateOperation(updatedOperation);
        setReviewTaskToComplete(null);
        setIsReviewFormOpen(false);
    };

    const handleSaveWatchlistChange = (data: { watchlist: WatchlistStatus, ratingOp: Rating, ratingGroup: Rating, event: Omit<Event, 'id'>}) => {
        const newEventId = Date.now();
        const eventToSave: Event = { ...data.event, id: newEventId };

        const updatedOperation: Operation = {
            ...operation,
            watchlist: data.watchlist,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
        };
        onUpdateOperation(updatedOperation);
        setIsWatchlistFormOpen(false);
    };

    const handleViewEventClick = (taskId: string) => {
        const completionEvent = operation.events.find(e => e.completedTaskId === taskId);
        if (completionEvent) {
            setExpandedEventId(completionEvent.id);
            const eventElement = eventRefs.current[completionEvent.id];
            if (eventElement) {
                eventElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }

    return (
        <div className="space-y-8">
            {isEventFormOpen && (
                <EventForm 
                    onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                    onSave={handleAddEvent}
                    analystName={operation.responsibleAnalyst}
                    prefilledTitle={taskToComplete ? `Conclusão: ${taskToComplete.ruleName}` : ''}
                />
            )}
            {isWatchlistFormOpen && (
                <WatchlistChangeForm
                    operation={operation}
                    onClose={() => setIsWatchlistFormOpen(false)}
                    onSave={handleSaveWatchlistChange}
                />
            )}
            {isReviewFormOpen && reviewTaskToComplete && (
                <ReviewCompletionForm
                    task={reviewTaskToComplete}
                    operation={operation}
                    onClose={() => setIsReviewFormOpen(false)}
                    onSave={handleSaveReview}
                />
            )}


            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-start mb-4">
                    <h2 className="text-2xl font-bold text-gray-800">{operation.name}</h2>
                    <button onClick={() => setIsWatchlistFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-yellow-400 text-yellow-900 rounded-lg hover:bg-yellow-500">
                        <BellIcon className="w-5 h-5"/> Alterar Watchlist / Rating
                    </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <InfoCard title="Projetos">{operation.projects.map(p => p.name).join(', ')}</InfoCard>
                    <InfoCard title="Garantias">{operation.guarantees.map(g => g.name).join(', ')}</InfoCard>
                    <InfoCard title="Segmento">{operation.segmento}</InfoCard>
                    <InfoCard title="Covenant LTV">{operation.covenants.ltv ?? 'N/A'}</InfoCard>
                    <InfoCard title="Covenant DSCR">{operation.covenants.dscr ?? 'N/A'}</InfoCard>
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold text-gray-700">Histórico de Eventos</h3>
                    <button onClick={() => setIsEventFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                        <PlusCircleIcon className="w-5 h-5"/> Adicionar Evento
                    </button>
                </div>

                <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4">
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div>
                            <label htmlFor="start-date" className="text-sm font-medium text-gray-700">De:</label>
                            <input type="date" id="start-date" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="end-date" className="text-sm font-medium text-gray-700">Até:</label>
                            <input type="date" id="end-date" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="type-filter" className="text-sm font-medium text-gray-700">Tipo:</label>
                            <select id="type-filter" value={typeFilter} onChange={e => setTypeFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueEventTypes.map(type => <option key={type} value={type}>{type}</option>)}
                            </select>
                        </div>
                        <div>
                            <label htmlFor="person-filter" className="text-sm font-medium text-gray-700">Responsável:</label>
                            <select id="person-filter" value={personFilter} onChange={e => setPersonFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueRegisteredBy.map(name => <option key={name} value={name}>{name}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="space-y-2 max-h-96 overflow-y-auto">
                     {filteredEvents.map(event => (
                        <div key={event.id} ref={el => { if(el) eventRefs.current[event.id] = el; }} className={`border border-gray-200 rounded-lg p-4 transition-all duration-300 ${expandedEventId === event.id ? 'bg-blue-50 ring-2 ring-blue-300' : ''}`}>
                            <div className="grid grid-cols-4 md:grid-cols-5 gap-4 items-center">
                                <div className="text-sm font-medium text-gray-600">{new Date(event.date).toLocaleDateString('pt-BR')}</div>
                                <div className="text-sm text-gray-800"><span className="font-semibold">{event.type}</span></div>
                                <div className="col-span-2 md:col-span-2 text-sm text-gray-800">{event.title}</div>
                                <div className="text-right">
                                    <button onClick={() => setExpandedEventId(expandedEventId === event.id ? null : event.id)} className="text-blue-600 hover:text-blue-800 text-sm">
                                        {expandedEventId === event.id ? 'Ver Menos' : 'Ver Mais'}
                                    </button>
                                </div>
                            </div>
                            {expandedEventId === event.id && (
                                <div className="mt-4 pt-4 border-t border-gray-200 space-y-3 text-sm text-gray-700">
                                    <p><strong className="font-semibold text-gray-600">Descrição:</strong> {event.description}</p>
                                    <p><strong className="font-semibold text-gray-600">Registrado por:</strong> {event.registeredBy}</p>
                                    <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>
                                    {event.completedTaskId && <p className="text-xs text-gray-500 italic pt-2">Este evento concluiu a tarefa ID: {event.completedTaskId}</p>}
                                </div>
                            )}
                        </div>
                     ))}
                     {filteredEvents.length === 0 && <p className="text-center text-gray-500 py-4">Nenhum evento encontrado para os filtros selecionados.</p>}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <h3 className="text-xl font-bold text-gray-700 mb-4">Execução de Tarefas</h3>
                    <div className="space-y-2 max-h-96 overflow-y-auto">
                       {activeTasks.map(task => (
                           <div key={task.id} className={`p-3 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                               <div>
                                   <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                   <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-700'}`}>
                                       Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                   </p>
                               </div>
                               <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                   <CheckCircleIcon className="w-4 h-4" /> Completar
                               </button>
                           </div>
                       ))}
                        {activeTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa pendente.</p>}
                    </div>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-lg">
                     <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-gray-700">Regras de Tarefas</h3>
                         <button onClick={() => onOpenNewTaskModal(operation.id)} className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm">
                            <PlusCircleIcon className="w-5 h-5"/> Adicionar Tarefa
                        </button>
                    </div>
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {operation.taskRules.map(rule => (
                            <div key={rule.id} className="p-3 bg-gray-50 rounded-md">
                                <p className="font-semibold text-gray-800">{rule.name} <span className="text-xs font-normal text-white bg-blue-500 px-2 py-0.5 rounded-full">{rule.frequency}</span></p>
                                <p className="text-sm text-gray-600">{rule.description}</p>
                                <p className="text-xs text-gray-400 mt-1">
                                    {new Date(rule.startDate).toLocaleDateString('pt-BR')} até {new Date(rule.endDate).toLocaleDateString('pt-BR')}
                                </p>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Ratings e Sentimentos</h3>
                <div className="space-y-3 max-h-96 overflow-y-auto">
                    {operation.ratingHistory.length > 0 ? (
                        [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((entry, index, array) => {
                             const previousEntry = array[index + 1]; // The one before chronologically
                             const opRatingChange = getRatingChange(entry.ratingOperation, previousEntry?.ratingOperation);
                             const groupRatingChange = getRatingChange(entry.ratingGroup, previousEntry?.ratingGroup);

                            return (
                                <div key={entry.id} className="p-3 bg-gray-50 rounded-md grid grid-cols-4 gap-4 items-center">
                                    <div className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</div>
                                    <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                        <span className="text-xs text-gray-500">Op: </span>
                                        <RatingChangeIndicator change={opRatingChange} />
                                        {entry.ratingOperation}
                                    </div>
                                    <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                        <span className="text-xs text-gray-500">Grupo: </span>
                                        <RatingChangeIndicator change={groupRatingChange} />
                                        {entry.ratingGroup}
                                    </div>
                                    <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                        {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                        {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                        {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                        {entry.sentiment}
                                    </div>
                                </div>
                            );
                        })
                    ) : (
                        <p className="text-center text-gray-500 py-4">Nenhum histórico de rating para esta operação.</p>
                    )}
                </div>
            </div>
             <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Tarefas Concluídas</h3>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {completedTasks.map(task => {
                        const completionEvent = operation.events.find(e => e.completedTaskId === task.id);
                        return (
                            <div key={task.id} className="p-3 bg-green-50 rounded-md flex justify-between items-center border-l-4 border-green-500">
                                <div>
                                    <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                    <p className="text-sm text-gray-600">
                                        Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                {completionEvent && (
                                    <button onClick={() => handleViewEventClick(task.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm">
                                        <EyeIcon className="w-4 h-4" /> Ver Evento
                                    </button>
                                )}
                            </div>
                        )
                    })}
                    {completedTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa foi concluída ainda.</p>}
                </div>
            </div>
        </div>
    );
};

export default OperationDetail;

import React, { useState, useEffect, useMemo } from 'react';
import type { Operation, TaskRule } from '../types';
import Modal from './Modal';
import TaskRuleForm from './TaskRuleForm';
import AdHocTaskForm from './AdHocTaskForm';

interface NewTaskModalProps {
  isOpen: boolean;
  onClose: () => void;
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
  preselectedOperationId?: number;
}

const NewTaskModal: React.FC<NewTaskModalProps> = ({ isOpen, onClose, operations, onUpdateOperation, preselectedOperationId }) => {
  const [operationId, setOperationId] = useState<number | null>(null);
  const [formType, setFormType] = useState<'pontual' | 'recorrente'>('pontual');

  const preselectedOperation = useMemo(() => {
    if (!preselectedOperationId) return null;
    return operations.find(op => op.id === preselectedOperationId);
  }, [preselectedOperationId, operations]);

  const handleSaveTaskRule = (rule: Omit<TaskRule, 'id'>) => {
    if (!operationId) return;
    const opToUpdate = operations.find(op => op.id === operationId);
    if (opToUpdate) {
        const updatedOp = {
            ...opToUpdate,
            taskRules: [...opToUpdate.taskRules, { ...rule, id: Date.now() }]
        };
        onUpdateOperation(updatedOp);
    }
    onClose();
  };

  useEffect(() => {
      if (isOpen) {
          setOperationId(preselectedOperationId ?? null);
          setFormType('pontual'); // Reset to default tab when opening
      } else {
          // Delay reset to prevent form disappearing before modal closes
          setTimeout(() => setOperationId(null), 200); 
      }
  }, [isOpen, preselectedOperationId]);

  const title = preselectedOperation 
    ? `Adicionar Tarefa para: ${preselectedOperation.name}` 
    : "Adicionar Nova Tarefa";

  const TabButton: React.FC<{isActive: boolean, onClick: () => void, children: React.ReactNode}> = ({ isActive, onClick, children }) => (
      <button
        type="button"
        onClick={onClick}
        className={`px-4 py-2 text-sm font-medium rounded-t-lg ${isActive ? 'bg-white border-b-0 border-gray-300 text-blue-600' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}
        style={{border: '1px solid #d1d5db', borderBottom: isActive ? '1px solid white' : '1px solid #d1d5db', marginBottom: '-1px'}}
      >
        {children}
      </button>
  );

  return (
    <Modal isOpen={isOpen} title={title} onClose={onClose}>
      <div className="space-y-4">
        {!preselectedOperationId && (
            <div className="mb-4">
                <label htmlFor="op-select" className="block text-sm font-medium text-gray-700 mb-1">1. Selecione a Operação</label>
                <select
                    id="op-select"
                    value={operationId ?? ''}
                    onChange={e => setOperationId(Number(e.target.value) || null)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                    <option value="">-- Por favor, escolha uma operação --</option>
                    {operations.map(op => <option key={op.id} value={op.id}>{op.name}</option>)}
                </select>
            </div>
        )}

        {operationId && (
            <div>
                 <label className="block text-sm font-medium text-gray-700 mb-2">
                    {preselectedOperationId ? 'Defina a Tarefa' : '2. Defina a Tarefa'}
                 </label>

                 <div className="flex border-b border-gray-300">
                    <TabButton isActive={formType === 'pontual'} onClick={() => setFormType('pontual')}>
                        Tarefa Pontual
                    </TabButton>
                    <TabButton isActive={formType === 'recorrente'} onClick={() => setFormType('recorrente')}>
                        Tarefa Recorrente (Regra)
                    </TabButton>
                 </div>

                <div className="p-4 border border-t-0 rounded-b-md bg-white">
                     {formType === 'pontual' && (
                        <AdHocTaskForm
                            onClose={onClose}
                            onSave={handleSaveTaskRule}
                        />
                     )}
                     {formType === 'recorrente' && (
                        <TaskRuleForm
                            onClose={onClose}
                            onSave={handleSaveTaskRule}
                        />
                     )}
                </div>
           </div>
        )}
      </div>
    </Modal>
  );
};

export default NewTaskModal;

import React, { useState } from 'react';
import type { TaskRule } from '../types';

interface AdHocTaskFormProps {
  onClose: () => void;
  onSave: (rule: Omit<TaskRule, 'id'>) => void;
}

const Label: React.FC<{htmlFor: string; children: React.ReactNode}> = ({ htmlFor, children }) => <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">{children}</label>;

const AdHocTaskForm: React.FC<AdHocTaskFormProps> = ({ onClose, onSave }) => {
  const [name, setName] = useState('');
  const [dueDate, setDueDate] = useState(new Date().toISOString().split('T')[0]);
  const [description, setDescription] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      name,
      frequency: 'Pontual',
      startDate: new Date(dueDate).toISOString(),
      endDate: new Date(dueDate).toISOString(), // For pontual, start and end are the same
      description,
    });
  };

  return (
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
                <Label htmlFor="adhoc-name">Nome da Tarefa</Label>
                <input id="adhoc-name" type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
            <div>
                <Label htmlFor="adhoc-dueDate">Data de Vencimento</Label>
                <input id="adhoc-dueDate" type="date" value={dueDate} onChange={e => setDueDate(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
        </div>
        <div>
            <Label htmlFor="adhoc-description">Descrição</Label>
            <textarea id="adhoc-description" value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>
         <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">Cancelar</button>
          <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">Salvar Tarefa</button>
        </div>
      </form>
  );
};

export default AdHocTaskForm;

