import React, { useState, useMemo, useEffect } from 'react';
import type { Operation, TaskRule } from './types';
import { Page } from './types';
import { generateTasksForOperation } from './utils/taskEngine';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';

const API_BASE_URL = 'http://127.0.0.1:5000'; // Flask default development server

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchOperations = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/operations`);
        if (!response.ok) {
          throw new Error('Failed to fetch data from backend');
        }
        const data: Operation[] = await response.json();
        setOperations(data);
      } catch (error) {
        console.error("Error fetching operations:", error);
        // Here you could set an error state to show a message to the user
      } finally {
        setIsLoading(false);
      }
    };
    fetchOperations();
  }, []);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => generateTasksForOperation(op));
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperation: Omit<Operation, 'id'>) => {
    // Auto-generation of rules remains a frontend concern for immediate feedback
    const autoGeneratedRules: Omit<TaskRule, 'id' | 'operation_id'>[] = [];
    const today = new Date();
    const startDate = today.toISOString();
    const endDate = newOperation.maturityDate;

    autoGeneratedRules.push({ name: 'Revisão Periódica', frequency: newOperation.reviewFrequency as TaskRule['frequency'], startDate, endDate, description: 'Revisão periódica da operação, conforme frequência definida.'});
    autoGeneratedRules.push({ name: 'Call de Acompanhamento', frequency: newOperation.callFrequency as TaskRule['frequency'], startDate, endDate, description: 'Call de acompanhamento com o cliente/gestor.' });
    autoGeneratedRules.push({ name: 'Análise de DFs & Dívida', frequency: newOperation.dfFrequency as TaskRule['frequency'], startDate, endDate, description: 'Análise dos demonstrativos financeiros e endividamento.' });

    const { defaultMonitoring } = newOperation;
    if (defaultMonitoring.news) {
        const nextFriday = new Date(today);
        nextFriday.setHours(0,0,0,0);
        const dayOfWeek = today.getDay();
        const daysUntilFriday = (5 - dayOfWeek + 7) % 7;
        nextFriday.setDate(today.getDate() + (daysUntilFriday === 0 ? 7 : daysUntilFriday));
        autoGeneratedRules.push({ name: 'Monitorar Notícias', frequency: 'Semanal', startDate: nextFriday.toISOString(), endDate, description: 'Acompanhar notícias relacionadas à operação e ao mercado.' });
    }
    if (defaultMonitoring.fiiReport) autoGeneratedRules.push({ name: 'Verificar Relatório FII', frequency: 'Mensal', startDate, endDate, description: 'Analisar o relatório mensal do FII, se aplicável.' });
    if (defaultMonitoring.operationalInfo) autoGeneratedRules.push({ name: 'Coletar Info Operacional', frequency: 'Mensal', startDate, endDate, description: 'Coletar e analisar informações operacionais da SPE/Projeto.' });
    if (defaultMonitoring.receivablesPortfolio) autoGeneratedRules.push({ name: 'Analisar Carteira de Recebíveis', frequency: 'Mensal', startDate, endDate, description: 'Análise da performance da carteira de recebíveis (FIDC/CRI).' });
    if (defaultMonitoring.monthlyConstructionReport) autoGeneratedRules.push({ name: 'Analisar Relatório Mensal de Obra', frequency: 'Mensal', startDate, endDate, description: 'Verificar o andamento físico e financeiro da obra.' });
    if (defaultMonitoring.monthlyCommercialInfo) autoGeneratedRules.push({ name: 'Analisar Info Comercial Mensal', frequency: 'Mensal', startDate, endDate, description: 'Analisar performance de vendas/locação do projeto.' });
    if (defaultMonitoring.speDfs) autoGeneratedRules.push({ name: 'Analisar DFs da SPE', frequency: 'Mensal', startDate, endDate, description: 'Analisar os demonstrativos financeiros da Sociedade de Propósito Específico.' });

    const operationWithRules = {
      ...newOperation,
      taskRules: autoGeneratedRules
    };

    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(operationWithRules)
        });
        if (!response.ok) throw new Error('Failed to save operation');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
     try {
        const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(updatedOperation)
        });
        if (!response.ok) throw new Error('Failed to update operation');
        const returnedOperation = await response.json();
         setOperations(prev => 
            prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
        );
    } catch (error) {
        console.error("Error updating operation:", error);
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };


  const renderContent = () => {
    if (isLoading) {
      return <div className="flex justify-center items-center h-full"><p className="text-xl text-gray-500">Carregando dados...</p></div>;
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return <OverviewDashboard
                operations={operations}
                allTasks={allTasks}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
            />;
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                allTasks={allTasks}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            <OverdueOperationsHighlight
              operations={operations}
              allTasks={allTasks}
              onNavigate={handleNavigate}
            />
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

