import React, { useState } from 'react';
import type { Operation } from '../types';
import { WatchlistStatus } from '../types';
import OperationForm from './OperationForm';
import AnalystCalendar from './AnalystCalendar';
import { PlusCircleIcon, EyeIcon, TrashIcon } from './icons/Icons';
import Modal from './Modal';

interface OverviewDashboardProps {
  operations: Operation[];
  onSelectOperation: (id: number) => void;
  onAddOperation: (newOperationData: any) => void;
  onOpenNewTaskModal: (operationId: number) => void;
  onDeleteOperation: (id: number) => void;
}

const WatchlistBadge: React.FC<{ status: WatchlistStatus }> = ({ status }) => {
  const colorClasses = {
    [WatchlistStatus.VERDE]: 'bg-green-100 text-green-800',
    [WatchlistStatus.AMARELO]: 'bg-yellow-100 text-yellow-800',
    [WatchlistStatus.ROSA]: 'bg-pink-100 text-pink-800',
    [WatchlistStatus.VERMELHO]: 'bg-red-100 text-red-800',
  };

  return (
    <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${colorClasses[status]}`}>
      {status}
    </span>
  );
};


const OverviewDashboard: React.FC<OverviewDashboardProps> = ({ operations, onSelectOperation, onAddOperation, onOpenNewTaskModal, onDeleteOperation }) => {
  const [isFormOpen, setIsFormOpen] = React.useState(false);
  const [operationToDelete, setOperationToDelete] = useState<Operation | null>(null);

  const allTasks = React.useMemo(() => {
      return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const confirmDelete = () => {
    if (operationToDelete) {
      onDeleteOperation(operationToDelete.id);
      setOperationToDelete(null); // Close modal
    }
  };

  return (
    <div className="space-y-8">
      {isFormOpen && (
        <OperationForm 
            onClose={() => setIsFormOpen(false)} 
            onSave={onAddOperation} 
        />
      )}

      {operationToDelete && (
        <Modal
          isOpen={true}
          onClose={() => setOperationToDelete(null)}
          title={`Deletar Operação: ${operationToDelete.name}`}
        >
          <div className="text-center">
            <p className="text-lg text-gray-700 mb-4">
              Você tem certeza que deseja deletar esta operação?
            </p>
            <p className="text-sm text-red-600 font-semibold mb-6">
              Todos os eventos, tarefas e históricos associados serão permanentemente removidos. Esta ação não pode ser desfeita.
            </p>
            <div className="flex justify-center gap-4">
              <button
                onClick={() => setOperationToDelete(null)}
                className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300"
              >
                Cancelar
              </button>
              <button
                onClick={confirmDelete}
                className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
              >
                Confirmar Deleção
              </button>
            </div>
          </div>
        </Modal>
      )}

      {/* Operations Summary */}
      <div className="bg-white p-6 rounded-lg shadow-lg">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold text-gray-700">Resumo de Operações</h2>
          <button
            onClick={() => setIsFormOpen(true)}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition duration-300"
          >
            <PlusCircleIcon className="w-5 h-5" />
            <span>Adicionar Operação</span>
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Nome da Operação</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Rating Op.</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Rating Grupo</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Watchlist</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tarefas Atrasadas</th>
                <th scope="col" className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {operations.map((op) => (
                <tr key={op.id} className="hover:bg-gray-50">
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{op.name}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{op.ratingOperation}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{op.ratingGroup}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500"><WatchlistBadge status={op.watchlist} /></td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-center">
                    <span className={op.overdueCount > 0 ? 'text-red-600 font-bold' : 'text-green-600'}>
                      {op.overdueCount}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm font-medium">
                    <div className="flex items-center justify-center gap-4">
                        <button onClick={() => onOpenNewTaskModal(op.id)} className="text-gray-600 hover:text-blue-600 font-semibold">
                            Adicionar Tarefa
                        </button>
                        <button onClick={() => onSelectOperation(op.id)} className="flex items-center gap-1 text-blue-600 hover:text-blue-900 font-semibold">
                            <EyeIcon className="w-5 h-5" /> Detalhes
                        </button>
                        <button
                            onClick={() => setOperationToDelete(op)}
                            className="text-gray-400 hover:text-red-600 transition-colors duration-200"
                            title="Deletar Operação"
                        >
                            <TrashIcon className="w-5 h-5" />
                        </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
            {operations.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                    Nenhuma operação cadastrada.
                </div>
            )}
        </div>
      </div>

      {/* Analyst Calendar */}
      <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-xl font-bold text-gray-700 mb-4">Calendário do Analista (Mês Atual)</h2>
        <AnalystCalendar tasks={allTasks} operations={operations} />
      </div>
    </div>
  );
};

export default OverviewDashboard;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import type { Operation } from './types';
import { Page } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); // Clear previous errors on a new attempt
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    // Business logic for task generation is now on the backend.
    // The frontend just consumes the 'tasks' array.
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    // Business logic for auto-generating task rules is now on the backend.
    // The frontend sends the raw form data.
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Failed to save operation');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];

    // Optimistic UI Update: Update the state immediately for a responsive feel.
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Failed to update operation on the server.');
      }
      // The backend now sends back the updated operation, which might have refreshed data.
      // We can re-sync the state silently.
      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      // Rollback on error
      setOperations(originalOperations);
      // Here you could also show a toast notification to the user
      // alert("Falha ao salvar as alterações. Tente novamente.");
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }
      setOperations(prev => prev.filter(op => op.id !== operationId));
      // If the currently viewed operation is the one being deleted, navigate away for better UX
      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
    } catch (error) {
      console.error("Error deleting operation:", error);
      // Optionally, show an error message to the user
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };


  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            <OverdueOperationsHighlight
              operations={operations}
              onNavigate={handleNavigate}
            />
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

