/// <reference types="cypress" />

describe('Operation Detail Page', () => {
  beforeEach(() => {
    // Intercept the initial GET request and provide mock data.
    cy.intercept('GET', '**/api/operations', {
      fixture: 'operations.json',
    }).as('getOperations');

    // Intercept the PUT request that will be used for updates.
    // We provide a static response that mirrors the request body,
    // which is what our optimized backend does.
    cy.intercept('PUT', '**/api/operations/1', (req) => {
      req.reply({
        statusCode: 200,
        body: req.body,
      });
    }).as('updateOperation');

    // Visit the root of our application.
    cy.visit('/');

    // Wait for the initial data to load.
    cy.wait('@getOperations');

    // Navigate to the detail page for our test operation.
    cy.contains('button', 'Detalhes').click();

    // Assert we are on the correct page by checking the header.
    cy.contains('h2', 'CRI Test Operation').should('be.visible');
  });

  it('should display the core details of the operation', () => {
    // Check for key information cards to ensure the data from the fixture is rendered.
    cy.contains('div', 'Project Cypress').should('be.visible');
    cy.contains('div', 'Infra').should('be.visible');
    cy.contains('div', '0.6').should('be.visible'); // LTV
    cy.contains('div', '1.5').should('be.visible'); // DSCR
  });

  it('should allow adding a new event and display it in the history', () => {
    const eventTitle = 'Reunião de Alinhamento Cypress';
    const eventDescription = 'Discussão sobre os próximos passos do projeto.';

    // 1. Open the event form modal.
    cy.contains('button', 'Adicionar Evento').click();

    // 2. Fill out the form.
    cy.get('input#title').type(eventTitle);
    cy.get('textarea#description').type(eventDescription);
    cy.get('textarea#nextSteps').type('Agendar próxima reunião.');

    // 3. Save the event.
    cy.contains('button', 'Salvar Evento').click();

    // 4. Wait for the API call and assert its request body.
    cy.wait('@updateOperation').its('request.body.events').should('have.length', 2);
    cy.wait('@updateOperation').its('request.body.events.1').should('deep.include', {
        title: eventTitle,
        description: eventDescription
    });

    // 5. Verify the new event is visible in the UI (testing the optimistic update).
    cy.contains(eventTitle).should('be.visible');
  });

  it('should allow completing a review task and update relevant sections', () => {
    // 1. Find the pending review task and click "Completar".
    cy.contains('div', 'Execução de Tarefas')
      .contains('div', 'Revisão Periódica')
      .find('button', 'Completar')
      .click();

    // 2. The review completion modal should appear. Fill it out.
    cy.get('textarea#review-description').type('Revisão trimestral concluída sem ressalvas.');
    cy.get('select#review-rating-op').select('A4'); // Simulate an upgrade
    cy.get('select#review-sentiment').select('Positivo');

    // 3. Save the review.
    cy.contains('button', 'Concluir e Salvar Revisão').click();

    // 4. Wait for the API call and verify the payload.
    cy.wait('@updateOperation').its('request.body').should((body) => {
        expect(body.ratingOperation).to.equal('A4'); // Check if rating was updated
        expect(body.ratingHistory).to.have.length(2); // Check if history was added
        expect(body.events).to.have.length(2); // Check if event was added
        expect(body.events[1].completedTaskId).to.equal('op1-rule1-2024-07-30');
    });

    // 5. Verify UI changes:
    // a. The task should be gone from the "pending" list.
    cy.contains('div', 'Execução de Tarefas')
      .should('not.contain', 'Revisão Periódica');
    cy.contains('div', 'Execução de Tarefas')
      .contains('Nenhuma tarefa pendente.')
      .should('be.visible');

    // b. The task should now appear in the "completed" list.
    cy.contains('div', 'Histórico de Tarefas Concluídas')
      .contains('Revisão Periódica')
      .should('be.visible');

    // c. A new rating history entry should be visible.
    cy.contains('div', 'Histórico de Ratings e Sentimentos')
      .contains('Positivo')
      .should('be.visible');
  });
});

import React, { useState, useMemo, useRef } from 'react';
import type { Operation, Event, Task, RatingHistoryEntry, Rating, Sentiment, TaskRule } from '../types';
import { TaskStatus, ratingOptions, WatchlistStatus, Sentiment as SentimentEnum } from '../types';
import { PlusCircleIcon, CheckCircleIcon, EyeIcon, ArrowUpIcon, ArrowRightIcon, ArrowDownIcon, BellIcon, PencilIcon, TrashIcon } from './icons/Icons';
import EventForm from './EventForm';
import WatchlistChangeForm from './WatchlistChangeForm';
import ReviewCompletionForm from './ReviewCompletionForm';
import TaskRuleForm from './TaskRuleForm';
import Modal from './Modal';

interface OperationDetailProps {
  operation: Operation;
  onUpdateOperation: (updatedOperation: Operation) => void;
  onOpenNewTaskModal: (operationId: number) => void;
}

const InfoCard: React.FC<{ title: string; children: React.ReactNode; }> = ({ title, children }) => (
    <div className="bg-gray-50 p-3 rounded-md">
        <h4 className="text-xs text-gray-500 font-semibold uppercase">{title}</h4>
        <p className="text-gray-800 font-medium">{children}</p>
    </div>
);

const getRatingChange = (currentRating: Rating, previousRating: Rating | undefined): 'up' | 'down' | 'neutral' => {
    if (!previousRating || currentRating === previousRating) {
        return 'neutral';
    }
    const currentIndex = ratingOptions.indexOf(currentRating);
    const previousIndex = ratingOptions.indexOf(previousRating);

    if (currentIndex < 0 || previousIndex < 0) return 'neutral';

    if (currentIndex < previousIndex) return 'up'; // Better rating, e.g., index 1 (Baa1) is better than index 2 (Baa3)
    if (currentIndex > previousIndex) return 'down'; // Worse rating
    return 'neutral';
};

const RatingChangeIndicator: React.FC<{ change: 'up' | 'down' | 'neutral' }> = ({ change }) => {
    if (change === 'up') {
        return <ArrowUpIcon className="w-4 h-4 text-green-600" title="Upgrade" />;
    }
    if (change === 'down') {
        return <ArrowDownIcon className="w-4 h-4 text-red-600" title="Downgrade" />;
    }
    return <ArrowRightIcon className="w-4 h-4 text-gray-400" title="Sem alteração" />;
};


const OperationDetail: React.FC<OperationDetailProps> = ({ operation, onUpdateOperation, onOpenNewTaskModal }) => {
    const [isEventFormOpen, setIsEventFormOpen] = useState(false);
    const [isWatchlistFormOpen, setIsWatchlistFormOpen] = useState(false);
    const [isReviewFormOpen, setIsReviewFormOpen] = useState(false);

    const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
    const [reviewTaskToComplete, setReviewTaskToComplete] = useState<Task | null>(null);

    const [expandedEventId, setExpandedEventId] = useState<number | null>(null);
    const eventRefs = useRef<Record<number, HTMLDivElement | null>>({});

    // State for filtering events
    const [eventDateFilter, setEventDateFilter] = useState({ start: '', end: '' });
    const [eventTypeFilter, setEventTypeFilter] = useState('Todos');
    const [eventPersonFilter, setEventPersonFilter] = useState('Todos');

    // State for filtering tasks
    const [taskStatusFilter, setTaskStatusFilter] = useState<'all' | 'pending' | 'overdue'>('all');
    const [taskDateFilter, setTaskDateFilter] = useState({ start: '', end: '' });

    // State for managing task rules
    const [ruleToEdit, setRuleToEdit] = useState<TaskRule | null>(null);
    const [ruleToDelete, setRuleToDelete] = useState<TaskRule | null>(null);


    const tasks = operation.tasks || [];

    const activeTasks = useMemo(() => {
        return tasks
            .filter(t => t.status === TaskStatus.PENDING || t.status === TaskStatus.OVERDUE)
            .filter(task => { // Status filter
                if (taskStatusFilter === 'all') return true;
                if (taskStatusFilter === 'pending') return task.status === TaskStatus.PENDING;
                if (taskStatusFilter === 'overdue') return task.status === TaskStatus.OVERDUE;
                return true;
            })
            .filter(task => { // Date filter
                if (!taskDateFilter.start && !taskDateFilter.end) return true;
                const taskDate = new Date(task.dueDate);
                taskDate.setHours(0,0,0,0);
                const startDate = taskDateFilter.start ? new Date(taskDateFilter.start) : null;
                const endDate = taskDateFilter.end ? new Date(taskDateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && taskDate < startDate) return false;
                if (endDate && taskDate > endDate) return false;
                return true;
            })
            .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks, taskStatusFilter, taskDateFilter]);

    const completedTasks = useMemo(() => {
        return tasks.filter(t => t.status === TaskStatus.COMPLETED)
            .sort((a, b) => {
                const eventA = operation.events.find(e => e.completedTaskId === a.id);
                const eventB = operation.events.find(e => e.completedTaskId === b.id);
                return (eventB ? new Date(eventB.date).getTime() : 0) - (eventA ? new Date(eventA.date).getTime() : 0);
            });
    }, [tasks, operation.events]);

    const uniqueEventTypes = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.type))], [operation.events]);
    const uniqueRegisteredBy = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.registeredBy))], [operation.events]);

    const filteredEvents = useMemo(() => {
        return [...operation.events]
            .filter(event => {
                if (!eventDateFilter.start && !eventDateFilter.end) return true;
                const eventDate = new Date(event.date);
                eventDate.setHours(0,0,0,0);
                const startDate = eventDateFilter.start ? new Date(eventDateFilter.start) : null;
                const endDate = eventDateFilter.end ? new Date(eventDateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && eventDate < startDate) return false;
                if (endDate && eventDate > endDate) return false;
                return true;
            })
            .filter(event => eventTypeFilter === 'Todos' || event.type === eventTypeFilter)
            .filter(event => eventPersonFilter === 'Todos' || event.registeredBy === eventPersonFilter)
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.events, eventDateFilter, eventTypeFilter, eventPersonFilter]);

    const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
        const eventToSave: Partial<Event> = { ...newEvent };
        if (taskToComplete) {
            eventToSave.completedTaskId = taskToComplete.id;
        }

        const updatedOperation = {
            ...operation,
            events: [...operation.events, { ...eventToSave, id: Date.now() } as Event]
        };
        onUpdateOperation(updatedOperation);

        setTaskToComplete(null);
        setIsEventFormOpen(false);
    };

    const handleCompleteTaskClick = (task: Task) => {
        if (task.ruleName === 'Revisão Periódica') {
            setReviewTaskToComplete(task);
            setIsReviewFormOpen(true);
        } else {
            setTaskToComplete(task);
            setIsEventFormOpen(true);
        }
    };

    const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
        const newEventId = Date.now();
        const eventToSave: Event = {
            ...data.event,
            id: newEventId,
            completedTaskId: reviewTaskToComplete?.id
        };

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            sentiment: data.sentiment, // Use sentiment from form
            eventId: newEventId,
        };

        const updatedOperation: Operation = {
            ...operation,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
            ratingHistory: [...operation.ratingHistory, newHistoryEntry]
        };

        onUpdateOperation(updatedOperation);
        setReviewTaskToComplete(null);
        setIsReviewFormOpen(false);
    };

    const handleSaveWatchlistChange = (data: { watchlist: WatchlistStatus, ratingOp: Rating, ratingGroup: Rating, event: Omit<Event, 'id'>}) => {
        const newEventId = Date.now();
        const eventToSave: Event = { ...data.event, id: newEventId };

        const oldWatchlistIndex = Object.values(WatchlistStatus).indexOf(operation.watchlist);
        const newWatchlistIndex = Object.values(WatchlistStatus).indexOf(data.watchlist);
        const oldRatingOpIndex = ratingOptions.indexOf(operation.ratingOperation);
        const newRatingOpIndex = ratingOptions.indexOf(data.ratingOp);
        const oldRatingGroupIndex = ratingOptions.indexOf(operation.ratingGroup);
        const newRatingGroupIndex = ratingOptions.indexOf(data.ratingGroup);

        let sentiment: Sentiment = SentimentEnum.NEUTRO;

        if (newWatchlistIndex > oldWatchlistIndex) {
            sentiment = SentimentEnum.NEGATIVO;
        } else if (newWatchlistIndex < oldWatchlistIndex) {
            sentiment = SentimentEnum.POSITIVO;
        } else { 
            if (newRatingOpIndex < oldRatingOpIndex) {
                sentiment = SentimentEnum.POSITIVO;
            } else if (newRatingOpIndex > oldRatingOpIndex) {
                sentiment = SentimentEnum.NEGATIVO;
            } else {
                if (newRatingGroupIndex < oldRatingGroupIndex) {
                    sentiment = SentimentEnum.POSITIVO;
                } else if (newRatingGroupIndex > oldRatingGroupIndex) {
                    sentiment = SentimentEnum.NEGATIVO;
                }
            }
        }

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            sentiment: sentiment,
            eventId: newEventId,
        };

        const updatedOperation: Operation = {
            ...operation,
            watchlist: data.watchlist,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
            ratingHistory: [...operation.ratingHistory, newHistoryEntry],
        };

        onUpdateOperation(updatedOperation);
        setIsWatchlistFormOpen(false);
    };

    const handleUpdateRule = (updatedRuleData: Omit<TaskRule, 'id'>) => {
        if (!ruleToEdit) return;
        const updatedRule = { ...ruleToEdit, ...updatedRuleData };
        const updatedOperation = {
            ...operation,
            taskRules: operation.taskRules.map(r => r.id === ruleToEdit.id ? updatedRule : r)
        };
        onUpdateOperation(updatedOperation);
        setRuleToEdit(null);
    };

    const handleConfirmDeleteRule = () => {
        if (!ruleToDelete) return;
        const updatedOperation = {
            ...operation,
            taskRules: operation.taskRules.filter(r => r.id !== ruleToDelete.id)
        };
        onUpdateOperation(updatedOperation);
        setRuleToDelete(null);
    };

    const handleViewEventClick = (taskId: string) => {
        const completionEvent = operation.events.find(e => e.completedTaskId === taskId);
        if (completionEvent) {
            setExpandedEventId(completionEvent.id);
            const eventElement = eventRefs.current[completionEvent.id];
            if (eventElement) {
                eventElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }

    const watchlistColorClasses = {
      [WatchlistStatus.VERDE]: 'bg-green-500 text-white hover:bg-green-600',
      [WatchlistStatus.AMARELO]: 'bg-yellow-400 text-yellow-900 hover:bg-yellow-500',
      [WatchlistStatus.ROSA]: 'bg-pink-500 text-white hover:bg-pink-600',
      [WatchlistStatus.VERMELHO]: 'bg-red-600 text-white hover:bg-red-700',
    };

    return (
        <div className="space-y-8">
            {isEventFormOpen && (
                <EventForm 
                    onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                    onSave={handleAddEvent}
                    analystName={operation.responsibleAnalyst}
                    prefilledTitle={taskToComplete ? `Conclusão: ${taskToComplete.ruleName}` : ''}
                />
            )}
            {isWatchlistFormOpen && (
                <WatchlistChangeForm
                    operation={operation}
                    onClose={() => setIsWatchlistFormOpen(false)}
                    onSave={handleSaveWatchlistChange}
                />
            )}
            {isReviewFormOpen && reviewTaskToComplete && (
                <ReviewCompletionForm
                    task={reviewTaskToComplete}
                    operation={operation}
                    onClose={() => setIsReviewFormOpen(false)}
                    onSave={handleSaveReview}
                />
            )}
            {ruleToEdit && (
                <Modal isOpen={true} onClose={() => setRuleToEdit(null)} title="Editar Regra de Tarefa">
                    <TaskRuleForm
                        onClose={() => setRuleToEdit(null)}
                        onSave={handleUpdateRule}
                        initialData={ruleToEdit}
                    />
                </Modal>
            )}
            {ruleToDelete && (
                 <Modal
                    isOpen={true}
                    onClose={() => setRuleToDelete(null)}
                    title={`Deletar Regra: ${ruleToDelete.name}`}
                >
                    <div className="text-center">
                        <p className="text-lg text-gray-700 mb-6">
                        Você tem certeza que deseja deletar esta regra de tarefa?
                        </p>
                        <div className="flex justify-center gap-4">
                        <button
                            onClick={() => setRuleToDelete(null)}
                            className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleConfirmDeleteRule}
                            className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
                        >
                            Confirmar Deleção
                        </button>
                        </div>
                    </div>
                </Modal>
            )}


            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-start mb-4">
                    <h2 className="text-2xl font-bold text-gray-800">{operation.name}</h2>
                    <button onClick={() => setIsWatchlistFormOpen(true)} className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors duration-200 ${watchlistColorClasses[operation.watchlist]}`}>
                        <BellIcon className="w-5 h-5"/> Alterar Watchlist / Rating
                    </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <InfoCard title="Projetos">{operation.projects.map(p => p.name).join(', ')}</InfoCard>
                    <InfoCard title="Garantias">{operation.guarantees.map(g => g.name).join(', ')}</InfoCard>
                    <InfoCard title="Segmento">{operation.segmento}</InfoCard>
                    <InfoCard title="Covenant LTV">{operation.covenants.ltv ?? 'N/A'}</InfoCard>
                    <InfoCard title="Covenant DSCR">{operation.covenants.dscr ?? 'N/A'}</InfoCard>
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-xl font-bold text-gray-700">Histórico de Eventos</h3>
                    <button onClick={() => setIsEventFormOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
                        <PlusCircleIcon className="w-5 h-5"/> Adicionar Evento
                    </button>
                </div>

                <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4">
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                        <div>
                            <label htmlFor="start-date" className="text-sm font-medium text-gray-700">De:</label>
                            <input type="date" id="start-date" value={eventDateFilter.start} onChange={e => setEventDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="end-date" className="text-sm font-medium text-gray-700">Até:</label>
                            <input type="date" id="end-date" value={eventDateFilter.end} onChange={e => setEventDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                        <div>
                            <label htmlFor="type-filter" className="text-sm font-medium text-gray-700">Tipo:</label>
                            <select id="type-filter" value={eventTypeFilter} onChange={e => setEventTypeFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueEventTypes.map(type => <option key={type} value={type}>{type}</option>)}
                            </select>
                        </div>
                        <div>
                            <label htmlFor="person-filter" className="text-sm font-medium text-gray-700">Responsável:</label>
                            <select id="person-filter" value={eventPersonFilter} onChange={e => setEventPersonFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                {uniqueRegisteredBy.map(name => <option key={name} value={name}>{name}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <div className="space-y-2 max-h-96 overflow-y-auto">
                     {filteredEvents.map(event => (
                        <div key={event.id} ref={el => { if(el) eventRefs.current[event.id] = el; }} className={`border border-gray-200 rounded-lg p-4 transition-all duration-300 ${expandedEventId === event.id ? 'bg-blue-50 ring-2 ring-blue-300' : ''}`}>
                            <div className="grid grid-cols-4 md:grid-cols-5 gap-4 items-center">
                                <div className="text-sm font-medium text-gray-600">{new Date(event.date).toLocaleDateString('pt-BR')}</div>
                                <div className="text-sm text-gray-800"><span className="font-semibold">{event.type}</span></div>
                                <div className="col-span-2 md:col-span-2 text-sm text-gray-800">{event.title}</div>
                                <div className="text-right">
                                    <button onClick={() => setExpandedEventId(expandedEventId === event.id ? null : event.id)} className="text-blue-600 hover:text-blue-800 text-sm">
                                        {expandedEventId === event.id ? 'Ver Menos' : 'Ver Mais'}
                                    </button>
                                </div>
                            </div>
                            {expandedEventId === event.id && (
                                <div className="mt-4 pt-4 border-t border-gray-200 space-y-3 text-sm text-gray-700">
                                    <p><strong className="font-semibold text-gray-600">Descrição:</strong> {event.description}</p>
                                    <p><strong className="font-semibold text-gray-600">Registrado por:</strong> {event.registeredBy}</p>
                                    <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>
                                    {event.completedTaskId && <p className="text-xs text-gray-500 italic pt-2">Este evento concluiu a tarefa ID: {event.completedTaskId}</p>}
                                </div>
                            )}
                        </div>
                     ))}
                     {filteredEvents.length === 0 && <p className="text-center text-gray-500 py-4">Nenhum evento encontrado para os filtros selecionados.</p>}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <h3 className="text-xl font-bold text-gray-700 mb-4">Execução de Tarefas</h3>

                    <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
                        <div>
                            <label htmlFor="task-status-filter" className="text-sm font-medium text-gray-700">Status:</label>
                             <select id="task-status-filter" value={taskStatusFilter} onChange={e => setTaskStatusFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                <option value="all">Todas</option>
                                <option value="pending">Pendentes</option>
                                <option value="overdue">Atrasadas</option>
                            </select>
                        </div>
                        <div>
                             <label htmlFor="task-start-date" className="text-sm font-medium text-gray-700">Venc. De:</label>
                             <input type="date" id="task-start-date" value={taskDateFilter.start} onChange={e => setTaskDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                         <div>
                            <label htmlFor="task-end-date" className="text-sm font-medium text-gray-700">Venc. Até:</label>
                            <input type="date" id="task-end-date" value={taskDateFilter.end} onChange={e => setTaskDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                    </div>

                    <div className="space-y-2 max-h-96 overflow-y-auto">
                       {activeTasks.map(task => (
                           <div key={task.id} className={`p-3 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                               <div>
                                   <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                   <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-700'}`}>
                                       Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                   </p>
                               </div>
                               <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                   <CheckCircleIcon className="w-4 h-4" /> Completar
                               </button>
                           </div>
                       ))}
                        {activeTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa pendente para os filtros selecionados.</p>}
                    </div>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-lg">
                     <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-gray-700">Regras de Tarefas</h3>
                         <button onClick={() => onOpenNewTaskModal(operation.id)} className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm">
                            <PlusCircleIcon className="w-5 h-5"/> Adicionar Tarefa
                        </button>
                    </div>
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {operation.taskRules.map(rule => (
                            <div key={rule.id} className="p-3 bg-gray-50 rounded-md flex justify-between items-center">
                                <div>
                                    <p className="font-semibold text-gray-800">{rule.name} <span className="text-xs font-normal text-white bg-blue-500 px-2 py-0.5 rounded-full">{rule.frequency}</span></p>
                                    <p className="text-sm text-gray-600">{rule.description}</p>
                                    <p className="text-xs text-gray-400 mt-1">
                                        {new Date(rule.startDate).toLocaleDateString('pt-BR')} até {new Date(rule.endDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <button onClick={() => setRuleToEdit(rule)} className="text-gray-400 hover:text-blue-600" title="Editar Regra">
                                        <PencilIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => setRuleToDelete(rule)} className="text-gray-400 hover:text-red-600" title="Deletar Regra">
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Ratings e Sentimentos</h3>
                <div className="space-y-3 max-h-96 overflow-y-auto">
                    {operation.ratingHistory.length > 0 ? (
                        [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((entry, index, array) => {
                             const previousEntry = array[index + 1]; // The one before chronologically
                             const opRatingChange = getRatingChange(entry.ratingOperation, previousEntry?.ratingOperation);
                             const groupRatingChange = getRatingChange(entry.ratingGroup, previousEntry?.ratingGroup);

                            return (
                                <div key={entry.id} className="p-3 bg-gray-50 rounded-md grid grid-cols-4 gap-4 items-center">
                                    <div className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</div>
                                    <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                        <span className="text-xs text-gray-500">Op: </span>
                                        <RatingChangeIndicator change={opRatingChange} />
                                        {entry.ratingOperation}
                                    </div>
                                    <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                        <span className="text-xs text-gray-500">Grupo: </span>
                                        <RatingChangeIndicator change={groupRatingChange} />
                                        {entry.ratingGroup}
                                    </div>
                                    <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                        {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                        {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                        {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                        {entry.sentiment}
                                    </div>
                                </div>
                            );
                        })
                    ) : (
                        <p className="text-center text-gray-500 py-4">Nenhum histórico de rating para esta operação.</p>
                    )}
                </div>
            </div>
             <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Tarefas Concluídas</h3>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {completedTasks.map(task => {
                        const completionEvent = operation.events.find(e => e.completedTaskId === task.id);
                        return (
                            <div key={task.id} className="p-3 bg-green-50 rounded-md flex justify-between items-center border-l-4 border-green-500">
                                <div>
                                    <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                    <p className="text-sm text-gray-600">
                                        Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                {completionEvent && (
                                    <button onClick={() => handleViewEventClick(task.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm">
                                        <EyeIcon className="w-4 h-4" /> Ver Evento
                                    </button>
                                )}
                            </div>
                        )
                    })}
                    {completedTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa foi concluída ainda.</p>}
                </div>
            </div>
        </div>
    );
};

export default OperationDetail;

import React, { useState, useEffect } from 'react';
import type { TaskRule } from '../types';

interface TaskRuleFormProps {
  onClose: () => void;
  onSave: (rule: Omit<TaskRule, 'id'>) => void;
  initialData?: TaskRule;
}

// Helper component moved outside of the main component to prevent re-creation on each render.
const Label: React.FC<{htmlFor: string; children: React.ReactNode}> = ({ htmlFor, children }) => <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">{children}</label>;

const TaskRuleForm: React.FC<TaskRuleFormProps> = ({ onClose, onSave, initialData }) => {
  const [name, setName] = useState('');
  const [frequency, setFrequency] = useState<TaskRule['frequency']>('Mensal');
  const [startDate, setStartDate] = useState(new Date().toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState('');
  const [description, setDescription] = useState('');

  useEffect(() => {
    if (initialData) {
        setName(initialData.name);
        setFrequency(initialData.frequency);
        setStartDate(new Date(initialData.startDate).toISOString().split('T')[0]);
        setEndDate(new Date(initialData.endDate).toISOString().split('T')[0]);
        setDescription(initialData.description);
    }
  }, [initialData]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      name,
      frequency,
      startDate: new Date(startDate).toISOString(),
      endDate: new Date(endDate).toISOString(),
      description,
    });
    onClose();
  };

  return (
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
            <Label htmlFor="name">Nome da Regra</Label>
            <input id="name" type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
                <Label htmlFor="frequency">Frequência</Label>
                <select id="frequency" value={frequency} onChange={e => setFrequency(e.target.value as TaskRule['frequency'])} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500">
                    <option>Diário</option>
                    <option>Semanal</option>
                    <option>Quinzenal</option>
                    <option>Mensal</option>
                    <option>Trimestral</option>
                    <option>Semestral</option>
                    <option>Anual</option>
                </select>
            </div>
            <div>
                <Label htmlFor="startDate">Data de Início</Label>
                <input id="startDate" type="date" value={startDate} onChange={e => setStartDate(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
            <div>
                <Label htmlFor="endDate">Data de Fim</Label>
                <input id="endDate" type="date" value={endDate} onChange={e => setEndDate(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
        </div>
        <div>
            <Label htmlFor="description">Descrição</Label>
            <textarea id="description" value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>
         <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">Cancelar</button>
          <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">
            {initialData ? 'Salvar Alterações' : 'Salvar Regra'}
          </button>
        </div>
      </form>
  );
};

export default TaskRuleForm;

