    // a. The task should be gone from the "pending" list.
    cy.contains('div', 'Execução de Tarefas')
      .should('not.contain', 'Revisão Periódica');
    cy.contains('div', 'Execução de Tarefas')
      .contains('Nenhuma tarefa pendente.')
      .should('be.visible');

    // b. The task should now appear in the "completed" list.
    cy.contains('div', 'Histórico de Tarefas Concluídas')
      .contains('Revisão Periódica')
      .should('be.visible');

    // c. A new rating history entry should be visible.
    cy.contains('div', 'Histórico de Ratings e Sentimentos')
      .contains('Positivo')
      .should('be.visible');
  });
});

