import React, { useState, useEffect } from 'react';
import type { TaskRule, Task } from '../types';

interface AdHocTaskFormProps {
  onClose: () => void;
  onSave: (rule: Omit<TaskRule, 'id'>) => void;
  initialTask?: Task;
}

const Label: React.FC<{htmlFor: string; children: React.ReactNode}> = ({ htmlFor, children }) => <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">{children}</label>;

const AdHocTaskForm: React.FC<AdHocTaskFormProps> = ({ onClose, onSave, initialTask }) => {
  const [name, setName] = useState('');
  const [dueDate, setDueDate] = useState(new Date().toISOString().split('T')[0]);
  const [description, setDescription] = useState('');

  useEffect(() => {
    if (initialTask) {
        setName(initialTask.ruleName);
        setDueDate(new Date(initialTask.dueDate).toISOString().split('T')[0]);
        // A description might not exist for a generated task, so we default to an empty string.
        setDescription('');
    }
  }, [initialTask]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      name,
      frequency: 'Pontual',
      startDate: new Date(dueDate).toISOString(),
      endDate: new Date(dueDate).toISOString(), // For pontual, start and end are the same
      description,
    });
    onClose();
  };

  return (
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
                <Label htmlFor="adhoc-name">Nome da Tarefa</Label>
                <input id="adhoc-name" type="text" value={name} onChange={e => setName(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
            <div>
                <Label htmlFor="adhoc-dueDate">Data de Vencimento</Label>
                <input id="adhoc-dueDate" type="date" value={dueDate} onChange={e => setDueDate(e.target.value)} required className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
        </div>
        <div>
            <Label htmlFor="adhoc-description">Descrição</Label>
            <textarea id="adhoc-description" value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />
        </div>
         <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">Cancelar</button>
          <button type="submit" className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">
            {initialTask ? 'Salvar Alterações' : 'Salvar Tarefa'}
          </button>
        </div>
      </form>
  );
};

export default AdHocTaskForm;

from datetime import date, timedelta, datetime

def get_next_date(current_date, frequency):
    """
    Calculates the next due date based on a given frequency.
    Note: This is a simplified implementation for monthly/yearly steps.
    """
    next_d = current_date
    if frequency == 'Diário':
        next_d += timedelta(days=1)
    elif frequency == 'Semanal':
        next_d += timedelta(days=7)
    elif frequency == 'Quinzenal':
        next_d += timedelta(days=15)
    elif frequency == 'Mensal':
        # A more robust library like dateutil.relativedelta is better for edge cases
        try:
            next_d = next_d.replace(month=next_d.month + 1)
        except ValueError: # Handles months with different number of days
            if next_d.month == 12:
                next_d = next_d.replace(year=next_d.year + 1, month=1)
            else:
                 # Go to the first day of the month after next, then subtract one day
                next_d = next_d.replace(month=next_d.month + 2, day=1) - timedelta(days=1)

    elif frequency == 'Trimestral':
        try:
            next_d = next_d.replace(month=next_d.month + 3)
        except ValueError:
             # Logic to handle jumping over year-end and different month lengths
            new_month = next_d.month + 3
            new_year = next_d.year
            if new_month > 12:
                new_year += 1
                new_month -= 12
            next_d = next_d.replace(year=new_year, month=new_month)

    elif frequency == 'Semestral':
        try:
            next_d = next_d.replace(month=next_d.month + 6)
        except ValueError:
            new_month = next_d.month + 6
            new_year = next_d.year
            if new_month > 12:
                new_year += 1
                new_month -= 12
            next_d = next_d.replace(year=new_year, month=new_month)

    elif frequency == 'Anual':
        next_d = next_d.replace(year=next_d.year + 1)
    return next_d

def generate_tasks_for_rule(operation, rule, task_exceptions):
    """ Generates all task instances for a single rule. """
    tasks = []
    # Use a set for efficient lookup
    completed_task_ids = {e.get('completedTaskId') for e in operation.get('events', []) if e.get('completedTaskId')}

    today = date.today()

    # Skip if rule has no dates
    if not rule.get('startDate') or not rule.get('endDate'):
        return []

    # Handle one-off 'Pontual' tasks
    if rule['frequency'] == 'Pontual':
        due_date = datetime.fromisoformat(rule['startDate']).date()
        task_id = f"op{operation['id']}-rule{rule['id']}-{due_date.isoformat()}"

        if task_id in task_exceptions:
            return []

        status = 'Concluída' if task_id in completed_task_ids else 'Atrasada' if due_date < today else 'Pendente'

        tasks.append({
            'id': task_id,
            'operationId': operation['id'],
            'ruleId': rule['id'],
            'ruleName': rule['name'],
            'dueDate': due_date.isoformat() + "T00:00:00",
            'status': status,
        })
        return tasks

    # Handle recurring tasks
    current_date = datetime.fromisoformat(rule['startDate']).date()
    end_date = datetime.fromisoformat(rule['endDate']).date()

    while current_date <= end_date:
        due_date = current_date
        task_id = f"op{operation['id']}-rule{rule['id']}-{due_date.isoformat()}"

        if task_id not in task_exceptions:
            status = 'Concluída' if task_id in completed_task_ids else 'Atrasada' if due_date < today else 'Pendente'

            tasks.append({
                'id': task_id,
                'operationId': operation['id'],
                'ruleId': rule['id'],
                'ruleName': rule['name'],
                'dueDate': due_date.isoformat() + "T00:00:00",
                'status': status,
            })
        current_date = get_next_date(current_date, rule['frequency'])

    return tasks

def generate_tasks_for_operation(operation, task_exceptions):
    """ Generates all task instances for all rules within an operation. """
    all_tasks = []
    for rule in operation.get('taskRules', []):
        all_tasks.extend(generate_tasks_for_rule(operation, rule, task_exceptions))
    return all_tasks

import React, { useState, useEffect, useMemo } from 'react';
import type { AuditLog } from '../types';

interface AuditLogPageProps {
    apiUrl: string;
}

const AuditLogPage: React.FC<AuditLogPageProps> = ({ apiUrl }) => {
    const [logs, setLogs] = useState<AuditLog[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    // Filter states
    const [userFilter, setUserFilter] = useState('All');
    const [actionFilter, setActionFilter] = useState('All');
    const [dateFilter, setDateFilter] = useState({ start: '', end: '' });

    useEffect(() => {
        const fetchLogs = async () => {
            setIsLoading(true);
            try {
                const response = await fetch(`${apiUrl}/api/audit_logs`, { credentials: 'include' });
                if (!response.ok) {
                    throw new Error(`Server responded with status: ${response.status}`);
                }
                const data: AuditLog[] = await response.json();
                setLogs(data);
            } catch (err) {
                 if (err instanceof Error) {
                    setError(err.message);
                } else {
                    setError("An unknown network error occurred.");
                }
            } finally {
                setIsLoading(false);
            }
        };
        fetchLogs();
    }, [apiUrl]);

    const uniqueUsers = useMemo(() => ['All', ...new Set(logs.map(log => log.user_name))], [logs]);
    const uniqueActions = useMemo(() => ['All', ...new Set(logs.map(log => log.action))], [logs]);

    const filteredLogs = useMemo(() => {
        return logs
            .filter(log => userFilter === 'All' || log.user_name === userFilter)
            .filter(log => actionFilter === 'All' || log.action === actionFilter)
            .filter(log => {
                if (!dateFilter.start && !dateFilter.end) return true;
                const logDate = new Date(log.timestamp);
                logDate.setHours(0,0,0,0);
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);

                if (startDate && logDate < startDate) return false;
                if (endDate && logDate > endDate) return false;
                return true;
            });
    }, [logs, userFilter, actionFilter, dateFilter]);

    const getActionBadge = (action: AuditLog['action']) => {
        const styles = {
            CREATE: 'bg-green-100 text-green-800',
            UPDATE: 'bg-yellow-100 text-yellow-800',
            DELETE: 'bg-red-100 text-red-800',
        };
        return <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${styles[action]}`}>{action}</span>;
    };

    if (isLoading) return <div className="text-center p-8">Carregando logs...</div>;
    if (error) return <div className="text-center p-8 text-red-600">Erro ao carregar logs: {error}</div>;

    return (
        <div className="bg-white p-6 rounded-lg shadow-lg">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">Log de Auditoria</h2>

            <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                    <label htmlFor="user-filter" className="text-sm font-medium text-gray-700">Usuário</label>
                    <select id="user-filter" value={userFilter} onChange={e => setUserFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                        {uniqueUsers.map(user => <option key={user} value={user}>{user}</option>)}
                    </select>
                </div>
                <div>
                    <label htmlFor="action-filter" className="text-sm font-medium text-gray-700">Ação</label>
                    <select id="action-filter" value={actionFilter} onChange={e => setActionFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                        {uniqueActions.map(action => <option key={action} value={action}>{action}</option>)}
                    </select>
                </div>
                 <div>
                    <label htmlFor="start-date-filter" className="text-sm font-medium text-gray-700">De</label>
                    <input type="date" id="start-date-filter" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                </div>
                 <div>
                    <label htmlFor="end-date-filter" className="text-sm font-medium text-gray-700">Até</label>
                    <input type="date" id="end-date-filter" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                </div>
            </div>

            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Data</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Usuário</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ação</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Entidade</th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Detalhes</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {filteredLogs.map(log => (
                            <tr key={log.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(log.timestamp).toLocaleString('pt-BR')}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700 font-medium">{log.user_name}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{getActionBadge(log.action)}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <span className="font-semibold">{log.entity_type}</span> (ID: {log.entity_id})
                                </td>
                                <td className="px-6 py-4 text-sm text-gray-600">{log.details}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                 {filteredLogs.length === 0 && (
                    <div className="text-center py-8 text-gray-500">
                        Nenhum log encontrado para os filtros selecionados.
                    </div>
                )}
            </div>
        </div>
    );
};

export default AuditLogPage;

