// FIX: Moved the triple-slash directive to the absolute top of the file. This is required for TypeScript to correctly process it and load the Cypress global types, resolving errors like "Cannot find name 'cy'".
/// <reference types="cypress" />

describe('Operation Detail Page', () => {
  beforeEach(() => {
    // Intercept the initial GET request and provide mock data.
    cy.intercept('GET', '**/api/operations', {
      fixture: 'operations.json',
    }).as('getOperations');

    // Intercept the PUT request that will be used for updates.
    // We provide a static response that mirrors the request body,
    // which is what our optimized backend does.
    cy.intercept('PUT', '**/api/operations/1', (req) => {
      req.reply({
        statusCode: 200,
        body: req.body,
      });
    }).as('updateOperation');

    // Visit the root of our application.
    cy.visit('/');

    // Wait for the initial data to load.
    cy.wait('@getOperations');

    // Navigate to the detail page for our test operation.
    cy.contains('button', 'Detalhes').click();

    // Assert we are on the correct page by checking the header.
    cy.contains('h2', 'CRI Test Operation').should('be.visible');
  });

  it('should display the core details of the operation', () => {
    // Check for key information cards to ensure the data from the fixture is rendered.
    cy.contains('div', 'Project Cypress').should('be.visible');
    cy.contains('div', 'Infra').should('be.visible');
    cy.contains('div', '0.6').should('be.visible'); // LTV
    cy.contains('div', '1.5').should('be.visible'); // DSCR
  });

  it('should allow adding a new event and display it in the history', () => {
    const eventTitle = 'Reunião de Alinhamento Cypress';
    const eventDescription = 'Discussão sobre os próximos passos do projeto.';

    // 1. Open the event form modal.
    cy.contains('button', 'Adicionar Evento').click();

    // 2. Fill out the form.
    cy.get('input#title').type(eventTitle);
    cy.get('textarea#description').type(eventDescription);
    cy.get('textarea#nextSteps').type('Agendar próxima reunião.');

    // 3. Save the event.
    cy.contains('button', 'Salvar Evento').click();

    // 4. Wait for the API call and assert its request body.
    cy.wait('@updateOperation').its('request.body.events').should('have.length', 2);
    cy.wait('@updateOperation').its('request.body.events.1').should('deep.include', {
        title: eventTitle,
        description: eventDescription
    });

    // 5. Verify the new event is visible in the UI (testing the optimistic update).
    cy.contains(eventTitle).should('be.visible');
  });

  it('should allow completing a review task and update relevant sections', () => {
    // 1. Find the pending review task and click "Completar".
    cy.contains('div', 'Execução de Tarefas')
      .contains('div', 'Revisão Periódica')
      .find('button', 'Completar')
      .click();

    // 2. The review completion modal should appear. Fill it out.
    cy.get('textarea#review-description').type('Revisão trimestral concluída sem ressalvas.');
    cy.get('select#review-rating-op').select('A4'); // Simulate an upgrade
    cy.get('select#review-sentiment').select('Positivo');

    // 3. Save the review.
    cy.contains('button', 'Concluir e Salvar Revisão').click();

    // 4. Wait for the API call and verify the payload.
    cy.wait('@updateOperation').its('request.body').should((body) => {
        expect(body.ratingOperation).to.equal('A4'); // Check if rating was updated
        expect(body.ratingHistory).to.have.length(2); // Check if history was added
        expect(body.events).to.have.length(2); // Check if event was added
        expect(body.events[1].completedTaskId).to.equal('op1-rule1-2024-07-30');
    });

    // 5. Verify UI changes:
    // a. The task should be gone from the "pending" list.
    cy.contains('div', 'Execução de Tarefas')
      .should('not.contain', 'Revisão Periódica');
    cy.contains('div', 'Execução de Tarefas')
      .contains('Nenhuma tarefa pendente.')
      .should('be.visible');

    // b. The task should now appear in the "completed" list.
    cy.contains('div', 'Histórico de Tarefas Concluídas')
      .contains('Revisão Periódica')
      .should('be.visible');

    // c. A new rating history entry should be visible.
    cy.contains('div', 'Histórico de Ratings e Sentimentos')
      .contains('Positivo')
      .should('be.visible');
  });
});

