import React, { useState, useMemo, useEffect, useCallback } from 'react';
import type { Operation, Task, TaskRule } from './types';
import { Page } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); // Clear previous errors on a new attempt
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    // Business logic for task generation is now on the backend.
    // The frontend just consumes the 'tasks' array.
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    // Business logic for auto-generating task rules is now on the backend.
    // The frontend sends the raw form data.
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Failed to save operation');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];

    // Optimistic UI Update: Update the state immediately for a responsive feel.
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Failed to update operation on the server.');
      }
      // The backend now sends back the updated operation, which might have refreshed data.
      // We can re-sync the state silently.
      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      // Rollback on error
      setOperations(originalOperations);
      // Here you could also show a toast notification to the user
      // alert("Falha ao salvar as alterações. Tente novamente.");
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }
      setOperations(prev => prev.filter(op => op.id !== operationId));
      // If the currently viewed operation is the one being deleted, navigate away for better UX
      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
    } catch (error) {
      console.error("Error deleting operation:", error);
      // Optionally, show an error message to the user
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];

    // Optimistic UI: Remove task from the specific operation
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));

    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Failed to delete task');

        const updatedOperation = await response.json();
        // Sync state with the server's response
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));

    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations); // Rollback
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];

     // Optimistic UI:
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            // 1. Remove the old task
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            // 2. Create a new ad-hoc rule for the edited task
            const newAdHocRule: TaskRule = {
                id: Date.now(), // Temporary client-side ID
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate).toISOString(),
                endDate: new Date(updates.dueDate).toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks, // Temporarily remove, will be replaced by backend's full list
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));

    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Failed to edit task');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));

    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations); // Rollback
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };


  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            <OverdueOperationsHighlight
              operations={operations}
              onNavigate={handleNavigate}
            />
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import type { Operation, RatingHistoryEntry, Event } from '../types';
import { WatchlistStatus } from '../types';
import { BellIcon, ArrowUpIcon, ArrowRightIcon, ArrowDownIcon } from './icons/Icons';
import WatchlistChangeForm from './WatchlistChangeForm';

interface WatchlistPageProps {
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
}

const WatchlistPage: React.FC<WatchlistPageProps> = ({ operations, onUpdateOperation }) => {
    const [activeFilter, setActiveFilter] = useState<WatchlistStatus | 'All'>('All');
    const [expandedOpId, setExpandedOpId] = useState<number | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [operationToEdit, setOperationToEdit] = useState<Operation | null>(null);

    const filterOptions: (WatchlistStatus | 'All')[] = ['All', ...Object.values(WatchlistStatus)];

    const filteredOperations = useMemo(() => {
        if (activeFilter === 'All') return operations;
        return operations.filter(op => op.watchlist === activeFilter);
    }, [operations, activeFilter]);

    const handleOpenModal = (op: Operation) => {
        setOperationToEdit(op);
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setOperationToEdit(null);
        setIsModalOpen(false);
    };

    const handleSaveChanges = (data: Parameters<typeof onUpdateOperation>[0]) => {
        onUpdateOperation(data);
        handleCloseModal();
    };

    return (
        <div className="space-y-6">
            {isModalOpen && operationToEdit && (
                <WatchlistChangeForm
                    operation={operationToEdit}
                    onClose={handleCloseModal}
                    onSave={(data) => {
                        const { watchlist, ratingOp, ratingGroup, event } = data;
                        const newEventId = Date.now();
                        const eventToSave: Event = { ...event, id: newEventId };

                        const newHistoryEntry: RatingHistoryEntry = {
                            id: Date.now() + 1,
                            date: eventToSave.date,
                            ratingOperation: ratingOp,
                            ratingGroup: ratingGroup,
                            sentiment: event.type === 'Mudança de Watchlist' ? 'Neutro' : 'Positivo', // Simplified for now
                            eventId: newEventId,
                        };

                        const updatedOp = {
                            ...operationToEdit,
                            watchlist,
                            ratingOperation: ratingOp,
                            ratingGroup: ratingGroup,
                            events: [...operationToEdit.events, eventToSave],
                            ratingHistory: [...operationToEdit.ratingHistory, newHistoryEntry],
                        };
                        handleSaveChanges(updatedOp);
                    }}
                />
            )}

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">Gerenciamento de Watchlist</h2>

                {/* Filter Buttons */}
                <div className="flex items-center gap-2 border-b border-gray-200 pb-4 mb-4">
                    {filterOptions.map(status => (
                        <button
                            key={status}
                            onClick={() => setActiveFilter(status)}
                            className={`px-4 py-2 text-sm font-semibold rounded-full transition-colors duration-200 ${
                                activeFilter === status
                                ? 'bg-blue-600 text-white shadow'
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                            }`}
                        >
                            {status === 'All' ? 'Todas' : status}
                        </button>
                    ))}
                </div>

                {/* Operations List */}
                <div className="space-y-4">
                    {filteredOperations.map(op => (
                        <OperationCard 
                            key={op.id}
                            operation={op}
                            isExpanded={expandedOpId === op.id}
                            onToggle={() => setExpandedOpId(prev => prev === op.id ? null : op.id)}
                            onOpenUpdateModal={() => handleOpenModal(op)}
                        />
                    ))}
                    {filteredOperations.length === 0 && (
                        <div className="text-center py-12 text-gray-500">
                            <p>Nenhuma operação encontrada para o filtro "{activeFilter}".</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

// --- Sub-component for Operation Card ---

interface OperationCardProps {
    operation: Operation;
    isExpanded: boolean;
    onToggle: () => void;
    onOpenUpdateModal: () => void;
}

const OperationCard: React.FC<OperationCardProps> = ({ operation, isExpanded, onToggle, onOpenUpdateModal }) => {
    const statusClasses = {
        [WatchlistStatus.VERDE]: { border: 'border-green-500', bg: 'bg-green-50' },
        [WatchlistStatus.AMARELO]: { border: 'border-yellow-500', bg: 'bg-yellow-50' },
        [WatchlistStatus.ROSA]: { border: 'border-pink-500', bg: 'bg-pink-50' },
        [WatchlistStatus.VERMELHO]: { border: 'border-red-500', bg: 'bg-red-50' },
    };

    const sortedHistory = useMemo(() => {
        return [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.ratingHistory]);

    return (
        <div className={`border-l-4 rounded-r-lg shadow-sm transition-all duration-300 ${statusClasses[operation.watchlist].border}`}>
            <div 
                className={`p-4 cursor-pointer ${isExpanded ? statusClasses[operation.watchlist].bg : 'bg-white hover:bg-gray-50'}`}
                onClick={onToggle}
            >
                <div className="flex justify-between items-center">
                    <div className="flex-1">
                        <p className="font-bold text-lg text-gray-800">{operation.name}</p>
                        <div className="flex items-center gap-4 text-sm text-gray-600 mt-1">
                            <span>Analista: <span className="font-medium">{operation.responsibleAnalyst}</span></span>
                            <span>Rating Op: <span className="font-medium">{operation.ratingOperation}</span></span>
                             <span>Rating Grupo: <span className="font-medium">{operation.ratingGroup}</span></span>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <button onClick={(e) => { e.stopPropagation(); onOpenUpdateModal(); }} className="flex items-center gap-2 px-3 py-2 bg-blue-100 text-blue-800 rounded-lg hover:bg-blue-200 text-sm font-semibold">
                            <BellIcon className="w-4 h-4" /> Alterar Status
                        </button>
                        <span className={`transform transition-transform duration-200 ${isExpanded ? 'rotate-180' : 'rotate-0'}`}>
                            <svg className="w-6 h-6 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </span>
                    </div>
                </div>
            </div>

            {isExpanded && (
                <div className="p-4 border-t border-gray-200 bg-white space-y-4">
                    <h4 className="font-semibold text-gray-700">Histórico de Alterações</h4>
                    {sortedHistory.length > 0 ? (
                        sortedHistory.map(entry => {
                            const event = operation.events.find(e => e.id === entry.eventId);
                            return (
                                <div key={entry.id} className="p-3 border rounded-md bg-gray-50">
                                    <div className="grid grid-cols-4 gap-4 items-center mb-3">
                                        <p className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</p>
                                        <p className="text-sm">Op: {entry.ratingOperation}</p>
                                        <p className="text-sm">Grupo: {entry.ratingGroup}</p>
                                        <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                            {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                            {entry.sentiment}
                                        </div>
                                    </div>
                                    {event && (
                                        <div className="border-t border-gray-200 pt-3 text-sm space-y-2">
                                            <p><strong className="font-semibold text-gray-600">Evento:</strong> {event.title}</p>
                                            <p className="text-gray-700">{event.description}</p>
                                            {event.nextSteps && <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>}
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    ) : (
                        <p className="text-center text-gray-500 py-4">Nenhum histórico de alteração para esta operação.</p>
                    )}
                </div>
            )}
        </div>
    );
};

