                                    <button onClick={() => setRuleToDelete(rule)} className="text-gray-400 hover:text-red-600" title="Deletar Regra">
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Ratings e Sentimentos</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {operation.ratingHistory.length > 0 ? (
                            [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).map((entry, index, array) => {
                                const previousEntry = array[index + 1]; // The one before chronologically
                                const opRatingChange = getRatingChange(entry.ratingOperation, previousEntry?.ratingOperation);
                                const groupRatingChange = getRatingChange(entry.ratingGroup, previousEntry?.ratingGroup);

                                return (
                                    <div key={entry.id} className="p-3 bg-gray-50 rounded-md grid grid-cols-4 gap-4 items-center">
                                        <div className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</div>
                                        <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                            <span className="text-xs text-gray-500">Op: </span>
                                            <RatingChangeIndicator change={opRatingChange} />
                                            {entry.ratingOperation}
                                        </div>
                                        <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                            <span className="text-xs text-gray-500">Grupo: </span>
                                            <RatingChangeIndicator change={groupRatingChange} />
                                            {entry.ratingGroup}
                                        </div>
                                        <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                            {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                            {entry.sentiment}
                                        </div>
                                    </div>
                                );
                            })
                        ) : (
                            <p className="text-center text-gray-500 py-4">Nenhum histórico de rating para esta operação.</p>
                        )}
                    </div>
                    <div>
                        <RatingHistoryChart history={operation.ratingHistory} />
                    </div>
                </div>
            </div>
             <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Tarefas Concluídas</h3>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {completedTasks.map(task => {
                        const completionEvent = operation.events.find(e => e.completedTaskId === task.id);
                        return (
                            <div key={task.id} className="p-3 bg-green-50 rounded-md flex justify-between items-center border-l-4 border-green-500">
                                <div>
                                    <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                    <p className="text-sm text-gray-600">
                                        Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                {completionEvent && (
                                    <button onClick={() => handleViewEventClick(task.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm">
                                        <EyeIcon className="w-4 h-4" /> Ver Evento
                                    </button>
                                )}
                            </div>
                        )
                    })}
                    {completedTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa foi concluída ainda.</p>}
                </div>
            </div>
        </div>
    );
};

export default OperationDetail;

import React, { useState, useMemo } from 'react';
import type { Operation, Task, Event, Rating, Sentiment, RatingHistoryEntry, Area, TaskRule } from '../types';
import { TaskStatus } from '../types';
import EventForm from './EventForm';
import ReviewCompletionForm from './ReviewCompletionForm';
import { CheckCircleIcon, PlusCircleIcon, PencilIcon, TrashIcon } from './icons/Icons';
import Modal from './Modal';
import AdHocTaskForm from './AdHocTaskForm';

interface TasksPageProps {
  operations: Operation[];
  allTasks: Task[];
  onUpdateOperation: (updatedOperation: Operation) => void;
  onOpenNewTaskModal: (operationId?: number) => void;
  onDeleteTask: (task: Task) => void;
  onEditTask: (task: Task, updates: { name: string, dueDate: string }) => void;
}

const TasksPage: React.FC<TasksPageProps> = ({ operations, allTasks, onUpdateOperation, onOpenNewTaskModal, onDeleteTask, onEditTask }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedAnalyst, setSelectedAnalyst] = useState('Todos');
  const [selectedRuleName, setSelectedRuleName] = useState('Todos');
  const [selectedOperationId, setSelectedOperationId] = useState('Todos');
  const [areaFilter, setAreaFilter] = useState<'All' | Area>('All');
  const [activeTab, setActiveTab] = useState('pending'); // 'pending' or 'completed'

  const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
  const [isEventFormOpen, setIsEventFormOpen] = useState(false);

  const [reviewTaskToComplete, setReviewTaskToComplete] = useState<Task | null>(null);
  const [isReviewFormOpen, setIsReviewFormOpen] = useState(false);

  const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);
  const [taskToDelete, setTaskToDelete] = useState<Task | null>(null);

  const analysts = useMemo(() => ['Todos', ...new Set(operations.map(op => op.responsibleAnalyst))], [operations]);
  const ruleNames = useMemo(() => ['Todos', ...new Set(allTasks.map(task => task.ruleName))], [allTasks]);
  const operationsById = useMemo(() => new Map(operations.map(op => [op.id, op])), [operations]);

  const filteredTasks = useMemo(() => {
    return allTasks.filter(task => {
      const op = operationsById.get(task.operationId);
      if (!op) return false;
      if (areaFilter !== 'All' && op.area !== areaFilter) return false;
      if (selectedOperationId !== 'Todos' && task.operationId !== parseInt(selectedOperationId, 10)) return false;
      if (selectedAnalyst !== 'Todos' && op.responsibleAnalyst !== selectedAnalyst) return false;
      if (selectedRuleName !== 'Todos' && task.ruleName !== selectedRuleName) return false;
      return true;
    });
  }, [allTasks, operationsById, areaFilter, selectedOperationId, selectedAnalyst, selectedRuleName]);


  const pendingTasksInMonth = useMemo(() => {
    return filteredTasks
      .filter(task => task.status !== TaskStatus.COMPLETED)
      .filter(task => {
        const dueDate = new Date(task.dueDate);
        return dueDate.getFullYear() === currentMonth.getFullYear() && dueDate.getMonth() === currentMonth.getMonth();
      })
      .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
  }, [filteredTasks, currentMonth]);

  const completedTasksInMonth = useMemo(() => {
     return filteredTasks
      .filter(task => task.status === TaskStatus.COMPLETED)
      .filter(task => {
        const op = operationsById.get(task.operationId);
        const completionEvent = op?.events.find(e => e.completedTaskId === task.id);
        if (!completionEvent) return false;
        const completionDate = new Date(completionEvent.date);
        return completionDate.getFullYear() === currentMonth.getFullYear() && completionDate.getMonth() === currentMonth.getMonth();
      })
      .sort((a, b) => {
          const eventA = operationsById.get(a.operationId)?.events.find(e => e.completedTaskId === a.id);
          const eventB = operationsById.get(b.operationId)?.events.find(e => e.completedTaskId === b.id);
          return (eventB ? new Date(eventB.date).getTime() : 0) - (eventA ? new Date(eventA.date).getTime() : 0);
      });
  }, [filteredTasks, currentMonth, operationsById]);

  const changeMonth = (offset: number) => {
    setCurrentMonth(prev => {
      const newDate = new Date(prev);
      newDate.setMonth(prev.getMonth() + offset);
      return newDate;
    });
  };

  const handleCompleteTaskClick = (task: Task) => {
    if (task.ruleName === 'Revisão Gerencial' || task.ruleName === 'Revisão Política') {
        setReviewTaskToComplete(task);
        setIsReviewFormOpen(true);
    } else {
        setTaskToComplete(task);
        setIsEventFormOpen(true);
    }
  };

  const handleAddEvent = (newEvent: Omit<Event, 'id'>) => {
      if (!taskToComplete) return;

      const operationToUpdate = operationsById.get(taskToComplete.operationId);
      if (operationToUpdate) {
        const eventToSave: Partial<Event> = {
            ...newEvent,
            completedTaskId: taskToComplete.id,
        };
        const updatedTasks = operationToUpdate.tasks.map(t => t.id === taskToComplete.id ? {...t, status: TaskStatus.COMPLETED} : t);

        const updatedOperation = {
            ...operationToUpdate,
            events: [...operationToUpdate.events, { ...eventToSave, id: Date.now() } as Event],
            tasks: updatedTasks,
        };
        onUpdateOperation(updatedOperation);
      }

      setTaskToComplete(null);
      setIsEventFormOpen(false);
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
    if (!reviewTaskToComplete) return;
    const operationToUpdate = operationsById.get(reviewTaskToComplete.operationId);
    if (!operationToUpdate) return;

    const newEventId = Date.now();
    const eventToSave: Event = {
        ...data.event,
        id: newEventId,
        completedTaskId: reviewTaskToComplete?.id
    };

    const newHistoryEntry: RatingHistoryEntry = {
        id: Date.now() + 1,
        date: eventToSave.date,
        ratingOperation: data.ratingOp,
        ratingGroup: data.ratingGroup,
        watchlist: operationToUpdate.watchlist,
        sentiment: data.sentiment,
        eventId: newEventId,
    };

    const updatedTasks = operationToUpdate.tasks.map(t => t.id === reviewTaskToComplete.id ? {...t, status: TaskStatus.COMPLETED} : t);

    const updatedOperation: Operation = {
        ...operationToUpdate,
        ratingOperation: data.ratingOp,
        ratingGroup: data.ratingGroup,
        events: [...operationToUpdate.events, eventToSave],
        ratingHistory: [...operationToUpdate.ratingHistory, newHistoryEntry],
        tasks: updatedTasks
    };

    onUpdateOperation(updatedOperation);
    setReviewTaskToComplete(null);
    setIsReviewFormOpen(false);
  };

  const handleConfirmDeleteTask = () => {
    if (taskToDelete) {
        onDeleteTask(taskToDelete);
        setTaskToDelete(null);
    }
  };

  const handleSaveEditedTask = (rule: Omit<TaskRule, 'id'>) => {
      if (taskToEdit) {
          onEditTask(taskToEdit, { name: rule.name, dueDate: rule.startDate });
          setTaskToEdit(null);
      }
  };

  return (
    <div className="space-y-6">
       {isEventFormOpen && taskToComplete && (
            <EventForm 
                onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); }} 
                onSave={handleAddEvent}
                analystName={operationsById.get(taskToComplete.operationId)?.responsibleAnalyst || ''}
                prefilledTitle={`Conclusão: ${taskToComplete.ruleName}`}
            />
        )}
        {isReviewFormOpen && reviewTaskToComplete && (
            <ReviewCompletionForm
                task={reviewTaskToComplete}
                operation={operationsById.get(reviewTaskToComplete.operationId)!}
                onClose={() => { setIsReviewFormOpen(false); setReviewTaskToComplete(null); }}
                onSave={handleSaveReview}
            />
        )}
        {taskToEdit && (
            <Modal isOpen={true} onClose={() => setTaskToEdit(null)} title="Editar Tarefa">
                <AdHocTaskForm
                    onClose={() => setTaskToEdit(null)}
                    onSave={handleSaveEditedTask}
                    initialTask={taskToEdit}
                />
            </Modal>
        )}
        {taskToDelete && (
            <Modal
                isOpen={true}
                onClose={() => setTaskToDelete(null)}
                title={`Deletar Tarefa: ${taskToDelete.ruleName}`}
            >
                <div className="text-center">
                    <p className="text-lg text-gray-700 mb-6">
                    Você tem certeza que deseja deletar esta tarefa? Esta ação não pode ser desfeita.
                    </p>
                    <div className="flex justify-center gap-4">
                        <button onClick={() => setTaskToDelete(null)} className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">Cancelar</button>
                        <button onClick={handleConfirmDeleteTask} className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700">Confirmar Deleção</button>
                    </div>
                </div>
            </Modal>
        )}

      <div className="bg-white p-6 rounded-lg shadow-lg">
        <div className="flex justify-between items-center mb-4">
            <h2 className="text-2xl font-bold text-gray-800">Gerenciador de Tarefas</h2>
             <button
                onClick={() => onOpenNewTaskModal()}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
            >
                <PlusCircleIcon className="w-5 h-5" /> Adicionar Tarefa
            </button>
        </div>

        {/* Filters */}
        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4">
          <div className="grid grid-cols-1 md:grid-cols-5 gap-4 items-end">
             <div>
              <label htmlFor="area-filter" className="block text-sm font-medium text-gray-700">Área de Negócio</label>
              <select id="area-filter" value={areaFilter} onChange={e => setAreaFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                <option value="All">Todas</option>
                <option value="CRI">CRI</option>
                <option value="Capital Solutions">Capital Solutions</option>
              </select>
            </div>
            <div>
              <label htmlFor="analyst-filter" className="block text-sm font-medium text-gray-700">Analista</label>
              <select id="analyst-filter" value={selectedAnalyst} onChange={e => setSelectedAnalyst(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                {analysts.map(name => <option key={name} value={name}>{name}</option>)}
              </select>
            </div>
            <div>
                <label htmlFor="operation-filter" className="block text-sm font-medium text-gray-700">Operação</label>
                <select id="operation-filter" value={selectedOperationId} onChange={e => setSelectedOperationId(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                    <option value="Todos">Todas</option>
                    {operations.map(op => <option key={op.id} value={op.id}>{op.name}</option>)}
                </select>
            </div>
             <div>
                <label htmlFor="task-type-filter" className="block text-sm font-medium text-gray-700">Tipo de Tarefa</label>
                <select id="task-type-filter" value={selectedRuleName} onChange={e => setSelectedRuleName(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-blue-500 focus:ring-blue-500 sm:text-sm">
                    {ruleNames.map(name => <option key={name} value={name}>{name}</option>)}
                </select>
            </div>
            <div>
                <label className="block text-sm font-medium text-gray-700 text-center">Mês</label>
                <div className="flex justify-between items-center mt-1">
                    <button onClick={() => changeMonth(-1)} className="px-3 py-2 bg-gray-200 rounded-md hover:bg-gray-300">&larr;</button>
                    <h3 className="font-semibold text-gray-700">
                        {currentMonth.toLocaleString('pt-BR', { month: 'long', year: 'numeric' })}
                    </h3>
                    <button onClick={() => changeMonth(1)} className="px-3 py-2 bg-gray-200 rounded-md hover:bg-gray-300">&rarr;</button>
                </div>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="border-b border-gray-200 mb-4">
            <nav className="-mb-px flex space-x-6" aria-label="Tabs">
                <button
                    onClick={() => setActiveTab('pending')}
                    className={`${
                        activeTab === 'pending'
                            ? 'border-blue-500 text-blue-600'
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    } whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}
                >
                    Tarefas Pendentes ({pendingTasksInMonth.length})
                </button>
                <button
                    onClick={() => setActiveTab('completed')}
                    className={`${
                        activeTab === 'completed'
                            ? 'border-blue-500 text-blue-600'
                            : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    } whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}
                >
                    Tarefas Concluídas ({completedTasksInMonth.length})
                </button>
            </nav>
        </div>

        {/* Task List */}
        <div className="space-y-3">
          {activeTab === 'pending' && (
            <>
              {pendingTasksInMonth.map(task => {
                  const operationName = operationsById.get(task.operationId)?.name || 'N/A';
                  return (
                     <div key={task.id} className={`p-4 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                        <div className="flex-1">
                            <p className="font-semibold text-gray-800">{task.ruleName}</p>
                            <p className="text-sm text-gray-600">
                                <span className="font-medium">Operação:</span> {operationName}
                            </p>
                            <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-800'}`}>
                                Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                            </p>
                        </div>
                        <div className="flex items-center gap-2">
                             <button onClick={() => setTaskToEdit(task)} className="text-gray-400 hover:text-blue-600 p-1 rounded-full" title="Editar Tarefa">
                                <PencilIcon className="w-5 h-5" />
                            </button>
                            <button onClick={() => setTaskToDelete(task)} className="text-gray-400 hover:text-red-600 p-1 rounded-full" title="Deletar Tarefa">
                                <TrashIcon className="w-5 h-5" />
                            </button>
                            <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                <CheckCircleIcon className="w-4 h-4" /> Completar
                            </button>
                        </div>
                    </div>
                  );
              })}
              {pendingTasksInMonth.length === 0 && (
                <div className="text-center py-8 text-gray-500">
                  <p>Nenhuma tarefa pendente encontrada para os filtros selecionados.</p>
                </div>
              )}
            </>
          )}

          {activeTab === 'completed' && (
            <>
                {completedTasksInMonth.map(task => {
                    const op = operationsById.get(task.operationId);
                    const operationName = op?.name || 'N/A';
                    const completionEvent = op?.events.find(e => e.completedTaskId === task.id);
                    return (
                        <div key={task.id} className="p-4 rounded-md flex justify-between items-center bg-green-50 border-l-4 border-green-500">
                            <div className="flex-1">
                                <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                <p className="text-sm text-gray-600">
                                    <span className="font-medium">Operação:</span> {operationName}
                                </p>
                                <p className="text-sm text-green-700">
                                    Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : 'N/A'}
                                </p>
                            </div>
                        </div>
                    );
                })}
                {completedTasksInMonth.length === 0 && (
                    <div className="text-center py-8 text-gray-500">
                      <p>Nenhuma tarefa concluída encontrada para os filtros selecionados.</p>
                    </div>
                )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default TasksPage;

import React, { useState, useMemo } from 'react';
import type { Operation, RatingHistoryEntry, Event, Rating, Sentiment as SentimentType } from '../types';
import { WatchlistStatus, Sentiment, ratingOptions } from '../types';
import { BellIcon, ArrowUpIcon, ArrowRightIcon, ArrowDownIcon } from './icons/Icons';
import WatchlistChangeForm from './WatchlistChangeForm';
import WatchlistHistoryChart from './WatchlistHistoryChart';


interface WatchlistPageProps {
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
}

const WatchlistPage: React.FC<WatchlistPageProps> = ({ operations, onUpdateOperation }) => {
    const [activeFilter, setActiveFilter] = useState<WatchlistStatus | 'All'>('All');
    const [expandedOpId, setExpandedOpId] = useState<number | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [operationToEdit, setOperationToEdit] = useState<Operation | null>(null);

    const filterOptions: (WatchlistStatus | 'All')[] = ['All', ...Object.values(WatchlistStatus)];

    const filteredOperations = useMemo(() => {
        if (activeFilter === 'All') return operations;
        return operations.filter(op => op.watchlist === activeFilter);
    }, [operations, activeFilter]);

    const handleOpenModal = (op: Operation) => {
        setOperationToEdit(op);
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setOperationToEdit(null);
        setIsModalOpen(false);
    };

    const handleSaveChanges = (data: Parameters<typeof onUpdateOperation>[0]) => {
        onUpdateOperation(data);
        handleCloseModal();
    };

    const handleSaveWatchlistChange = (op: Operation, data: { watchlist: WatchlistStatus, ratingOp: Rating, ratingGroup: Rating, event: Omit<Event, 'id'>}) => {
        const newEventId = Date.now();
        const eventToSave: Event = { ...data.event, id: newEventId };

        const oldWatchlistIndex = Object.values(WatchlistStatus).indexOf(op.watchlist);
        const newWatchlistIndex = Object.values(WatchlistStatus).indexOf(data.watchlist);
        const oldRatingOpIndex = ratingOptions.indexOf(op.ratingOperation);
        const newRatingOpIndex = ratingOptions.indexOf(data.ratingOp);
        const oldRatingGroupIndex = ratingOptions.indexOf(op.ratingGroup);
        const newRatingGroupIndex = ratingOptions.indexOf(data.ratingGroup);

        let sentiment: SentimentType = Sentiment.NEUTRO;

        if (newWatchlistIndex > oldWatchlistIndex) sentiment = Sentiment.NEGATIVO;
        else if (newWatchlistIndex < oldWatchlistIndex) sentiment = Sentiment.POSITIVO;
        else if (newRatingOpIndex > oldRatingOpIndex) sentiment = Sentiment.NEGATIVO;
        else if (newRatingOpIndex < oldRatingOpIndex) sentiment = Sentiment.POSITIVO;
        else if (newRatingGroupIndex > oldRatingGroupIndex) sentiment = Sentiment.NEGATIVO;
        else if (newRatingGroupIndex < oldRatingGroupIndex) sentiment = Sentiment.POSITIVO;

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            watchlist: data.watchlist, // Save the new watchlist status to history
            sentiment: sentiment,
            eventId: newEventId,
        };

        const updatedOp = {
            ...op,
            watchlist: data.watchlist,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...op.events, eventToSave],
            ratingHistory: [...op.ratingHistory, newHistoryEntry],
        };
        handleSaveChanges(updatedOp);
    };

    return (
        <div className="space-y-8">
            {isModalOpen && operationToEdit && (
                <WatchlistChangeForm
                    operation={operationToEdit}
                    onClose={handleCloseModal}
                    onSave={(data) => handleSaveWatchlistChange(operationToEdit, data)}
                />
            )}

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">Gerenciamento de Watchlist</h2>

                <div className="flex items-center gap-2 border-b border-gray-200 pb-4 mb-4">
                    {filterOptions.map(status => (
                        <button
                            key={status}
                            onClick={() => setActiveFilter(status)}
                            className={`px-4 py-2 text-sm font-semibold rounded-full transition-colors duration-200 ${
                                activeFilter === status
                                ? 'bg-blue-600 text-white shadow'
                                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                            }`}
                        >
                            {status === 'All' ? 'Todas' : status}
                        </button>
                    ))}
                </div>

                <div className="space-y-4">
                    {filteredOperations.map(op => (
                        <OperationCard 
                            key={op.id}
                            operation={op}
                            isExpanded={expandedOpId === op.id}
                            onToggle={() => setExpandedOpId(prev => prev === op.id ? null : op.id)}
                            onOpenUpdateModal={() => handleOpenModal(op)}
                        />
                    ))}
                    {filteredOperations.length === 0 && (
                        <div className="text-center py-12 text-gray-500">
                            <p>Nenhuma operação encontrada para o filtro "{activeFilter}".</p>
                        </div>
                    )}
                </div>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h2 className="text-2xl font-bold text-gray-800 mb-4">Histórico Mensal de Watchlist</h2>
                 <WatchlistHistoryChart operations={operations} />
            </div>
        </div>
    );
};

const WatchlistBadge: React.FC<{ status: WatchlistStatus | null }> = ({ status }) => {
    if (!status) return null;
    const colorClasses = {
        [WatchlistStatus.VERDE]: 'bg-green-100 text-green-800',
        [WatchlistStatus.AMARELO]: 'bg-yellow-100 text-yellow-800',
        [WatchlistStatus.ROSA]: 'bg-pink-100 text-pink-800',
        [WatchlistStatus.VERMELHO]: 'bg-red-100 text-red-800',
    };

    return (
        <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${colorClasses[status]}`}>
        {status}
        </span>
    );
};


interface OperationCardProps {
    operation: Operation;
    isExpanded: boolean;
    onToggle: () => void;
    onOpenUpdateModal: () => void;
}

const OperationCard: React.FC<OperationCardProps> = ({ operation, isExpanded, onToggle, onOpenUpdateModal }) => {
    const statusClasses = {
        [WatchlistStatus.VERDE]: { border: 'border-green-500', bg: 'bg-green-50' },
        [WatchlistStatus.AMARELO]: { border: 'border-yellow-500', bg: 'bg-yellow-50' },
        [WatchlistStatus.ROSA]: { border: 'border-pink-500', bg: 'bg-pink-50' },
        [WatchlistStatus.VERMELHO]: { border: 'border-red-500', bg: 'bg-red-50' },
    };

    const sortedHistory = useMemo(() => {
        return [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.ratingHistory]);

    const previousWatchlistStatus = useMemo(() => {
        const now = new Date();
        const startOfThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
        const relevantHistory = operation.ratingHistory
            .filter(h => new Date(h.date) < startOfThisMonth)
            .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        // If there's history from before this month, use the latest one. Otherwise, it's null.
        return relevantHistory.length > 0 ? relevantHistory[0].watchlist : null;
    }, [operation.ratingHistory]);

    return (
        <div className={`border-l-4 rounded-r-lg shadow-sm transition-all duration-300 ${statusClasses[operation.watchlist].border} ${isExpanded ? statusClasses[operation.watchlist].bg : 'bg-white'}`}>
            <div 
                className="p-4 cursor-pointer"
                onClick={onToggle}
            >
                <div className="flex justify-between items-center">
                    <div className="flex-1">
                        <p className="font-bold text-lg text-gray-900">{operation.name}</p>
                        <div className="flex items-center gap-4 text-sm text-gray-700 mt-1">
                            <span>Analista: <span className="font-medium">{operation.responsibleAnalyst}</span></span>
                            <span>Rating Op: <span className="font-medium">{operation.ratingOperation}</span></span>
                            <span>Rating Grupo: <span className="font-medium">{operation.ratingGroup}</span></span>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="text-right">
                           <p className="text-xs text-gray-500">Farol Atual</p>
                           <WatchlistBadge status={operation.watchlist} />
                        </div>
                        {previousWatchlistStatus && (
                            <div className="text-right">
                               <p className="text-xs text-gray-500">Mês Anterior</p>
                               <WatchlistBadge status={previousWatchlistStatus} />
                            </div>
                        )}
                        <button onClick={(e) => { e.stopPropagation(); onOpenUpdateModal(); }} className="flex items-center gap-2 px-3 py-2 bg-blue-100 text-blue-800 rounded-lg hover:bg-blue-200 text-sm font-semibold">
                            <BellIcon className="w-4 h-4" /> Alterar Status
                        </button>
                        <span className={`transform transition-transform duration-200 ${isExpanded ? 'rotate-180' : 'rotate-0'}`}>
                            <svg className="w-6 h-6 text-gray-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </span>
                    </div>
                </div>
            </div>

            {isExpanded && (
                <div className="p-4 border-t border-gray-200 bg-white/50 space-y-4">
                    <h4 className="font-semibold text-gray-700">Histórico de Alterações</h4>
                    {sortedHistory.length > 0 ? (
                        sortedHistory.map(entry => {
                            const event = operation.events.find(e => e.id === entry.eventId);
                            return (
                                <div key={entry.id} className="p-3 border rounded-md bg-white">
                                    <div className="grid grid-cols-5 gap-4 items-center mb-3">
                                        <p className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</p>
                                        <div className="text-sm">Farol: <WatchlistBadge status={entry.watchlist} /></div>
                                        <p className="text-sm">Op: {entry.ratingOperation}</p>
                                        <p className="text-sm">Grupo: {entry.ratingGroup}</p>
                                        <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                            {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                            {entry.sentiment}
                                        </div>
                                    </div>
                                    {event && (
                                        <div className="border-t border-gray-200 pt-3 text-sm space-y-2">
                                            <p><strong className="font-semibold text-gray-600">Evento:</strong> {event.title}</p>
                                            <p className="text-gray-700">{event.description}</p>
                                            {event.nextSteps && <p><strong className="font-semibold text-gray-600">Próximos Passos:</strong> {event.nextSteps}</p>}
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    ) : (
                        <p className="text-center text-gray-500 py-4">Nenhum histórico de alteração para esta operação.</p>
                    )}
                </div>
            )}
        </div>
    );
};

export default WatchlistPage;

import React, { useMemo } from 'react';
import type { Operation } from '../types';
import { WatchlistStatus } from '../types';

interface WatchlistHistoryChartProps {
    operations: Operation[];
}

// Helper to get the last day of a given month
const getEndOfMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth() + 1, 0);

// Helper to get the watchlist status of an operation at a specific point in time
const getStatusForMonth = (operation: Operation, monthEndDate: Date): WatchlistStatus => {
    const relevantHistory = operation.ratingHistory
        .filter(h => new Date(h.date) <= monthEndDate)
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // If there is history for that month or before, take the most recent one.
    if (relevantHistory.length > 0) {
        return relevantHistory[0].watchlist;
    }

    // Otherwise, it implies the operation was created with its current status and had no changes yet.
    // We should be careful here. A better approach would be to check creation date.
    // For now, let's assume if no history, it's the current status.
    return operation.watchlist;
};

const WatchlistHistoryChart: React.FC<WatchlistHistoryChartProps> = ({ operations }) => {
    const months = useMemo(() => {
        const monthLabels: { name: string; endDate: Date }[] = [];
        const today = new Date();
        for (let i = 3; i >= 0; i--) {
            const date = new Date(today.getFullYear(), today.getMonth() - i, 1);
            monthLabels.push({
                name: date.toLocaleString('pt-BR', { month: 'short', year: '2-digit' }),
                endDate: getEndOfMonth(date),
            });
        }
        return monthLabels;
    }, []);

    const chartData = useMemo(() => {
        return operations.map(op => ({
            operationName: op.name,
            statuses: months.map(month => getStatusForMonth(op, month.endDate)),
        }));
    }, [operations, months]);

    const statusColorClasses: Record<WatchlistStatus, string> = {
        [WatchlistStatus.VERDE]: 'bg-green-500',
        [WatchlistStatus.AMARELO]: 'bg-yellow-400',
        [WatchlistStatus.ROSA]: 'bg-pink-500',
        [WatchlistStatus.VERMELHO]: 'bg-red-600',
    };

    if (operations.length === 0) {
        return <p className="text-center text-gray-500 py-4">Nenhuma operação para exibir no gráfico.</p>;
    }

    return (
        <div className="overflow-x-auto p-2">
            <div className="inline-block min-w-full">
                <div className="grid gap-x-4" style={{ gridTemplateColumns: `minmax(200px, 1.5fr) repeat(${months.length}, minmax(80px, 1fr))` }}>
                    {/* Header */}
                    <div className="font-semibold text-gray-600 pb-2">Operação</div>
                    {months.map(month => (
                        <div key={month.name} className="font-semibold text-gray-600 text-center pb-2 capitalize">{month.name}</div>
                    ))}

                    {/* Body */}
                    {chartData.map(({ operationName, statuses }) => (
                        <React.Fragment key={operationName}>
                            <div className="py-3 border-t border-gray-200 text-sm font-medium text-gray-800 truncate" title={operationName}>{operationName}</div>
                            {statuses.map((status, index) => (
                                <div key={index} className="py-3 border-t border-gray-200 flex items-center justify-center">
                                    <div className={`w-6 h-6 rounded-full border-2 border-black/20 ${statusColorClasses[status]}`} title={status}></div>
                                </div>
                            ))}
                        </React.Fragment>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default WatchlistHistoryChart;

