const WatchlistPage: React.FC<WatchlistPageProps> = ({ operations, onUpdateOperation }) => {
    const [activeFilter, setActiveFilter] = useState<WatchlistStatus | 'All'>('All');
    const [expandedOpId, setExpandedOpId] = useState<number | null>(null);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [operationToEdit, setOperationToEdit] = useState<Operation | null>(null);

    const filterOptions: (WatchlistStatus | 'All')[] = ['All', ...Object.values(WatchlistStatus)];

    const filteredOperations = useMemo(() => {
        if (activeFilter === 'All') return operations;
        return operations.filter(op => op.watchlist === activeFilter);
    }, [operations, activeFilter]);

    const handleOpenModal = (op: Operation) => {
        setOperationToEdit(op);
        setIsModalOpen(true);
    };

    const handleCloseModal = () => {
        setOperationToEdit(null);
        setIsModalOpen(false);
    };

    const handleSaveChanges = (data: Parameters<typeof onUpdateOperation>[0]) => {
        onUpdateOperation(data);
        handleCloseModal();
    };

    const handleSaveWatchlistChange = (op: Operation, data: { watchlist: WatchlistStatus, ratingOp: Rating, ratingGroup: Rating, event: Omit<Event, 'id'>}) => {
        const newEventId = Date.now();
        const eventToSave: Event = { ...data.event, id: newEventId };

        const oldWatchlistIndex = Object.values(WatchlistStatus).indexOf(op.watchlist);
        const newWatchlistIndex = Object.values(WatchlistStatus).indexOf(data.watchlist);
        const oldRatingOpIndex = ratingOptions.indexOf(op.ratingOperation);
        const newRatingOpIndex = ratingOptions.indexOf(data.ratingOp);
        const oldRatingGroupIndex = ratingOptions.indexOf(op.ratingGroup);
        const newRatingGroupIndex = ratingOptions.indexOf(data.ratingGroup);

        let sentiment: SentimentType = Sentiment.NEUTRO;

        if (newWatchlistIndex > oldWatchlistIndex) sentiment = Sentiment.NEGATIVO;
        else if (newWatchlistIndex < oldWatchlistIndex) sentiment = Sentiment.POSITIVO;
        else if (newRatingOpIndex > oldRatingOpIndex) sentiment = Sentiment.NEGATIVO;
        else if (newRatingOpIndex < oldRatingOpIndex) sentiment = Sentiment.POSITIVO;
        else if (newRatingGroupIndex > oldRatingGroupIndex) sentiment = Sentiment.NEGATIVO;
        else if (newRatingGroupIndex < oldRatingGroupIndex) sentiment = Sentiment.POSITIVO;

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            watchlist: data.watchlist, // Save the new watchlist status to history
            sentiment: sentiment,
            eventId: newEventId,
        };

        const updatedOp = {
            ...op,
            watchlist: data.watchlist,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...op.events, eventToSave],
            ratingHistory: [...op.ratingHistory, newHistoryEntry],
        };
        handleSaveChanges(updatedOp);
    };

    return (
        <div className="space-y-8">
            {isModalOpen && operationToEdit && (
                <WatchlistChangeForm
                    operation={operationToEdit}
                    onClose={handleCloseModal}
                    onSave={(data) => handleSaveWatchlistChange(operationToEdit, data)}
                />
            )}

