import React, { useMemo } from 'react';
import type { Operation, Area } from '../types';
import { Page } from '../types';
import { HomeIcon, BriefcaseIcon, ClipboardCheckIcon, HistoryIcon, BellIcon, DocumentSearchIcon } from './icons/Icons';

interface SidebarProps {
  operations: Operation[];
  currentPage: Page;
  selectedOperationId: number | null;
  onNavigate: (page: Page, operationId?: number) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ operations, currentPage, selectedOperationId, onNavigate }) => {

  const groupedOperations = useMemo(() => {
    return operations.reduce((acc, op) => {
      const area = op.area || 'CRI'; // Default to CRI if area is not set
      if (!acc[area]) {
        acc[area] = [];
      }
      acc[area].push(op);
      return acc;
    }, {} as Record<Area, Operation[]>);
  }, [operations]);


  const NavLink: React.FC<{
    onClick: () => void;
    isActive: boolean;
    children: React.ReactNode;
    isSubItem?: boolean;
  }> = ({ onClick, isActive, children, isSubItem = false }) => (
    <button
      onClick={onClick}
      className={`w-full text-left flex items-center gap-3 rounded-md transition-colors duration-200 ${
        isSubItem ? 'pl-10 pr-2 py-2 text-sm' : 'px-4 py-2.5'
      } ${
        isActive
          ? 'bg-gray-700 text-white'
          : 'text-gray-300 hover:bg-gray-700 hover:text-white'
      }`}
    >
      {children}
    </button>
  );

  return (
    <div className="w-64 bg-gray-800 text-white flex flex-col h-screen">
      <div className="p-4 border-b border-gray-700">
        <h2 className="text-xl font-bold">Navegação</h2>
      </div>
      <nav className="flex-1 p-2 space-y-1 overflow-y-auto">
        <NavLink
          onClick={() => onNavigate(Page.OVERVIEW)}
          isActive={currentPage === Page.OVERVIEW}
        >
          <HomeIcon className="w-5 h-5" />
          <span>Resumo Geral</span>
        </NavLink>

        <NavLink
          onClick={() => onNavigate(Page.TASKS)}
          isActive={currentPage === Page.TASKS}
        >
          <ClipboardCheckIcon className="w-5 h-5" />
          <span>Gerenciador de Tarefas</span>
        </NavLink>

         <NavLink
          onClick={() => onNavigate(Page.CREDIT_REVIEWS)}
          isActive={currentPage === Page.CREDIT_REVIEWS}
        >
          <DocumentSearchIcon className="w-5 h-5" />
          <span>Revisões de Crédito</span>
        </NavLink>

         <NavLink
          onClick={() => onNavigate(Page.WATCHLIST)}
          isActive={currentPage === Page.WATCHLIST}
        >
          <BellIcon className="w-5 h-5" />
          <span>Watchlist</span>
        </NavLink>

        <NavLink
          onClick={() => onNavigate(Page.AUDIT_LOG)}
          isActive={currentPage === Page.AUDIT_LOG}
        >
          <HistoryIcon className="w-5 h-5" />
          <span>Log de Auditoria</span>
        </NavLink>

        <div className="pt-2">
            {Object.keys(groupedOperations).sort().map(area => (
              <div key={area} className="mt-2">
                 <h3 className="px-4 text-xs font-semibold text-gray-400 uppercase tracking-wider">{area}</h3>
                 <div className="mt-1 space-y-1">
                    {groupedOperations[area as Area].map(op => (
                        <NavLink
                            key={op.id}
                            onClick={() => onNavigate(Page.DETAIL, op.id)}
                            isActive={currentPage === Page.DETAIL && selectedOperationId === op.id}
                            isSubItem
                        >
                            <BriefcaseIcon className="w-4 h-4" />
                            <span className="truncate">{op.name}</span>
                        </NavLink>
                    ))}
                </div>
              </div>
            ))}
        </div>
      </nav>
    </div>
  );
};

export default Sidebar;

import React, { useState, useMemo, useEffect } from 'react';
import type { Operation, Task, Area, ReviewNote } from '../types';
import { TaskStatus } from '../types';
import { PencilIcon, CheckCircleIcon } from './icons/Icons';

interface CreditReviewsPageProps {
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
  onCompleteReview: (task: Task) => void;
  apiUrl: string;
  showToast: (message: string, type: 'success' | 'error') => void;
}

const CreditReviewsPage: React.FC<CreditReviewsPageProps> = ({ operations, onUpdateOperation, onCompleteReview, apiUrl, showToast }) => {
  const [reviewNotes, setReviewNotes] = useState<ReviewNote[]>([]);
  const [isLoadingNotes, setIsLoadingNotes] = useState(true);

  // Filters
  const [analystFilter, setAnalystFilter] = useState('All');
  const [areaFilter, setAreaFilter] = useState<'All' | Area>('All');
  const [dateFilter, setDateFilter] = useState({ start: '', end: '' });

  // In-line editing state
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editingNotes, setEditingNotes] = useState('');

  const analysts = useMemo(() => ['All', ...new Set(operations.map(op => op.responsibleAnalyst))], [operations]);

  useEffect(() => {
    const fetchNotes = async () => {
        setIsLoadingNotes(true);
        try {
            const response = await fetch(`${apiUrl}/api/review_notes`, { credentials: 'include' });
            if (!response.ok) throw new Error('Falha ao buscar as notas das revisões.');
            const data: ReviewNote[] = await response.json();
            setReviewNotes(data);
        } catch (error) {
            console.error(error);
            showToast('Erro ao carregar observações.', 'error');
        } finally {
            setIsLoadingNotes(false);
        }
    };
    fetchNotes();
  }, [apiUrl, showToast]);

  const allPendingReviews = useMemo(() => {
    const notesMap = new Map(reviewNotes.map(note => [note.task_id, note.notes]));

    return operations.flatMap(op => 
        op.tasks
            .filter(task => 
                (task.ruleName === 'Revisão Gerencial' || task.ruleName === 'Revisão Política') &&
                task.status !== TaskStatus.COMPLETED
            )
            .map(task => ({
                ...task,
                operationName: op.name,
                analyst: op.responsibleAnalyst,
                area: op.area,
                notes: notesMap.get(task.id) || '',
            }))
    );
  }, [operations, reviewNotes]);

  const filteredReviews = useMemo(() => {
    return allPendingReviews
        .filter(review => {
            if (analystFilter !== 'All' && review.analyst !== analystFilter) return false;
            if (areaFilter !== 'All' && review.area !== areaFilter) return false;
            if (dateFilter.start || dateFilter.end) {
                const reviewDate = new Date(review.dueDate);
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;
                 if(startDate) startDate.setHours(0,0,0,0);
                 if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && reviewDate < startDate) return false;
                if (endDate && reviewDate > endDate) return false;
            }
            return true;
        })
        .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
  }, [allPendingReviews, analystFilter, areaFilter, dateFilter]);

  const handleStartEditing = (task: (typeof allPendingReviews)[0]) => {
      setEditingTaskId(task.id);
      setEditingNotes(task.notes || '');
  };

  const handleCancelEditing = () => {
      setEditingTaskId(null);
      setEditingNotes('');
  };

  const handleSaveNote = async () => {
      if (!editingTaskId) return;

      const review = allPendingReviews.find(r => r.id === editingTaskId);
      if (!review) return;

      try {
        const response = await fetch(`${apiUrl}/api/review_notes`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                taskId: editingTaskId,
                operationId: review.operationId,
                notes: editingNotes,
                userName: review.analyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a observação.');

        const savedNote = await response.json();
        // Update local state for immediate feedback
        setReviewNotes(prev => {
            const existingNoteIndex = prev.findIndex(n => n.task_id === savedNote.taskId);
            if (existingNoteIndex > -1) {
                const newNotes = [...prev];
                newNotes[existingNoteIndex] = { ...newNotes[existingNoteIndex], notes: savedNote.notes };
                return newNotes;
            } else {
                return [...prev, { task_id: savedNote.taskId, operation_id: review.operationId, notes: savedNote.notes }];
            }
        });
        showToast('Observação salva com sucesso!', 'success');
      } catch (error) {
          console.error(error);
          showToast('Erro ao salvar observação.', 'error');
      } finally {
          handleCancelEditing();
      }
  };

  const getStatusBadge = (dueDate: string) => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const due = new Date(dueDate);
      due.setHours(0, 0, 0, 0);
      const diffDays = (due.getTime() - today.getTime()) / (1000 * 3600 * 24);

      if (diffDays < 0) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">Atrasada</span>;
      }
      if (diffDays <= 7) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">Próxima</span>;
      }
      return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">No Prazo</span>;
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Painel de Revisões de Crédito</h2>

        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
                <label htmlFor="analyst-filter" className="text-sm font-medium text-gray-700">Analista</label>
                <select id="analyst-filter" value={analystFilter} onChange={e => setAnalystFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    {analysts.map(name => <option key={name} value={name}>{name}</option>)}
                </select>
            </div>
             <div>
                <label htmlFor="area-filter" className="text-sm font-medium text-gray-700">Área</label>
                <select id="area-filter" value={areaFilter} onChange={e => setAreaFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    <option value="All">Todas</option>
                    <option value="CRI">CRI</option>
                    <option value="Capital Solutions">Capital Solutions</option>
                </select>
            </div>
            <div>
                <label htmlFor="start-date-filter" className="text-sm font-medium text-gray-700">Vencimento De</label>
                <input type="date" id="start-date-filter" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
             <div>
                <label htmlFor="end-date-filter" className="text-sm font-medium text-gray-700">Vencimento Até</label>
                <input type="date" id="end-date-filter" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
        </div>

        <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                    <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Operação</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Analista</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Tipo</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Próxima Revisão</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-1/3">Observações</th>
                        <th className="px-6 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                    {filteredReviews.map(review => (
                        <tr key={review.id} className="hover:bg-gray-50">
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{review.operationName}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{review.analyst}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{review.ruleName.replace('Revisão ', '')}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{new Date(review.dueDate).toLocaleDateString('pt-BR')}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm">{getStatusBadge(review.dueDate)}</td>
                            <td className="px-6 py-4 text-sm text-gray-600">
                                {editingTaskId === review.id ? (
                                    <div>
                                        <textarea
                                            value={editingNotes}
                                            onChange={(e) => setEditingNotes(e.target.value)}
                                            className="w-full p-2 border border-gray-300 rounded-md text-sm"
                                            rows={2}
                                        />
                                        <div className="flex gap-2 mt-1">
                                            <button onClick={handleSaveNote} className="text-xs bg-blue-500 text-white px-2 py-1 rounded hover:bg-blue-600">Salvar</button>
                                            <button onClick={handleCancelEditing} className="text-xs bg-gray-200 px-2 py-1 rounded hover:bg-gray-300">Cancelar</button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex items-start justify-between">
                                        <p className="whitespace-pre-wrap flex-1">{review.notes}</p>
                                        <button onClick={() => handleStartEditing(review)} className="ml-2 text-gray-400 hover:text-blue-600">
                                            <PencilIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                )}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-center text-sm">
                                <button
                                    onClick={() => onCompleteReview(review)}
                                    className="flex items-center justify-center gap-1.5 w-full px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm"
                                >
                                    <CheckCircleIcon className="w-4 h-4" /> Completar
                                </button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
            {(isLoadingNotes || filteredReviews.length === 0) && (
                 <div className="text-center py-8 text-gray-500">
                    {isLoadingNotes ? 'Carregando observações...' : 'Nenhuma revisão pendente encontrada para os filtros selecionados.'}
                </div>
            )}
        </div>
    </div>
  );
};

export default CreditReviewsPage;

