-- CRM Schema Update Script
-- This script updates an existing database schema to the latest version.
-- It is designed to be safely re-runnable on Databricks SQL.
-- It uses `ADD COLUMN IF NOT EXISTS` and `CREATE TABLE IF NOT EXISTS` to prevent errors.

USE cri.crm;

-- ====================================================================
-- Tabela: operations
-- Garante que a tabela principal de operações tenha todas as colunas necessárias.
-- ====================================================================
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS area STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS operation_type STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS maturity_date TIMESTAMP;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS responsible_analyst STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS review_frequency STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS call_frequency STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS df_frequency STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS segmento STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS rating_operation STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS rating_group STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS watchlist STRING;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS ltv FLOAT;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS dscr FLOAT;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_news BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_fii_report BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_operational_info BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_receivables_portfolio BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_construction_report BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_commercial_info BOOLEAN;
ALTER TABLE cri.crm.operations ADD COLUMN IF NOT EXISTS monitoring_spe_dfs BOOLEAN;

-- Nota sobre valores padrão:
-- No Databricks SQL, ALTER TABLE não suporta definir um valor DEFAULT diretamente.
-- Se precisar popular campos 'area' nulos existentes, execute separadamente:
-- UPDATE cri.crm.operations SET area = 'CRI' WHERE area IS NULL;

-- ====================================================================
-- Tabela: events
-- Adiciona a coluna para vincular um evento a uma tarefa concluída.
-- ====================================================================
ALTER TABLE cri.crm.events ADD COLUMN IF NOT EXISTS completed_task_id STRING;

-- ====================================================================
-- Tabela: rating_history
-- Adiciona colunas para vincular o histórico a um evento e para rastrear o status do watchlist e sentimento.
-- ====================================================================
ALTER TABLE cri.crm.rating_history ADD COLUMN IF NOT EXISTS event_id BIGINT;
ALTER TABLE cri.crm.rating_history ADD COLUMN IF NOT EXISTS watchlist STRING;
ALTER TABLE cri.crm.rating_history ADD COLUMN IF NOT EXISTS sentiment STRING;


-- ====================================================================
-- Tabela: task_exceptions
-- Cria a tabela para permitir que os usuários excluam tarefas permanentemente.
-- ====================================================================
CREATE TABLE IF NOT EXISTS cri.crm.task_exceptions (
    task_id STRING PRIMARY KEY,
    operation_id BIGINT,
    deleted_at TIMESTAMP,
    deleted_by STRING
);

-- ====================================================================
-- Tabela: audit_logs
-- Cria a tabela para fornecer um histórico completo de todas as alterações no sistema.
-- ====================================================================
CREATE TABLE IF NOT EXISTS cri.crm.audit_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    timestamp TIMESTAMP,
    user_name STRING,
    action STRING, -- e.g., 'CREATE', 'UPDATE', 'DELETE'
    entity_type STRING, -- e.g., 'Operation', 'TaskRule', 'Event'
    entity_id STRING, -- Pode ser BIGINT (para a maioria dos IDs) ou STRING (para IDs de tarefas)
    details STRING -- Descrição legível da alteração
);

-- ====================================================================
-- Tabela: operation_review_notes
-- Cria a tabela para armazenar observações editáveis para operações.
-- ====================================================================
CREATE TABLE IF NOT EXISTS cri.crm.operation_review_notes (
    operation_id BIGINT PRIMARY KEY,
    notes STRING,
    updated_at TIMESTAMP,
    updated_by STRING
);

import React, { useState, useMemo, useEffect } from 'react';
import type { Operation, Task, Area, OperationReviewNote } from '../types';
import { TaskStatus } from '../types';
import { PencilIcon, CheckCircleIcon } from './icons/Icons';

interface CreditReviewsPageProps {
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
  onCompleteReview: (task: Task) => void;
  apiUrl: string;
  showToast: (message: string, type: 'success' | 'error') => void;
}

const CreditReviewsPage: React.FC<CreditReviewsPageProps> = ({ operations, onUpdateOperation, onCompleteReview, apiUrl, showToast }) => {
  // Filters
  const [analystFilter, setAnalystFilter] = useState('All');
  const [areaFilter, setAreaFilter] = useState<'All' | Area>('All');
  const [dateFilter, setDateFilter] = useState({ start: '', end: '' });

  // In-line editing state
  const [editingOpId, setEditingOpId] = useState<number | null>(null);
  const [editingNotes, setEditingNotes] = useState('');

  const analysts = useMemo(() => ['All', ...new Set(operations.map(op => op.responsibleAnalyst))], [operations]);

  const filteredOperations = useMemo(() => {
    return operations
        .filter(op => {
            if (analystFilter !== 'All' && op.responsibleAnalyst !== analystFilter) return false;
            if (areaFilter !== 'All' && op.area !== areaFilter) return false;
            if (dateFilter.start || dateFilter.end) {
                const gerencialDate = op.nextReviewGerencialTask ? new Date(op.nextReviewGerencialTask.dueDate) : null;
                const politicaDate = op.nextReviewPoliticaTask ? new Date(op.nextReviewPoliticaTask.dueDate) : null;
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;

                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(23,59,59,999);

                const hasMatchingDate = 
                    (gerencialDate && (!startDate || gerencialDate >= startDate) && (!endDate || gerencialDate <= endDate)) ||
                    (politicaDate && (!startDate || politicaDate >= startDate) && (!endDate || politicaDate <= endDate));

                if (!hasMatchingDate) return false;
            }
            return true;
        })
        .sort((a, b) => a.name.localeCompare(b.name));
  }, [operations, analystFilter, areaFilter, dateFilter]);

  const handleStartEditing = (op: Operation) => {
      setEditingOpId(op.id);
      setEditingNotes(op.notes || '');
  };

  const handleCancelEditing = () => {
      setEditingOpId(null);
      setEditingNotes('');
  };

  const handleSaveNote = async () => {
      if (!editingOpId) return;

      const opToUpdate = operations.find(op => op.id === editingOpId);
      if (!opToUpdate) return;

      try {
        const response = await fetch(`${apiUrl}/api/operation_review_notes`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                operationId: editingOpId,
                notes: editingNotes,
                userName: opToUpdate.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a observação.');

        const savedNote = await response.json();

        // Optimistic UI update
        const updatedOperation = { ...opToUpdate, notes: savedNote.notes };
        onUpdateOperation(updatedOperation);

        showToast('Observação salva com sucesso!', 'success');
      } catch (error) {
          console.error(error);
          showToast('Erro ao salvar observação.', 'error');
      } finally {
          handleCancelEditing();
      }
  };

  const getStatusBadge = (dueDate: string) => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const due = new Date(dueDate);
      due.setHours(0, 0, 0, 0);
      const diffDays = (due.getTime() - today.getTime()) / (1000 * 3600 * 24);

      if (diffDays < 0) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">Atrasada</span>;
      }
      if (diffDays <= 7) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">Próxima</span>;
      }
      return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">No Prazo</span>;
  };

  const ReviewCell: React.FC<{ task: Task | null | undefined }> = ({ task }) => {
    if (!task) {
        return <span className="text-gray-400">N/A</span>;
    }
    return (
        <div className="flex flex-col gap-2">
            <div className="flex items-center gap-2">
                <span>{new Date(task.dueDate).toLocaleDateString('pt-BR')}</span>
                {getStatusBadge(task.dueDate)}
            </div>
            <button
                onClick={() => onCompleteReview(task)}
                className="flex items-center justify-center gap-1.5 w-full max-w-[120px] px-2 py-1 bg-green-600 text-white rounded-md hover:bg-green-700 text-xs"
            >
                <CheckCircleIcon className="w-4 h-4" /> Completar
            </button>
        </div>
    );
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Painel de Revisões de Crédito</h2>

        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
                <label htmlFor="analyst-filter" className="text-sm font-medium text-gray-700">Analista</label>
                <select id="analyst-filter" value={analystFilter} onChange={e => setAnalystFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    {analysts.map(name => <option key={name} value={name}>{name}</option>)}
                </select>
            </div>
             <div>
                <label htmlFor="area-filter" className="text-sm font-medium text-gray-700">Área</label>
                <select id="area-filter" value={areaFilter} onChange={e => setAreaFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    <option value="All">Todas</option>
                    <option value="CRI">CRI</option>
                    <option value="Capital Solutions">Capital Solutions</option>
                </select>
            </div>
            <div>
                <label htmlFor="start-date-filter" className="text-sm font-medium text-gray-700">Vencimento De</label>
                <input type="date" id="start-date-filter" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
             <div>
                <label htmlFor="end-date-filter" className="text-sm font-medium text-gray-700">Vencimento Até</label>
                <input type="date" id="end-date-filter" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
        </div>

        <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                    <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Operação</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Analista</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Próx. Rev. Gerencial</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Próx. Rev. Política</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-1/3">Observações</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                    {filteredOperations.map(op => (
                        <tr key={op.id} className="hover:bg-gray-50">
                            <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{op.name}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{op.responsibleAnalyst}</td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                <ReviewCell task={op.nextReviewGerencialTask} />
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                <ReviewCell task={op.nextReviewPoliticaTask} />
                            </td>
                            <td className="px-6 py-4 text-sm text-gray-600">
                                {editingOpId === op.id ? (
                                    <div>
                                        <textarea
                                            value={editingNotes}
                                            onChange={(e) => setEditingNotes(e.target.value)}
                                            className="w-full p-2 border border-gray-300 rounded-md text-sm"
                                            rows={3}
                                        />
                                        <div className="flex gap-2 mt-1">
                                            <button onClick={handleSaveNote} className="text-xs bg-blue-500 text-white px-2 py-1 rounded hover:bg-blue-600">Salvar</button>
                                            <button onClick={handleCancelEditing} className="text-xs bg-gray-200 px-2 py-1 rounded hover:bg-gray-300">Cancelar</button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="flex items-start justify-between">
                                        <p className="whitespace-pre-wrap flex-1">{op.notes}</p>
                                        <button onClick={() => handleStartEditing(op)} className="ml-2 text-gray-400 hover:text-blue-600 flex-shrink-0">
                                            <PencilIcon className="w-4 h-4" />
                                        </button>
                                    </div>
                                )}
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
            {filteredOperations.length === 0 && (
                 <div className="text-center py-8 text-gray-500">
                    Nenhuma operação encontrada para os filtros selecionados.
                </div>
            )}
        </div>
    </div>
  );
};

export default CreditReviewsPage;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Import Event to resolve name collision with DOM Event type, and TaskStatus for enum usage.
import type { Operation, Task, TaskRule, Rating, Sentiment, Event } from './types';
import { Page, TaskStatus } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';
import CreditReviewsPage from './components/CreditReviewsPage';
import ReviewCompletionForm from './components/ReviewCompletionForm';
import Toast from './components/Toast';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [reviewModalState, setReviewModalState] = useState<{isOpen: boolean; task: Task | null}>({isOpen: false, task: null});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{message: string; type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error') => {
      setToast({ message, type });
  };

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); // Clear previous errors on a new attempt
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    // Business logic for task generation is now on the backend.
    // The frontend just consumes the 'tasks' array.
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a operação');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        showToast('Operação adicionada com sucesso!', 'success');
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
        showToast('Erro ao adicionar operação.', 'error');
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];

    // Optimistic UI Update: Update the state immediately for a responsive feel.
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });

      if (!response.ok) {
        let errorMsg = 'Falha ao salvar as alterações. Tente novamente.';
        try {
            const errorData = await response.json();
            errorMsg = errorData.error || errorMsg;
        } catch(e) { /* Ignore if body isn't json */ }
        throw new Error(errorMsg);
      }

      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
      showToast('Alterações salvas com sucesso!', 'success');
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      setOperations(originalOperations);
      const errorMessage = error instanceof Error ? error.message : 'Ocorreu um erro desconhecido.';
      showToast(`Erro ao salvar: ${errorMessage}`, 'error');
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    const originalOperations = [...operations];
    // Optimistic UI delete
    setOperations(prev => prev.filter(op => op.id !== operationId));

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }

      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
      showToast('Operação deletada com sucesso!', 'success');
    } catch (error) {
      console.error("Error deleting operation:", error);
      setOperations(originalOperations); // Rollback on error
      showToast('Erro ao deletar a operação. A exclusão foi revertida.', 'error');
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];

    // Optimistic UI: Remove task from the specific operation
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));

    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao deletar a tarefa');

        const updatedOperation = await response.json();
        // Sync state with the server's response
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
        showToast('Tarefa deletada com sucesso!', 'success');

    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations); // Rollback
        showToast('Erro ao deletar a tarefa.', 'error');
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];

     // Optimistic UI:
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            // 1. Remove the old task
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            // 2. Create a new ad-hoc rule for the edited task
            const newAdHocRule: TaskRule = {
                id: Date.now(), // Temporary client-side ID
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate).toISOString(),
                endDate: new Date(updates.dueDate).toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks, // Temporarily remove, will be replaced by backend's full list
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));

    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao editar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
        showToast('Tarefa editada com sucesso!', 'success');

    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations); // Rollback
        showToast('Erro ao editar a tarefa.', 'error');
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
      const clickedTask = reviewModalState.task;
      if (!clickedTask) return;

      const operation = operations.find(op => op.id === clickedTask.operationId);
      if (!operation) return;

      const newEventId = Date.now();
      // The event is still linked to the task that was clicked for traceability
      const eventToSave: Event = {
          ...data.event,
          id: newEventId,
          completedTaskId: clickedTask.id
      };

      const newHistoryEntry = {
          id: Date.now() + 1,
          date: eventToSave.date,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          watchlist: operation.watchlist,
          sentiment: data.sentiment,
          eventId: newEventId,
      };

      // NEW LOGIC: Mark both next Gerencial and Politica tasks as completed.
      const gerencialTaskToCompleteId = operation.nextReviewGerencialTask?.id;
      const politicaTaskToCompleteId = operation.nextReviewPoliticaTask?.id;

      const updatedTasks = operation.tasks.map(t => {
          if (t.id === gerencialTaskToCompleteId || t.id === politicaTaskToCompleteId) {
              return { ...t, status: TaskStatus.COMPLETED };
          }
          return t;
      });

      const updatedOperation = {
          ...operation,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          events: [...operation.events, eventToSave],
          ratingHistory: [...operation.ratingHistory, newHistoryEntry],
          tasks: updatedTasks
      };

      handleUpdateOperation(updatedOperation);
      setReviewModalState({ isOpen: false, task: null });
  };


  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return (
                <>
                    {/* The overdue highlight is now only shown on the overview page */}
                    <OverdueOperationsHighlight
                        operations={operations}
                        onNavigate={handleNavigate}
                    />
                    <OverviewDashboard
                        operations={operations}
                        onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                        onAddOperation={handleAddOperation}
                        onOpenNewTaskModal={openNewTaskModal}
                        onDeleteOperation={handleDeleteOperation}
                    />
                </>
            );
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
            />;
        case Page.CREDIT_REVIEWS:
            return <CreditReviewsPage
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
                onCompleteReview={(task) => setReviewModalState({ isOpen: true, task })}
                apiUrl={API_BASE_URL}
                showToast={showToast}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      {reviewModalState.isOpen && reviewModalState.task && (
          <ReviewCompletionForm
              task={reviewModalState.task}
              operation={operations.find(op => op.id === reviewModalState.task!.operationId)!}
              onClose={() => setReviewModalState({ isOpen: false, task: null })}
              onSave={handleSaveReview}
          />
      )}
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import type { Task, Operation, Event, Rating, Sentiment } from '../types';
import { ratingOptions, Sentiment as SentimentEnum } from '../types';
import Modal from './Modal';

interface ReviewCompletionFormProps {
  task: Task;
  operation: Operation;
  onClose: () => void;
  onSave: (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => void;
}

const Label: React.FC<{htmlFor: string; children: React.ReactNode}> = ({ htmlFor, children }) => <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">{children}</label>;
const Select: React.FC<React.SelectHTMLAttributes<HTMLSelectElement>> = (props) => <select {...props} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />;
const Textarea: React.FC<React.TextareaHTMLAttributes<HTMLTextAreaElement>> = (props) => <textarea {...props} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />;
const Input: React.FC<React.InputHTMLAttributes<HTMLInputElement>> = (props) => <input {...props} className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500" />;


const ReviewCompletionForm: React.FC<ReviewCompletionFormProps> = ({ task, operation, onClose, onSave }) => {
  const [completionDate, setCompletionDate] = useState(new Date().toISOString().split('T')[0]);
  const [ratingOp, setRatingOp] = useState(operation.ratingOperation);
  const [ratingGroup, setRatingGroup] = useState(operation.ratingGroup);
  const [sentiment, setSentiment] = useState<Sentiment>(SentimentEnum.NEUTRO);
  const [description, setDescription] = useState('');
  const [nextSteps, setNextSteps] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const event: Omit<Event, 'id'> = {
      date: new Date(completionDate).toISOString(),
      type: 'Revisão Periódica',
      title: `Conclusão: ${task.ruleName}`,
      description,
      registeredBy: operation.responsibleAnalyst,
      nextSteps,
    };

    onSave({ event, ratingOp, ratingGroup, sentiment });
    onClose();
  };

  return (
    <Modal isOpen={true} onClose={onClose} title={`Concluir Revisão Periódica: ${operation.name}`}>
      <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-md text-sm text-blue-800">
        <p><strong>Atenção:</strong> Ao salvar, as próximas revisões pendentes (Gerencial e Política) para esta operação serão marcadas como concluídas.</p>
      </div>
      <form onSubmit={handleSubmit} className="space-y-4">

        <div>
            <Label htmlFor="review-completion-date">Data de Conclusão</Label>
            <Input id="review-completion-date" type="date" value={completionDate} onChange={e => setCompletionDate(e.target.value)} required />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
                <Label htmlFor="review-rating-op">Rating Operação</Label>
                <Select id="review-rating-op" value={ratingOp} onChange={e => setRatingOp(e.target.value as Rating)}>
                    {ratingOptions.map(r => <option key={r} value={r}>{r}</option>)}
                </Select>
            </div>
            <div>
                <Label htmlFor="review-rating-group">Rating Grupo</Label>
                <Select id="review-rating-group" value={ratingGroup} onChange={e => setRatingGroup(e.target.value as Rating)}>
                    {ratingOptions.map(r => <option key={r} value={r}>{r}</option>)}
                </Select>
            </div>
            <div>
                <Label htmlFor="review-sentiment">Sentimento</Label>
                <Select id="review-sentiment" value={sentiment} onChange={e => setSentiment(e.target.value as Sentiment)}>
                    {Object.values(SentimentEnum).map(s => <option key={s} value={s}>{s}</option>)}
                </Select>
            </div>
        </div>

        <div>
            <Label htmlFor="review-description">Descrição / Resumo da Revisão</Label>
            <Textarea id="review-description" value={description} onChange={e => setDescription(e.target.value)} rows={4} required />
        </div>
        <div>
            <Label htmlFor="review-next-steps">Próximos Passos</Label>
            <Textarea id="review-next-steps" value={nextSteps} onChange={e => setNextSteps(e.target.value)} rows={2} />
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300">Cancelar</button>
          <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700">Concluir e Salvar Revisão</button>
        </div>
      </form>
    </Modal>
  );
};

export default ReviewCompletionForm;

import React, { useState, useMemo, useEffect } from 'react';
import type { Operation, Task, Area, OperationReviewNote } from '../types';
import { TaskStatus } from '../types';
import { PencilIcon, CheckCircleIcon } from './icons/Icons';

interface CreditReviewsPageProps {
  operations: Operation[];
  onUpdateOperation: (updatedOperation: Operation) => void;
  onCompleteReview: (task: Task) => void;
  apiUrl: string;
  showToast: (message: string, type: 'success' | 'error') => void;
}

const CreditReviewsPage: React.FC<CreditReviewsPageProps> = ({ operations, onUpdateOperation, onCompleteReview, apiUrl, showToast }) => {
  // Filters
  const [analystFilter, setAnalystFilter] = useState('All');
  const [areaFilter, setAreaFilter] = useState<'All' | Area>('All');
  const [dateFilter, setDateFilter] = useState({ start: '', end: '' });

  // In-line editing state
  const [editingOpId, setEditingOpId] = useState<number | null>(null);
  const [editingNotes, setEditingNotes] = useState('');

  const analysts = useMemo(() => ['All', ...new Set(operations.map(op => op.responsibleAnalyst))], [operations]);

  const filteredOperations = useMemo(() => {
    return operations
        .filter(op => {
            if (analystFilter !== 'All' && op.responsibleAnalyst !== analystFilter) return false;
            if (areaFilter !== 'All' && op.area !== areaFilter) return false;
            if (dateFilter.start || dateFilter.end) {
                const gerencialDate = op.nextReviewGerencialTask ? new Date(op.nextReviewGerencialTask.dueDate) : null;
                const politicaDate = op.nextReviewPoliticaTask ? new Date(op.nextReviewPoliticaTask.dueDate) : null;
                const startDate = dateFilter.start ? new Date(dateFilter.start) : null;
                const endDate = dateFilter.end ? new Date(dateFilter.end) : null;

                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(23,59,59,999);

                const hasMatchingDate = 
                    (gerencialDate && (!startDate || gerencialDate >= startDate) && (!endDate || gerencialDate <= endDate)) ||
                    (politicaDate && (!startDate || politicaDate >= startDate) && (!endDate || politicaDate <= endDate));

                if (!hasMatchingDate) return false;
            }
            return true;
        })
        .sort((a, b) => a.name.localeCompare(b.name));
  }, [operations, analystFilter, areaFilter, dateFilter]);

  const handleStartEditing = (op: Operation) => {
      setEditingOpId(op.id);
      setEditingNotes(op.notes || '');
  };

  const handleCancelEditing = () => {
      setEditingOpId(null);
      setEditingNotes('');
  };

  const handleSaveNote = async () => {
      if (!editingOpId) return;

      const opToUpdate = operations.find(op => op.id === editingOpId);
      if (!opToUpdate) return;

      try {
        const response = await fetch(`${apiUrl}/api/operation_review_notes`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                operationId: editingOpId,
                notes: editingNotes,
                userName: opToUpdate.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a observação.');

        const savedNote = await response.json();

        // Optimistic UI update
        const updatedOperation = { ...opToUpdate, notes: savedNote.notes };
        onUpdateOperation(updatedOperation);

        showToast('Observação salva com sucesso!', 'success');
      } catch (error) {
          console.error(error);
          showToast('Erro ao salvar observação.', 'error');
      } finally {
          handleCancelEditing();
      }
  };

  const getStatusBadge = (dueDate: string) => {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const due = new Date(dueDate);
      due.setHours(0, 0, 0, 0);
      const diffDays = (due.getTime() - today.getTime()) / (1000 * 3600 * 24);

      if (diffDays < 0) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-red-100 text-red-800">Atrasada</span>;
      }
      if (diffDays <= 7) {
          return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-yellow-100 text-yellow-800">Próxima</span>;
      }
      return <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-green-100 text-green-800">No Prazo</span>;
  };

  const ReviewInfoCell: React.FC<{ task: Task | null | undefined }> = ({ task }) => {
    if (!task) {
        return <span className="text-gray-400">N/A</span>;
    }
    return (
        <div className="flex items-center gap-2">
            <span>{new Date(task.dueDate).toLocaleDateString('pt-BR')}</span>
            {getStatusBadge(task.dueDate)}
        </div>
    );
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">Painel de Revisões de Crédito</h2>

        <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
                <label htmlFor="analyst-filter" className="text-sm font-medium text-gray-700">Analista</label>
                <select id="analyst-filter" value={analystFilter} onChange={e => setAnalystFilter(e.target.value)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    {analysts.map(name => <option key={name} value={name}>{name}</option>)}
                </select>
            </div>
             <div>
                <label htmlFor="area-filter" className="text-sm font-medium text-gray-700">Área</label>
                <select id="area-filter" value={areaFilter} onChange={e => setAreaFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                    <option value="All">Todas</option>
                    <option value="CRI">CRI</option>
                    <option value="Capital Solutions">Capital Solutions</option>
                </select>
            </div>
            <div>
                <label htmlFor="start-date-filter" className="text-sm font-medium text-gray-700">Vencimento De</label>
                <input type="date" id="start-date-filter" value={dateFilter.start} onChange={e => setDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
             <div>
                <label htmlFor="end-date-filter" className="text-sm font-medium text-gray-700">Vencimento Até</label>
                <input type="date" id="end-date-filter" value={dateFilter.end} onChange={e => setDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
            </div>
        </div>

        <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                    <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Operação</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Analista</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Próx. Rev. Gerencial</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Próx. Rev. Política</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Ações</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-1/3">Observações</th>
                    </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                    {filteredOperations.map(op => {
                        const gerencialTask = op.nextReviewGerencialTask;
                        const politicaTask = op.nextReviewPoliticaTask;
                        let taskForCompletion: Task | null = null;

                        if (gerencialTask && politicaTask) {
                            taskForCompletion = new Date(gerencialTask.dueDate) <= new Date(politicaTask.dueDate) ? gerencialTask : politicaTask;
                        } else {
                            taskForCompletion = gerencialTask || politicaTask || null;
                        }

                        return (
                            <tr key={op.id} className="hover:bg-gray-50">
                                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{op.name}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{op.responsibleAnalyst}</td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <ReviewInfoCell task={gerencialTask} />
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    <ReviewInfoCell task={politicaTask} />
                                </td>
                                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                    {taskForCompletion ? (
                                        <button
                                            onClick={() => onCompleteReview(taskForCompletion!)}
                                            className="flex items-center justify-center gap-1.5 w-full max-w-[120px] px-2 py-1 bg-green-600 text-white rounded-md hover:bg-green-700 text-xs"
                                        >
                                            <CheckCircleIcon className="w-4 h-4" /> Completar
                                        </button>
                                    ) : (
                                        <span className="text-gray-400">-</span>
                                    )}
                                </td>
                                <td className="px-6 py-4 text-sm text-gray-600">
                                    {editingOpId === op.id ? (
                                        <div>
                                            <textarea
                                                value={editingNotes}
                                                onChange={(e) => setEditingNotes(e.target.value)}
                                                className="w-full p-2 border border-gray-300 rounded-md text-sm"
                                                rows={3}
                                            />
                                            <div className="flex gap-2 mt-1">
                                                <button onClick={handleSaveNote} className="text-xs bg-blue-500 text-white px-2 py-1 rounded hover:bg-blue-600">Salvar</button>
                                                <button onClick={handleCancelEditing} className="text-xs bg-gray-200 px-2 py-1 rounded hover:bg-gray-300">Cancelar</button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex items-start justify-between">
                                            <p className="whitespace-pre-wrap flex-1">{op.notes}</p>
                                            <button onClick={() => handleStartEditing(op)} className="ml-2 text-gray-400 hover:text-blue-600 flex-shrink-0">
                                                <PencilIcon className="w-4 h-4" />
                                            </button>
                                        </div>
                                    )}
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>
            {filteredOperations.length === 0 && (
                 <div className="text-center py-8 text-gray-500">
                    Nenhuma operação encontrada para os filtros selecionados.
                </div>
            )}
        </div>
    </div>
  );
};

export default CreditReviewsPage;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Import Event to resolve name collision with DOM Event type, and TaskStatus for enum usage.
import type { Operation, Task, TaskRule, Rating, Sentiment, Event } from './types';
import { Page, TaskStatus } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';
import CreditReviewsPage from './components/CreditReviewsPage';
import ReviewCompletionForm from './components/ReviewCompletionForm';
import Toast from './components/Toast';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [reviewModalState, setReviewModalState] = useState<{isOpen: boolean; task: Task | null}>({isOpen: false, task: null});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{message: string; type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error') => {
      setToast({ message, type });
  };

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); // Clear previous errors on a new attempt
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    // Business logic for task generation is now on the backend.
    // The frontend just consumes the 'tasks' array.
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a operação');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        showToast('Operação adicionada com sucesso!', 'success');
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
        showToast('Erro ao adicionar operação.', 'error');
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];

    // Optimistic UI Update: Update the state immediately for a responsive feel.
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });

      if (!response.ok) {
        let errorMsg = 'Falha ao salvar as alterações. Tente novamente.';
        try {
            const errorData = await response.json();
            errorMsg = errorData.error || errorMsg;
        } catch(e) { /* Ignore if body isn't json */ }
        throw new Error(errorMsg);
      }

      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
      showToast('Alterações salvas com sucesso!', 'success');
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      setOperations(originalOperations);
      const errorMessage = error instanceof Error ? error.message : 'Ocorreu um erro desconhecido.';
      showToast(`Erro ao salvar: ${errorMessage}`, 'error');
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    const originalOperations = [...operations];
    // Optimistic UI delete
    setOperations(prev => prev.filter(op => op.id !== operationId));

    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }

      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
      showToast('Operação deletada com sucesso!', 'success');
    } catch (error) {
      console.error("Error deleting operation:", error);
      setOperations(originalOperations); // Rollback on error
      showToast('Erro ao deletar a operação. A exclusão foi revertida.', 'error');
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];

    // Optimistic UI: Remove task from the specific operation
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));

    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao deletar a tarefa');

        const updatedOperation = await response.json();
        // Sync state with the server's response
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
        showToast('Tarefa deletada com sucesso!', 'success');

    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations); // Rollback
        showToast('Erro ao deletar a tarefa.', 'error');
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];

     // Optimistic UI:
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            // 1. Remove the old task
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            // 2. Create a new ad-hoc rule for the edited task
            const newAdHocRule: TaskRule = {
                id: Date.now(), // Temporary client-side ID
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate).toISOString(),
                endDate: new Date(updates.dueDate).toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks, // Temporarily remove, will be replaced by backend's full list
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));

    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao editar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
        showToast('Tarefa editada com sucesso!', 'success');

    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations); // Rollback
        showToast('Erro ao editar a tarefa.', 'error');
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
      const clickedTask = reviewModalState.task;
      if (!clickedTask) return;

      const operation = operations.find(op => op.id === clickedTask.operationId);
      if (!operation) return;

      const eventsToAdd: Event[] = [];
      const gerencialTaskToComplete = operation.nextReviewGerencialTask;
      const politicaTaskToComplete = operation.nextReviewPoliticaTask;

      const baseEventData = {
          date: new Date(data.event.date).toISOString(),
          type: 'Revisão Periódica',
          description: data.event.description,
          registeredBy: data.event.registeredBy,
          nextSteps: data.event.nextSteps,
      };

      if (gerencialTaskToComplete) {
          eventsToAdd.push({
              ...baseEventData,
              id: Date.now() + Math.random(),
              title: `Conclusão: Revisão Gerencial`,
              completedTaskId: gerencialTaskToComplete.id,
          });
      }

      if (politicaTaskToComplete && politicaTaskToComplete.id !== gerencialTaskToComplete?.id) {
          eventsToAdd.push({
              ...baseEventData,
              id: Date.now() + Math.random(),
              title: `Conclusão: Revisão Política`,
              completedTaskId: politicaTaskToComplete.id,
          });
      }

      // Fallback in case no tasks are found, to ensure the event is still logged.
      if (eventsToAdd.length === 0) {
          eventsToAdd.push({
              ...baseEventData,
              id: Date.now() + Math.random(),
              title: `Revisão Periódica (Manual)`,
              completedTaskId: clickedTask.id,
          });
      }

      const newHistoryEntry = {
          id: Date.now() + 1,
          date: baseEventData.date,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          watchlist: operation.watchlist,
          sentiment: data.sentiment,
          eventId: eventsToAdd[0].id, // Link to the first created event
      };

      // For optimistic UI update
      const tasksToCompleteIds = new Set([gerencialTaskToComplete?.id, politicaTaskToComplete?.id].filter(Boolean));
      const updatedTasks = operation.tasks.map(t => {
          if (tasksToCompleteIds.has(t.id)) {
              return { ...t, status: TaskStatus.COMPLETED };
          }
          return t;
      });

      const updatedOperation = {
          ...operation,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          events: [...operation.events, ...eventsToAdd],
          ratingHistory: [...operation.ratingHistory, newHistoryEntry],
          tasks: updatedTasks,
      };

      handleUpdateOperation(updatedOperation);
      setReviewModalState({ isOpen: false, task: null });
  };


  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return (
                <>
                    {/* The overdue highlight is now only shown on the overview page */}
                    <OverdueOperationsHighlight
                        operations={operations}
                        onNavigate={handleNavigate}
                    />
                    <OverviewDashboard
                        operations={operations}
                        onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                        onAddOperation={handleAddOperation}
                        onOpenNewTaskModal={openNewTaskModal}
                        onDeleteOperation={handleDeleteOperation}
                    />
                </>
            );
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
            />;
        case Page.CREDIT_REVIEWS:
            return <CreditReviewsPage
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
                onCompleteReview={(task) => setReviewModalState({ isOpen: true, task })}
                apiUrl={API_BASE_URL}
                showToast={showToast}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      {reviewModalState.isOpen && reviewModalState.task && (
          <ReviewCompletionForm
              task={reviewModalState.task}
              operation={operations.find(op => op.id === reviewModalState.task!.operationId)!}
              onClose={() => setReviewModalState({ isOpen: false, task: null })}
              onSave={handleSaveReview}
          />
      )}
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <h1 className="text-2xl font-bold text-gray-800">
                CRM de Crédito Estruturado
              </h1>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

