              >
                Confirmar Deleção
              </button>
            </div>
          </div>
        </Modal>
      )}

      <div className="bg-white p-6 rounded-lg shadow-lg">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-xl font-bold text-gray-700">Resumo de Operações</h2>
