import React, { useState, useMemo, useRef } from 'react';
import type { Operation, Event, Task, RatingHistoryEntry, Rating, Sentiment, TaskRule } from '../types';
import { TaskStatus, ratingOptions, WatchlistStatus, Sentiment as SentimentEnum } from '../types';
import { PlusCircleIcon, CheckCircleIcon, EyeIcon, ArrowUpIcon, ArrowRightIcon, ArrowDownIcon, BellIcon, PencilIcon, TrashIcon, DownloadIcon } from './icons/Icons';
import EventForm from './EventForm';
import WatchlistChangeForm from './WatchlistChangeForm';
import ReviewCompletionForm from './ReviewCompletionForm';
import TaskRuleForm from './TaskRuleForm';
import Modal from './Modal';
import AdHocTaskForm from './AdHocTaskForm';
import RatingHistoryChart from './RatingHistoryChart';
import EventHistory from './EventHistory';

interface OperationDetailProps {
  operation: Operation;
  onUpdateOperation: (updatedOperation: Operation) => void;
  onOpenNewTaskModal: (operationId: number) => void;
  onDeleteTask: (task: Task) => void;
  onEditTask: (task: Task, updates: { name: string, dueDate: string }) => void;
}

const InfoCard: React.FC<{ title: string; children: React.ReactNode; highlight?: boolean }> = ({ title, children, highlight = false }) => (
    <div className={`${highlight ? 'bg-blue-50 border border-blue-200' : 'bg-gray-50'} p-3 rounded-md`}>
        <h4 className={`text-xs ${highlight ? 'text-blue-600' : 'text-gray-500'} font-semibold uppercase`}>{title}</h4>
        <p className={`${highlight ? 'text-blue-900 font-bold text-lg' : 'text-gray-800 font-medium'}`}>{children}</p>
    </div>
);

const getRatingChange = (currentRating: Rating, previousRating: Rating | undefined): 'up' | 'down' | 'neutral' => {
    if (!previousRating || currentRating === previousRating) {
        return 'neutral';
    }
    const currentIndex = ratingOptions.indexOf(currentRating);
    const previousIndex = ratingOptions.indexOf(previousRating);

    if (currentIndex < 0 || previousIndex < 0) return 'neutral';

    if (currentIndex < previousIndex) return 'up'; // Better rating
    if (currentIndex > previousIndex) return 'down'; // Worse rating
    return 'neutral';
};

const RatingChangeIndicator: React.FC<{ change: 'up' | 'down' | 'neutral' }> = ({ change }) => {
    if (change === 'up') {
        return <ArrowUpIcon className="w-4 h-4 text-green-600" title="Upgrade" />;
    }
    if (change === 'down') {
        return <ArrowDownIcon className="w-4 h-4 text-red-600" title="Downgrade" />;
    }
    return <ArrowRightIcon className="w-4 h-4 text-gray-400" title="Sem alteração" />;
};


const OperationDetail: React.FC<OperationDetailProps> = ({ operation, onUpdateOperation, onOpenNewTaskModal, onDeleteTask, onEditTask }) => {
    const [isEventFormOpen, setIsEventFormOpen] = useState(false);
    const [eventToEdit, setEventToEdit] = useState<Event | null>(null);
    const [isWatchlistFormOpen, setIsWatchlistFormOpen] = useState(false);
    const [isReviewFormOpen, setIsReviewFormOpen] = useState(false);

    const [taskToComplete, setTaskToComplete] = useState<Task | null>(null);
    const [reviewTaskToComplete, setReviewTaskToComplete] = useState<Task | null>(null);

    const [expandedEventId, setExpandedEventId] = useState<number | null>(null);
    const eventRefs = useRef<Record<number, HTMLDivElement | null>>({});

    // State for filtering events
    const [eventDateFilter, setEventDateFilter] = useState({ start: '', end: '' });
    const [eventTypeFilter, setEventTypeFilter] = useState('Todos');
    const [eventPersonFilter, setEventPersonFilter] = useState('Todos');

    // State for filtering tasks
    const [taskStatusFilter, setTaskStatusFilter] = useState<'all' | 'pending' | 'overdue'>('all');
    const [taskDateFilter, setTaskDateFilter] = useState({ start: '', end: '' });

    // State for managing task rules
    const [ruleToEdit, setRuleToEdit] = useState<TaskRule | null>(null);
    const [ruleToDelete, setRuleToDelete] = useState<TaskRule | null>(null);

    // State for managing individual tasks
    const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);
    const [taskToDelete, setTaskToDelete] = useState<Task | null>(null);


    const tasks = operation.tasks || [];

    const sortedHistory = useMemo(() => {
        return [...operation.ratingHistory].sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.ratingHistory]);

    const currentWatchlistStatus = useMemo(() => {
        return sortedHistory[0]?.watchlist ?? operation.watchlist;
    }, [sortedHistory, operation.watchlist]);

    const activeTasks = useMemo(() => {
        return tasks
            .filter(t => t.status === TaskStatus.PENDING || t.status === TaskStatus.OVERDUE)
            .filter(task => { // Status filter
                if (taskStatusFilter === 'all') return true;
                if (taskStatusFilter === 'pending') return task.status === TaskStatus.PENDING;
                if (taskStatusFilter === 'overdue') return task.status === TaskStatus.OVERDUE;
                return true;
            })
            .filter(task => { // Date filter
                if (!taskDateFilter.start && !taskDateFilter.end) return true;
                const taskDate = new Date(task.dueDate);
                taskDate.setHours(0,0,0,0);
                const startDate = taskDateFilter.start ? new Date(taskDateFilter.start) : null;
                const endDate = taskDateFilter.end ? new Date(taskDateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && taskDate < startDate) return false;
                if (endDate && taskDate > endDate) return false;
                return true;
            })
            .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
    }, [tasks, taskStatusFilter, taskDateFilter]);

    const completedTasks = useMemo(() => {
        return tasks.filter(t => t.status === TaskStatus.COMPLETED)
            .sort((a, b) => {
                const eventA = operation.events.find(e => e.completedTaskId === a.id);
                const eventB = operation.events.find(e => e.completedTaskId === b.id);
                return (eventB ? new Date(eventB.date).getTime() : 0) - (eventA ? new Date(eventA.date).getTime() : 0);
            });
    }, [tasks, operation.events]);

    const uniqueEventTypes = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.type))], [operation.events]);
    const uniqueRegisteredBy = useMemo(() => ['Todos', ...new Set(operation.events.map(e => e.registeredBy))], [operation.events]);

    const filteredEvents = useMemo(() => {
        return [...operation.events]
            .filter(event => {
                if (!eventDateFilter.start && !eventDateFilter.end) return true;
                const eventDate = new Date(event.date);
                eventDate.setHours(0,0,0,0);
                const startDate = eventDateFilter.start ? new Date(eventDateFilter.start) : null;
                const endDate = eventDateFilter.end ? new Date(eventDateFilter.end) : null;
                if(startDate) startDate.setHours(0,0,0,0);
                if(endDate) endDate.setHours(0,0,0,0);
                if (startDate && eventDate < startDate) return false;
                if (endDate && eventDate > endDate) return false;
                return true;
            })
            .filter(event => eventTypeFilter === 'Todos' || event.type === eventTypeFilter)
            .filter(event => eventPersonFilter === 'Todos' || event.registeredBy === eventPersonFilter)
            .sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [operation.events, eventDateFilter, eventTypeFilter, eventPersonFilter]);

    const handleSaveEvent = (eventData: Omit<Event, 'id'>, id?: number) => {
        let updatedOperation;
        if (id) {
            const updatedEvents = operation.events.map(e => 
                e.id === id ? { ...e, ...eventData } : e
            );
            updatedOperation = { ...operation, events: updatedEvents };
        } else {
            const eventToSave: Partial<Event> = { ...eventData };
            if (taskToComplete) {
                eventToSave.completedTaskId = taskToComplete.id;
            }

            const updatedTasks = taskToComplete
                ? operation.tasks.map(t => t.id === taskToComplete.id ? { ...t, status: TaskStatus.COMPLETED } : t)
                : operation.tasks;

            updatedOperation = {
                ...operation,
                events: [...operation.events, { ...eventToSave, id: Date.now() } as Event],
                tasks: updatedTasks
            };
        }
        onUpdateOperation(updatedOperation);
        setTaskToComplete(null);
        setIsEventFormOpen(false);
        setEventToEdit(null);
    };

    const handleOpenEditEventModal = (event: Event) => {
        setEventToEdit(event);
        setIsEventFormOpen(true);
    };

    const handleDownloadEvent = (event: Event) => {
        const content = `
Título: ${event.title}
Data: ${new Date(event.date).toLocaleDateString('pt-BR')}
Tipo: ${event.type}
Registrado por: ${event.registeredBy}

--------------------
Descrição:
--------------------
${event.description}

--------------------
Próximos Passos:
--------------------
${event.nextSteps || 'Nenhum'}
        `.trim().replace(/^\s+/gm, '');

        const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        const sanitizedTitle = event.title.replace(/[^a-z0-9]/gi, '_').toLowerCase();
        link.download = `evento_${sanitizedTitle}_${event.id}.txt`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    const handleCompleteTaskClick = (task: Task) => {
        if (task.ruleName === 'Revisão Gerencial' || task.ruleName === 'Revisão Política') {
            setReviewTaskToComplete(task);
            setIsReviewFormOpen(true);
        } else {
            setTaskToComplete(task);
            setIsEventFormOpen(true);
        }
    };

    const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
        const newEventId = Date.now();
        const eventToSave: Event = {
            ...data.event,
            id: newEventId,
            completedTaskId: reviewTaskToComplete?.id
        };

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            watchlist: operation.watchlist,
            sentiment: data.sentiment,
            eventId: newEventId,
        };

        const updatedTasks = reviewTaskToComplete
            ? operation.tasks.map(t => t.id === reviewTaskToComplete.id ? { ...t, status: TaskStatus.COMPLETED } : t)
            : operation.tasks;

        const updatedOperation: Operation = {
            ...operation,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
            ratingHistory: [...operation.ratingHistory, newHistoryEntry],
            tasks: updatedTasks
        };

        onUpdateOperation(updatedOperation);
        setReviewTaskToComplete(null);
        setIsReviewFormOpen(false);
    };

    const handleSaveWatchlistChange = (data: { watchlist: WatchlistStatus, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment, event: Omit<Event, 'id'>}) => {
        const newEventId = Date.now();
        const eventToSave: Event = { ...data.event, id: newEventId };

        const newHistoryEntry: RatingHistoryEntry = {
            id: Date.now() + 1,
            date: eventToSave.date,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            watchlist: data.watchlist,
            sentiment: data.sentiment,
            eventId: newEventId,
        };

        const updatedOperation: Operation = {
            ...operation,
            watchlist: data.watchlist,
            ratingOperation: data.ratingOp,
            ratingGroup: data.ratingGroup,
            events: [...operation.events, eventToSave],
            ratingHistory: [...operation.ratingHistory, newHistoryEntry],
        };

        onUpdateOperation(updatedOperation);
        setIsWatchlistFormOpen(false);
    };

    const handleUpdateRule = (updatedRuleData: Omit<TaskRule, 'id'>) => {
        if (!ruleToEdit) return;
        const updatedRule = { ...ruleToEdit, ...updatedRuleData };
        const updatedOperation = {
            ...operation,
            taskRules: operation.taskRules.map(r => r.id === ruleToEdit.id ? updatedRule : r)
        };
        onUpdateOperation(updatedOperation);
        setRuleToEdit(null);
    };

    const handleConfirmDeleteRule = () => {
        if (!ruleToDelete) return;
        const updatedOperation = {
            ...operation,
            taskRules: operation.taskRules.filter(r => r.id !== ruleToDelete.id)
        };
        onUpdateOperation(updatedOperation);
        setRuleToDelete(null);
    };

    const handleConfirmDeleteTask = () => {
        if (taskToDelete) {
            onDeleteTask(taskToDelete);
            setTaskToDelete(null);
        }
    };

    const handleSaveEditedTask = (rule: Omit<TaskRule, 'id'>) => {
        if (taskToEdit) {
            onEditTask(taskToEdit, { name: rule.name, dueDate: rule.startDate });
            setTaskToEdit(null);
        }
    };

    const handleViewEventClick = (taskId: string) => {
        const completionEvent = operation.events.find(e => e.completedTaskId === taskId);
        if (completionEvent) {
            setExpandedEventId(completionEvent.id);
            const eventElement = eventRefs.current[completionEvent.id];
            if (eventElement) {
                eventElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }

    const watchlistColorClasses = {
      [WatchlistStatus.VERDE]: 'bg-green-500 text-white hover:bg-green-600',
      [WatchlistStatus.AMARELO]: 'bg-yellow-400 text-yellow-900 hover:bg-yellow-500',
      [WatchlistStatus.ROSA]: 'bg-pink-500 text-white hover:bg-pink-600',
      [WatchlistStatus.VERMELHO]: 'bg-red-600 text-white hover:bg-red-700',
    };

    return (
        <div className="space-y-8">
            {(isEventFormOpen || eventToEdit) && (
                <EventForm 
                    onClose={() => { setIsEventFormOpen(false); setTaskToComplete(null); setEventToEdit(null); }} 
                    onSave={handleSaveEvent}
                    analystName={operation.responsibleAnalyst}
                    prefilledTitle={taskToComplete ? `Conclusão: ${taskToComplete.ruleName}` : ''}
                    initialData={eventToEdit}
                />
            )}
            {isWatchlistFormOpen && (
                <WatchlistChangeForm
                    operation={operation}
                    onClose={() => setIsWatchlistFormOpen(false)}
                    onSave={handleSaveWatchlistChange}
                />
            )}
            {isReviewFormOpen && reviewTaskToComplete && (
                <ReviewCompletionForm
                    task={reviewTaskToComplete}
                    operation={operation}
                    onClose={() => setIsReviewFormOpen(false)}
                    onSave={handleSaveReview}
                />
            )}
            {ruleToEdit && (
                <Modal isOpen={true} onClose={() => setRuleToEdit(null)} title="Editar Regra de Tarefa">
                    <TaskRuleForm
                        onClose={() => setRuleToEdit(null)}
                        onSave={handleUpdateRule}
                        initialData={ruleToEdit}
                    />
                </Modal>
            )}
            {ruleToDelete && (
                 <Modal
                    isOpen={true}
                    onClose={() => setRuleToDelete(null)}
                    title={`Deletar Regra: ${ruleToDelete.name}`}
                >
                    <div className="text-center">
                        <p className="text-lg text-gray-700 mb-6">
                        Você tem certeza que deseja deletar esta regra de tarefa?
                        </p>
                        <div className="flex justify-center gap-4">
                        <button
                            onClick={() => setRuleToDelete(null)}
                            className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleConfirmDeleteRule}
                            className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
                        >
                            Confirmar Deleção
                        </button>
                        </div>
                    </div>
                </Modal>
            )}
            {taskToEdit && (
                 <Modal isOpen={true} onClose={() => setTaskToEdit(null)} title="Editar Tarefa">
                    <AdHocTaskForm
                        onClose={() => setTaskToEdit(null)}
                        onSave={handleSaveEditedTask}
                        initialTask={taskToEdit}
                    />
                </Modal>
            )}
             {taskToDelete && (
                 <Modal
                    isOpen={true}
                    onClose={() => setTaskToDelete(null)}
                    title={`Deletar Tarefa: ${taskToDelete.ruleName}`}
                >
                    <div className="text-center">
                        <p className="text-lg text-gray-700 mb-6">
                        Você tem certeza que deseja deletar esta tarefa? Esta ação não pode ser desfeita.
                        </p>
                        <div className="flex justify-center gap-4">
                        <button
                            onClick={() => setTaskToDelete(null)}
                            className="px-6 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300"
                        >
                            Cancelar
                        </button>
                        <button
                            onClick={handleConfirmDeleteTask}
                            className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
                        >
                            Confirmar Deleção
                        </button>
                        </div>
                    </div>
                </Modal>
            )}


            <div className="bg-white p-6 rounded-lg shadow-lg">
                <div className="flex justify-between items-start mb-4">
                    <h2 className="text-2xl font-bold text-gray-800">{operation.name}</h2>
                    <button onClick={() => setIsWatchlistFormOpen(true)} className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-colors duration-200 ${watchlistColorClasses[currentWatchlistStatus]}`}>
                        <BellIcon className="w-5 h-5"/> Alterar Watchlist / Rating
                    </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <InfoCard title="Área">{operation.area}</InfoCard>
                    <InfoCard title="Projetos">{operation.projects.map(p => p.name).join(', ')}</InfoCard>
                    <InfoCard title="Garantias">{operation.guarantees.map(g => g.name).join(', ')}</InfoCard>
                    <InfoCard title="Segmento">{operation.segmento}</InfoCard>
                    <InfoCard title="Vencimento" highlight>{operation.maturityDate ? new Date(operation.maturityDate).toLocaleDateString('pt-BR') : 'N/A'}</InfoCard>
                </div>
            </div>

            <EventHistory 
                events={filteredEvents}
                onAddEvent={() => setIsEventFormOpen(true)}
                onEditEvent={handleOpenEditEventModal}
                onDownloadEvent={handleDownloadEvent}
                dateFilter={eventDateFilter}
                onDateFilterChange={setEventDateFilter}
                typeFilter={eventTypeFilter}
                onTypeFilterChange={setEventTypeFilter}
                personFilter={eventPersonFilter}
                onPersonFilterChange={setEventPersonFilter}
                uniqueEventTypes={uniqueEventTypes}
                uniqueRegisteredBy={uniqueRegisteredBy}
                expandedEventId={expandedEventId}
                onToggleExpand={setExpandedEventId}
                eventRefs={eventRefs}
            />

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                <div className="bg-white p-6 rounded-lg shadow-lg">
                    <h3 className="text-xl font-bold text-gray-700 mb-4">Execução de Tarefas</h3>

                    <div className="bg-gray-50 p-3 rounded-lg border border-gray-200 mb-4 grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
                        <div>
                            <label htmlFor="task-status-filter" className="text-sm font-medium text-gray-700">Status:</label>
                             <select id="task-status-filter" value={taskStatusFilter} onChange={e => setTaskStatusFilter(e.target.value as any)} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm">
                                <option value="all">Todas</option>
                                <option value="pending">Pendentes</option>
                                <option value="overdue">Atrasadas</option>
                            </select>
                        </div>
                        <div>
                             <label htmlFor="task-start-date" className="text-sm font-medium text-gray-700">Venc. De:</label>
                             <input type="date" id="task-start-date" value={taskDateFilter.start} onChange={e => setTaskDateFilter(prev => ({...prev, start: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                         <div>
                            <label htmlFor="task-end-date" className="text-sm font-medium text-gray-700">Venc. Até:</label>
                            <input type="date" id="task-end-date" value={taskDateFilter.end} onChange={e => setTaskDateFilter(prev => ({...prev, end: e.target.value}))} className="mt-1 block w-full rounded-md border-gray-300 shadow-sm sm:text-sm"/>
                        </div>
                    </div>

                    <div className="space-y-2 max-h-96 overflow-y-auto">
                       {activeTasks.map(task => (
                           <div key={task.id} className={`p-3 rounded-md flex justify-between items-center ${task.status === TaskStatus.OVERDUE ? 'bg-red-50 border-l-4 border-red-500' : 'bg-yellow-50 border-l-4 border-yellow-500'}`}>
                               <div>
                                   <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                   <p className={`text-sm ${task.status === TaskStatus.OVERDUE ? 'text-red-700' : 'text-yellow-700'}`}>
                                       Vencimento: {new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                   </p>
                               </div>
                               <div className="flex items-center gap-2">
                                    <button onClick={() => setTaskToEdit(task)} className="text-gray-400 hover:text-blue-600" title="Editar Tarefa">
                                        <PencilIcon className="w-5 h-5" />
                                    </button>
                                     <button onClick={() => setTaskToDelete(task)} className="text-gray-400 hover:text-red-600" title="Deletar Tarefa">
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => handleCompleteTaskClick(task)} className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 text-white rounded-md hover:bg-green-700 text-sm">
                                        <CheckCircleIcon className="w-4 h-4" /> Completar
                                    </button>
                               </div>
                           </div>
                       ))}
                        {activeTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa pendente para os filtros selecionados.</p>}
                    </div>
                </div>
                <div className="bg-white p-6 rounded-lg shadow-lg">
                     <div className="flex justify-between items-center mb-4">
                        <h3 className="text-xl font-bold text-gray-700">Regras de Tarefas</h3>
                         <button onClick={() => onOpenNewTaskModal(operation.id)} className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 text-sm">
                            <PlusCircleIcon className="w-5 h-5"/> Adicionar Tarefa
                        </button>
                    </div>
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {operation.taskRules.map(rule => (
                            <div key={rule.id} className="p-3 bg-gray-50 rounded-md flex justify-between items-center">
                                <div>
                                    <p className="font-semibold text-gray-800">{rule.name} <span className="text-xs font-normal text-white bg-blue-500 px-2 py-0.5 rounded-full">{rule.frequency}</span></p>
                                    <p className="text-sm text-gray-600">{rule.description}</p>
                                    <p className="text-xs text-gray-400 mt-1">
                                        {new Date(rule.startDate).toLocaleDateString('pt-BR')} até {new Date(rule.endDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                <div className="flex items-center gap-3">
                                    <button onClick={() => setRuleToEdit(rule)} className="text-gray-400 hover:text-blue-600" title="Editar Regra">
                                        <PencilIcon className="w-5 h-5" />
                                    </button>
                                    <button onClick={() => setRuleToDelete(rule)} className="text-gray-400 hover:text-red-600" title="Deletar Regra">
                                        <TrashIcon className="w-5 h-5" />
                                    </button>
                                </div>
                            </div>
                        ))}
                        {operation.taskRules.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma regra de tarefa definida.</p>}
                    </div>
                </div>
            </div>
            <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Ratings e Sentimentos</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start">
                    <div className="space-y-3 max-h-96 overflow-y-auto">
                        {sortedHistory.length > 0 ? (
                            sortedHistory.map((entry, index, array) => {
                                const previousEntry = array[index + 1];
                                const opRatingChange = getRatingChange(entry.ratingOperation, previousEntry?.ratingOperation);
                                const groupRatingChange = getRatingChange(entry.ratingGroup, previousEntry?.ratingGroup);

                                return (
                                    <div key={entry.id} className="p-3 bg-gray-50 rounded-md grid grid-cols-4 gap-4 items-center">
                                        <div className="font-medium text-gray-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</div>
                                        <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                            <span className="text-xs text-gray-500">Op: </span>
                                            <RatingChangeIndicator change={opRatingChange} />
                                            {entry.ratingOperation}
                                        </div>
                                        <div className="text-sm text-gray-800 flex items-center gap-1.5">
                                            <span className="text-xs text-gray-500">Grupo: </span>
                                            <RatingChangeIndicator change={groupRatingChange} />
                                            {entry.ratingGroup}
                                        </div>
                                        <div className={`flex items-center gap-2 font-semibold text-sm ${entry.sentiment === 'Positivo' ? 'text-green-600' : entry.sentiment === 'Negativo' ? 'text-red-600' : 'text-gray-600'}`}>
                                            {entry.sentiment === 'Positivo' && <ArrowUpIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Neutro' && <ArrowRightIcon className="w-4 h-4" />}
                                            {entry.sentiment === 'Negativo' && <ArrowDownIcon className="w-4 h-4" />}
                                            {entry.sentiment}
                                        </div>
                                    </div>
                                );
                            })
                        ) : (
                            <p className="text-center text-gray-500 py-4">Nenhum histórico de rating para esta operação.</p>
                        )}
                    </div>
                    <div>
                        <RatingHistoryChart history={operation.ratingHistory} />
                    </div>
                </div>
            </div>
             <div className="bg-white p-6 rounded-lg shadow-lg">
                <h3 className="text-xl font-bold text-gray-700 mb-4">Histórico de Tarefas Concluídas</h3>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                    {completedTasks.map(task => {
                        const completionEvent = operation.events.find(e => e.completedTaskId === task.id);
                        return (
                            <div key={task.id} className="p-3 bg-green-50 rounded-md flex justify-between items-center border-l-4 border-green-500">
                                <div>
                                    <p className="font-semibold text-gray-800">{task.ruleName}</p>
                                    <p className="text-sm text-gray-600">
                                        Concluída em: {completionEvent ? new Date(completionEvent.date).toLocaleDateString('pt-BR') : new Date(task.dueDate).toLocaleDateString('pt-BR')}
                                    </p>
                                </div>
                                {completionEvent && (
                                    <button onClick={() => handleViewEventClick(task.id)} className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-md hover:bg-blue-700 text-sm">
                                        <EyeIcon className="w-4 h-4" /> Ver Evento
                                    </button>
                                )}
                            </div>
                        )
                    })}
                    {completedTasks.length === 0 && <p className="text-center text-gray-500 py-4">Nenhuma tarefa foi concluída ainda.</p>}
                </div>
            </div>
        </div>
    );
};

export default OperationDetail;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Import Event to resolve name collision with DOM Event type, and TaskStatus for enum usage.
import type { Operation, Task, TaskRule, Rating, Sentiment, Event } from './types';
import { Page, TaskStatus } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';
import CreditReviewsPage from './components/CreditReviewsPage';
import ReviewCompletionForm from './components/ReviewCompletionForm';
import Toast from './components/Toast';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [reviewModalState, setReviewModalState] = useState<{isOpen: boolean; task: Task | null}>({isOpen: false, task: null});
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{message: string; type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error') => {
      setToast({ message, type });
  };

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); 
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a operação');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        showToast('Operação adicionada com sucesso!', 'success');
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
        showToast('Erro ao adicionar operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];
    // Atualização otimista da UI
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });

      if (!response.ok) {
        let errorMsg = 'Falha ao salvar no Databricks.';
        try {
            const errorData = await response.json();
            errorMsg = errorData.error || errorMsg;
        } catch(e) { }
        throw new Error(errorMsg);
      }

      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
      showToast('Dados sincronizados com sucesso!', 'success');
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      setOperations(originalOperations);
      const errorMessage = error instanceof Error ? error.message : 'Erro na sincronização.';
      showToast(`Erro ao sincronizar: ${errorMessage}`, 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    const originalOperations = [...operations];
    setOperations(prev => prev.filter(op => op.id !== operationId));
    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }

      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
      showToast('Operação deletada com sucesso!', 'success');
    } catch (error) {
      console.error("Error deleting operation:", error);
      setOperations(originalOperations);
      showToast('Erro ao deletar a operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao deletar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations);
        showToast('Erro ao deletar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            const newAdHocRule: TaskRule = {
                id: Date.now(),
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                endDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks,
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao editar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations);
        showToast('Erro ao editar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
      const clickedTask = reviewModalState.task;
      if (!clickedTask) return;

      const operation = operations.find(op => op.id === clickedTask.operationId);
      if (!operation) return;

      const completionDate = data.event.date; // Data em que o usuário disse que concluiu

      const baseEventData = {
          date: completionDate,
          type: 'Revisão Periódica',
          description: data.event.description,
          registeredBy: data.event.registeredBy,
          nextSteps: data.event.nextSteps,
      };

      // BUSINESS LOGIC: "SANEAMENTO DE HISTÓRICO"
      // Ao concluir uma revisão, as regras Gerencial e Política daquela operação 
      // têm sua data de início movida para hoje (data de conclusão). 
      // Isso faz com que o passado seja esquecido e a contagem recomece.
      const reviewTaskNames = ['Revisão Gerencial', 'Revisão Política'];

      const updatedRules = operation.taskRules.map(rule => {
          if (reviewTaskNames.includes(rule.name)) {
              return {
                  ...rule,
                  startDate: completionDate // Empurra o início para a data da última conclusão
              };
          }
          return rule;
      });

      const eventToAdd: Event = {
          ...baseEventData,
          id: Date.now() + Math.random(),
          title: `Conclusão e Saneamento: ${clickedTask.ruleName}`,
          completedTaskId: clickedTask.id,
      };

      const newHistoryEntry = {
          id: Date.now() + 1,
          date: completionDate,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          watchlist: operation.watchlist,
          sentiment: data.sentiment,
          eventId: eventToAdd.id,
      };

      const updatedOperation = {
          ...operation,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          events: [...operation.events, eventToAdd],
          ratingHistory: [...operation.ratingHistory, newHistoryEntry],
          taskRules: updatedRules,
          // Deixamos o motor do Databricks recalcular as tarefas na volta do fetch.
          // Mas para UI otimista, limpamos as tarefas de revisão pendentes atuais:
          tasks: operation.tasks.filter(t => !reviewTaskNames.includes(t.ruleName) || t.status === TaskStatus.COMPLETED)
      };

      // Fechar modal imediatamente e salvar em background
      setReviewModalState({ isOpen: false, task: null });
      handleUpdateOperation(updatedOperation);
  };

  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados do Databricks...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return (
                <>
                    <OverdueOperationsHighlight
                        operations={operations}
                        onNavigate={handleNavigate}
                    />
                    <OverviewDashboard
                        operations={operations}
                        onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                        onAddOperation={handleAddOperation}
                        onOpenNewTaskModal={openNewTaskModal}
                        onDeleteOperation={handleDeleteOperation}
                    />
                </>
            );
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
            />;
        case Page.CREDIT_REVIEWS:
            return <CreditReviewsPage
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
                onCompleteReview={(task) => setReviewModalState({ isOpen: true, task })}
                apiUrl={API_BASE_URL}
                showToast={showToast}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      {reviewModalState.isOpen && reviewModalState.task && (
          <ReviewCompletionForm
              task={reviewModalState.task}
              operation={operations.find(op => op.id === reviewModalState.task!.operationId)!}
              onClose={() => setReviewModalState({ isOpen: false, task: null })}
              onSave={handleSaveReview}
          />
      )}
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <div className="flex items-center gap-4">
                  <h1 className="text-2xl font-bold text-gray-800">
                    CRM de Crédito Estruturado
                  </h1>
                  {isSyncing && (
                      <span className="flex items-center gap-2 text-xs font-semibold text-blue-600 bg-blue-50 px-2 py-1 rounded-full animate-pulse border border-blue-200">
                          <div className="w-2 h-2 bg-blue-600 rounded-full"></div>
                          Sincronizando Databricks...
                      </span>
                  )}
              </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Import Event to resolve name collision with DOM Event type, and TaskStatus for enum usage.
import type { Operation, Task, TaskRule, Rating, Sentiment, Event } from './types';
import { Page, TaskStatus } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';
import CreditReviewsPage from './components/CreditReviewsPage';
import ReviewCompletionForm from './components/ReviewCompletionForm';
import Toast from './components/Toast';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [reviewModalState, setReviewModalState] = useState<{isOpen: boolean; task: Task | null}>({isOpen: false, task: null});
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{message: string; type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error') => {
      setToast({ message, type });
  };

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); 
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a operação');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        showToast('Operação adicionada com sucesso!', 'success');
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
        showToast('Erro ao adicionar operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];
    // Atualização otimista da UI
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });

      if (!response.ok) {
        let errorMsg = 'Falha ao salvar no Databricks.';
        try {
            const errorData = await response.json();
            errorMsg = errorData.error || errorMsg;
        } catch(e) { }
        throw new Error(errorMsg);
      }

      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
      showToast('Dados sincronizados com sucesso!', 'success');
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      setOperations(originalOperations);
      const errorMessage = error instanceof Error ? error.message : 'Erro na sincronização.';
      showToast(`Erro ao sincronizar: ${errorMessage}`, 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    const originalOperations = [...operations];
    setOperations(prev => prev.filter(op => op.id !== operationId));
    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }

      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
      showToast('Operação deletada com sucesso!', 'success');
    } catch (error) {
      console.error("Error deleting operation:", error);
      setOperations(originalOperations);
      showToast('Erro ao deletar a operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao deletar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations);
        showToast('Erro ao deletar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            const newAdHocRule: TaskRule = {
                id: Date.now(),
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                endDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks,
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao editar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations);
        showToast('Erro ao editar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
      const clickedTask = reviewModalState.task;
      if (!clickedTask) return;

      const operation = operations.find(op => op.id === clickedTask.operationId);
      if (!operation) return;

      const actualCompletionDate = data.event.date; // Data da conclusão (hoje ou conforme form)
      const expectedTaskDate = clickedTask.dueDate; // Data original da tarefa (01/03/2025)

      const baseEventData = {
          // PONTO 1: O evento é registrado na data em que a revisão era ESPERADA
          date: expectedTaskDate,
          type: 'Revisão Periódica',
          description: data.event.description,
          registeredBy: data.event.registeredBy,
          nextSteps: data.event.nextSteps,
      };

      // PONTO 2: O ciclo de tarefas é reiniciado a partir da data de conclusão REAL
      // Isso garante que a próxima revisão seja Hoje + Frequência
      const reviewTaskNames = ['Revisão Gerencial', 'Revisão Política'];

      const updatedRules = operation.taskRules.map(rule => {
          if (reviewTaskNames.includes(rule.name)) {
              return {
                  ...rule,
                  startDate: actualCompletionDate // Reinicia o ciclo a partir da conclusão real
              };
          }
          return rule;
      });

      const eventToAdd: Event = {
          ...baseEventData,
          id: Date.now() + Math.random(),
          title: `Conclusão: ${clickedTask.ruleName}`, // Sem menção a saneamento
          completedTaskId: clickedTask.id,
      };

      const newHistoryEntry = {
          id: Date.now() + 1,
          date: actualCompletionDate,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          watchlist: operation.watchlist,
          sentiment: data.sentiment,
          eventId: eventToAdd.id,
      };

      const updatedOperation = {
          ...operation,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          events: [...operation.events, eventToAdd],
          ratingHistory: [...operation.ratingHistory, newHistoryEntry],
          taskRules: updatedRules,
          // Limpamos tarefas pendentes de revisão para a UI otimista
          tasks: operation.tasks.filter(t => !reviewTaskNames.includes(t.ruleName) || t.status === TaskStatus.COMPLETED)
      };

      // Fechar modal imediatamente e salvar em background
      setReviewModalState({ isOpen: false, task: null });
      handleUpdateOperation(updatedOperation);
  };

  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados do Databricks...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return (
                <>
                    <OverdueOperationsHighlight
                        operations={operations}
                        onNavigate={handleNavigate}
                    />
                    <OverviewDashboard
                        operations={operations}
                        onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                        onAddOperation={handleAddOperation}
                        onOpenNewTaskModal={openNewTaskModal}
                        onDeleteOperation={handleDeleteOperation}
                    />
                </>
            );
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
            />;
        case Page.CREDIT_REVIEWS:
            return <CreditReviewsPage
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
                onCompleteReview={(task) => setReviewModalState({ isOpen: true, task })}
                apiUrl={API_BASE_URL}
                showToast={showToast}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      {reviewModalState.isOpen && reviewModalState.task && (
          <ReviewCompletionForm
              task={reviewModalState.task}
              operation={operations.find(op => op.id === reviewModalState.task!.operationId)!}
              onClose={() => setReviewModalState({ isOpen: false, task: null })}
              onSave={handleSaveReview}
          />
      )}
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <div className="flex items-center gap-4">
                  <h1 className="text-2xl font-bold text-gray-800">
                    CRM de Crédito Estruturado
                  </h1>
                  {isSyncing && (
                      <span className="flex items-center gap-2 text-xs font-semibold text-blue-600 bg-blue-50 px-2 py-1 rounded-full animate-pulse border border-blue-200">
                          <div className="w-2 h-2 bg-blue-600 rounded-full"></div>
                          Sincronizando Databricks...
                      </span>
                  )}
              </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import type { Task, Operation, Event, Rating, Sentiment } from '../types';
import { ratingOptions, Sentiment as SentimentEnum } from '../types';
import Modal from './Modal';
import { Label, Input, Select, Textarea } from './UI';

interface ReviewCompletionFormProps {
  task: Task;
  operation: Operation;
  onClose: () => void;
  onSave: (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => void;
}

const ReviewCompletionForm: React.FC<ReviewCompletionFormProps> = ({ task, operation, onClose, onSave }) => {
  const [completionDate, setCompletionDate] = useState(new Date().toISOString().split('T')[0]);
  const [ratingOp, setRatingOp] = useState(operation.ratingOperation);
  const [ratingGroup, setRatingGroup] = useState(operation.ratingGroup);
  const [sentiment, setSentiment] = useState<Sentiment>(SentimentEnum.NEUTRO);
  const [description, setDescription] = useState('');
  const [nextSteps, setNextSteps] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const event: Omit<Event, 'id'> = {
      // Esta data será usada como âncora para reiniciar o ciclo das regras recorrentes
      date: new Date(completionDate + 'T12:00:00').toISOString(),
      type: 'Revisão Periódica',
      title: `Conclusão: ${task.ruleName}`,
      description,
      registeredBy: operation.responsibleAnalyst,
      nextSteps,
    };

    onSave({ event, ratingOp, ratingGroup, sentiment });
  };

  return (
    <Modal isOpen={true} onClose={onClose} title={`Concluir ${task.ruleName}: ${operation.name}`}>
      <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-md text-sm text-blue-800">
        <p><strong>Nota:</strong> O evento histórico será registrado na data original ({new Date(task.dueDate).toLocaleDateString('pt-BR')}). A data selecionada abaixo definirá o início do <strong>próximo ciclo</strong> de revisões.</p>
      </div>
      <form onSubmit={handleSubmit} className="space-y-4">

        <div>
            <Label htmlFor="review-completion-date">Data da Conclusão Real</Label>
            <Input id="review-completion-date" type="date" value={completionDate} onChange={e => setCompletionDate(e.target.value)} required />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
                <Label htmlFor="review-rating-op">Rating Operação</Label>
                <Select id="review-rating-op" value={ratingOp} onChange={e => setRatingOp(e.target.value as Rating)}>
                    {ratingOptions.map(r => <option key={r} value={r}>{r}</option>)}
                </Select>
            </div>
            <div>
                <Label htmlFor="review-rating-group">Rating Grupo</Label>
                <Select id="review-rating-group" value={ratingGroup} onChange={e => setRatingGroup(e.target.value as Rating)}>
                    {ratingOptions.map(r => <option key={r} value={r}>{r}</option>)}
                </Select>
            </div>
            <div>
                <Label htmlFor="review-sentiment">Sentimento</Label>
                <Select id="review-sentiment" value={sentiment} onChange={e => setSentiment(e.target.value as Sentiment)}>
                    {Object.values(SentimentEnum).map(s => <option key={s} value={s}>{s}</option>)}
                </Select>
            </div>
        </div>

        <div>
            <Label htmlFor="review-description">Resumo da Revisão</Label>
            <Textarea id="review-description" value={description} onChange={e => setDescription(e.target.value)} rows={4} required placeholder="Descreva os principais pontos analisados..." />
        </div>
        <div>
            <Label htmlFor="review-next-steps">Próximos Passos</Label>
            <Textarea id="review-next-steps" value={nextSteps} onChange={e => setNextSteps(e.target.value)} rows={2} />
        </div>

        <div className="flex justify-end gap-4 pt-4">
          <button type="button" onClick={onClose} className="px-4 py-2 bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300" disabled={isSubmitting}>Cancelar</button>
          <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 disabled:bg-green-400" disabled={isSubmitting}>
            {isSubmitting ? 'Processando...' : 'Concluir e Salvar'}
            </button>
        </div>
      </form>
    </Modal>
  );
};

export default ReviewCompletionForm;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
// FIX: Import Event to resolve name collision with DOM Event type, and TaskStatus for enum usage.
import type { Operation, Task, TaskRule, Rating, Sentiment, Event } from './types';
import { Page, TaskStatus } from './types';
import OverviewDashboard from './components/OverviewDashboard';
import OperationDetail from './components/OperationDetail';
import TasksPage from './components/TasksPage';
import Sidebar from './components/Sidebar';
import OverdueOperationsHighlight from './components/OverdueOperationsHighlight';
import NewTaskModal from './components/NewTaskModal';
import BackendError from './components/BackendError';
import AuditLogPage from './components/AuditLogPage';
import WatchlistPage from './components/WatchlistPage';
import CreditReviewsPage from './components/CreditReviewsPage';
import ReviewCompletionForm from './components/ReviewCompletionForm';
import Toast from './components/Toast';

const API_BASE_URL = 'https://crmcri-flask.onrender.com';

const App: React.FC = () => {
  const [operations, setOperations] = useState<Operation[]>([]);
  const [currentPage, setCurrentPage] = useState<Page>(Page.OVERVIEW);
  const [selectedOperationId, setSelectedOperationId] = useState<number | null>(null);
  const [newTaskModalState, setNewTaskModalState] = useState<{isOpen: boolean; operationId?: number}>({ isOpen: false });
  const [reviewModalState, setReviewModalState] = useState<{isOpen: boolean; task: Task | null}>({isOpen: false, task: null});
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toast, setToast] = useState<{message: string; type: 'success' | 'error'} | null>(null);

  const showToast = (message: string, type: 'success' | 'error') => {
      setToast({ message, type });
  };

  const fetchOperations = useCallback(async () => {
    setIsLoading(true);
    setError(null); 
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations`, { credentials: 'include' });
      if (!response.ok) {
        throw new Error(`O servidor respondeu com o status: ${response.status}`);
      }
      const data: Operation[] = await response.json();
      setOperations(data);
    } catch (error) {
      console.error("Error fetching operations:", error);
      if (error instanceof Error) {
        setError(error.message);
      } else {
        setError("Ocorreu um erro de rede desconhecido.");
      }
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchOperations();
  }, [fetchOperations]);

  const allTasks = useMemo(() => {
    return operations.flatMap(op => op.tasks || []);
  }, [operations]);

  const handleNavigate = (page: Page, operationId?: number) => {
    setCurrentPage(page);
    setSelectedOperationId(operationId ?? null);
  };

  const handleAddOperation = async (newOperationData: any) => {
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/operations`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(newOperationData),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao salvar a operação');
        const savedOperation = await response.json();
        setOperations(prev => [ ...prev, savedOperation ]);
        showToast('Operação adicionada com sucesso!', 'success');
        handleNavigate(Page.DETAIL, savedOperation.id);
    } catch (error) {
        console.error("Error adding operation:", error);
        showToast('Erro ao adicionar operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleUpdateOperation = async (updatedOperation: Operation) => {
    const originalOperations = [...operations];
    // Atualização otimista da UI
    setOperations(prev => 
      prev.map(op => op.id === updatedOperation.id ? updatedOperation : op)
    );

    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${updatedOperation.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedOperation),
        credentials: 'include'
      });

      if (!response.ok) {
        let errorMsg = 'Falha ao salvar no Databricks.';
        try {
            const errorData = await response.json();
            errorMsg = errorData.error || errorMsg;
        } catch(e) { }
        throw new Error(errorMsg);
      }

      const returnedOperation = await response.json();
      setOperations(prev => 
        prev.map(op => op.id === returnedOperation.id ? returnedOperation : op)
      );
      showToast('Dados sincronizados com sucesso!', 'success');
    } catch (error) {
      console.error("Error updating operation, rolling back UI:", error);
      setOperations(originalOperations);
      const errorMessage = error instanceof Error ? error.message : 'Erro na sincronização.';
      showToast(`Erro ao sincronizar: ${errorMessage}`, 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteOperation = async (operationId: number) => {
    const originalOperations = [...operations];
    setOperations(prev => prev.filter(op => op.id !== operationId));
    setIsSyncing(true);
    try {
      const response = await fetch(`${API_BASE_URL}/api/operations/${operationId}`, {
        method: 'DELETE',
        credentials: 'include'
      });
      if (!response.ok) {
        throw new Error('Falha ao deletar a operação');
      }

      if (selectedOperationId === operationId) {
        handleNavigate(Page.OVERVIEW);
      }
      showToast('Operação deletada com sucesso!', 'success');
    } catch (error) {
      console.error("Error deleting operation:", error);
      setOperations(originalOperations);
      showToast('Erro ao deletar a operação.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleDeleteTask = async (task: Task) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            return {
                ...op,
                tasks: op.tasks.filter(t => t.id !== task.id)
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
        const response = await fetch(`${API_BASE_URL}/api/tasks/delete`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ taskId: task.id, operationId: task.operationId, responsibleAnalyst: operations.find(o=>o.id === task.operationId)?.responsibleAnalyst }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao deletar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error deleting task:", error);
        setOperations(originalOperations);
        showToast('Erro ao deletar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const handleEditTask = async (task: Task, updates: { name: string, dueDate: string }) => {
    const originalOperations = [...operations];
    setOperations(prevOps => prevOps.map(op => {
        if (op.id === task.operationId) {
            const filteredTasks = op.tasks.filter(t => t.id !== task.id);
            const newAdHocRule: TaskRule = {
                id: Date.now(),
                name: updates.name,
                frequency: 'Pontual',
                startDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                endDate: new Date(updates.dueDate + 'T12:00:00').toISOString(),
                description: `Tarefa editada a partir da tarefa original: ${task.ruleName} (ID: ${task.id})`,
            };
            return {
                ...op,
                tasks: filteredTasks,
                taskRules: [...op.taskRules, newAdHocRule]
            };
        }
        return op;
    }));
    setIsSyncing(true);
    try {
         const response = await fetch(`${API_BASE_URL}/api/tasks/edit`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                originalTaskId: task.id,
                operationId: task.operationId,
                updates: updates,
                responsibleAnalyst: operations.find(o => o.id === task.operationId)?.responsibleAnalyst
            }),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Falha ao editar a tarefa');

        const updatedOperation = await response.json();
        setOperations(prev => prev.map(op => op.id === updatedOperation.id ? updatedOperation : op));
    } catch (error) {
        console.error("Error editing task:", error);
        setOperations(originalOperations);
        showToast('Erro ao editar a tarefa.', 'error');
    } finally {
        setIsSyncing(false);
    }
  };

  const selectedOperation = useMemo(() => {
    return operations.find(op => op.id === selectedOperationId) || null;
  }, [operations, selectedOperationId]);

  const openNewTaskModal = (operationId?: number) => {
    setNewTaskModalState({ isOpen: true, operationId });
  };
  const closeNewTaskModal = () => {
    setNewTaskModalState({ isOpen: false });
  };

  const handleSaveReview = (data: { event: Omit<Event, 'id'>, ratingOp: Rating, ratingGroup: Rating, sentiment: Sentiment }) => {
      const clickedTask = reviewModalState.task;
      if (!clickedTask) return;

      const operation = operations.find(op => op.id === clickedTask.operationId);
      if (!operation) return;

      const actualCompletionDate = data.event.date; // Data da conclusão REAL
      const expectedTaskDate = new Date(clickedTask.dueDate); // Data original da tarefa

      // Formatação da data original: set/25
      const monthNames = ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"];
      const formattedOriginalDate = `${monthNames[expectedTaskDate.getMonth()]}/${expectedTaskDate.getFullYear().toString().slice(-2)}`;

      const baseEventData = {
          // PONTO 1: O evento agora é registrado na data de conclusão REAL
          date: actualCompletionDate,
          type: 'Revisão Periódica',
          description: data.event.description,
          registeredBy: data.event.registeredBy,
          nextSteps: data.event.nextSteps,
      };

      // PONTO 2: O ciclo de tarefas é reiniciado a partir da data de conclusão REAL
      // Atualizamos AMBAS as regras para manter a paridade
      const reviewTaskNames = ['Revisão Gerencial', 'Revisão Política'];

      const updatedRules = operation.taskRules.map(rule => {
          if (reviewTaskNames.includes(rule.name)) {
              return {
                  ...rule,
                  startDate: actualCompletionDate // Reinicia o ciclo a partir da conclusão real
              };
          }
          return rule;
      });

      const eventToAdd: Event = {
          ...baseEventData,
          id: Date.now() + Math.random(),
          // PONTO 2: Título com referência à data original
          title: `Conclusão: ${clickedTask.ruleName} - ${formattedOriginalDate}`,
          completedTaskId: clickedTask.id,
      };

      const newHistoryEntry = {
          id: Date.now() + 1,
          date: actualCompletionDate,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          watchlist: operation.watchlist,
          sentiment: data.sentiment,
          eventId: eventToAdd.id,
      };

      const updatedOperation = {
          ...operation,
          ratingOperation: data.ratingOp,
          ratingGroup: data.ratingGroup,
          events: [...operation.events, eventToAdd],
          ratingHistory: [...operation.ratingHistory, newHistoryEntry],
          taskRules: updatedRules,
          // Limpamos tarefas pendentes de revisão para a UI otimista
          tasks: operation.tasks.filter(t => !reviewTaskNames.includes(t.ruleName) || t.status === TaskStatus.COMPLETED)
      };

      // Fechar modal imediatamente e salvar em background
      setReviewModalState({ isOpen: false, task: null });
      handleUpdateOperation(updatedOperation);
  };

  const renderContent = () => {
    if (error) {
      return <BackendError errorMessage={error} onRetry={fetchOperations} />;
    }

    if (isLoading) {
      return (
        <div className="flex justify-center items-center h-full">
            <p className="text-xl text-gray-500 animate-pulse">Carregando dados do Databricks...</p>
        </div>
      );
    }

    switch (currentPage) {
        case Page.OVERVIEW:
            return (
                <>
                    <OverdueOperationsHighlight
                        operations={operations}
                        onNavigate={handleNavigate}
                    />
                    <OverviewDashboard
                        operations={operations}
                        onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                        onAddOperation={handleAddOperation}
                        onOpenNewTaskModal={openNewTaskModal}
                        onDeleteOperation={handleDeleteOperation}
                    />
                </>
            );
        case Page.DETAIL:
            return selectedOperation ? (
              <OperationDetail 
                operation={selectedOperation}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
              />
            ) : (
               <div>
                <h2 className="text-xl font-semibold mb-4">Operação não encontrada</h2>
                <p>Por favor, selecione uma operação válida na barra lateral.</p>
              </div>
            );
        case Page.TASKS:
            return <TasksPage
                operations={operations}
                allTasks={allTasks}
                onUpdateOperation={handleUpdateOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteTask={handleDeleteTask}
                onEditTask={handleEditTask}
            />;
        case Page.CREDIT_REVIEWS:
            return <CreditReviewsPage
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
                onCompleteReview={(task) => setReviewModalState({ isOpen: true, task })}
                apiUrl={API_BASE_URL}
                showToast={showToast}
            />;
        case Page.AUDIT_LOG:
            return <AuditLogPage apiUrl={API_BASE_URL} />;
        case Page.WATCHLIST:
            return <WatchlistPage 
                operations={operations}
                onUpdateOperation={handleUpdateOperation}
            />;
        default:
             return <OverviewDashboard
                operations={operations}
                onSelectOperation={(id) => handleNavigate(Page.DETAIL, id)}
                onAddOperation={handleAddOperation}
                onOpenNewTaskModal={openNewTaskModal}
                onDeleteOperation={handleDeleteOperation}
            />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => toast && setToast(null)} />}
      <NewTaskModal
        isOpen={newTaskModalState.isOpen}
        onClose={closeNewTaskModal}
        operations={operations}
        onUpdateOperation={handleUpdateOperation}
        preselectedOperationId={newTaskModalState.operationId}
      />
      {reviewModalState.isOpen && reviewModalState.task && (
          <ReviewCompletionForm
              task={reviewModalState.task}
              operation={operations.find(op => op.id === reviewModalState.task!.operationId)!}
              onClose={() => setReviewModalState({ isOpen: false, task: null })}
              onSave={handleSaveReview}
          />
      )}
      <Sidebar
        operations={operations}
        currentPage={currentPage}
        selectedOperationId={selectedOperationId}
        onNavigate={handleNavigate}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="bg-white shadow-sm z-10">
          <div className="container mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
              <div className="flex items-center gap-4">
                  <h1 className="text-2xl font-bold text-gray-800">
                    CRM de Crédito Estruturado
                  </h1>
                  {isSyncing && (
                      <span className="flex items-center gap-2 text-xs font-semibold text-blue-600 bg-blue-50 px-2 py-1 rounded-full animate-pulse border border-blue-200">
                          <div className="w-2 h-2 bg-blue-600 rounded-full"></div>
                          Sincronizando Databricks...
                      </span>
                  )}
              </div>
            </div>
          </div>
        </header>

        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-50">
          <div className="container mx-auto p-4 sm:p-6 lg:p-8">
            {renderContent()}
          </div>
        </main>
      </div>
    </div>
  );
};

